export default "):\\n    try:\\n        user_data = UserUpdate(last_login_at=datetime.now(timezone.utc))\\n        user = await get_user_by_id(db, user_id)\\n        return await update_user(user, user_data, db)\\n    except Exception as e:  # noqa: BLE001\\n        await logger.aerror(f\\\"Error updating user last login at: {e!s}\\\")\\n\\n\\nasync def get_all_superusers(db: AsyncSession) -> list[User]:\\n    \\\"\\\"\\\"Get all superuser accounts from the database.\\\"\\\"\\\"\\n    stmt = select(User).where(User.is_superuser == True)  # noqa: E712\\n    result = await db.exec(stmt)\\n    return list(result.all())\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/user/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e6a60c814f37382ad98d56251f4ff3c795bb5a88b58ec67c1e32279a743f7c3b\",\"content\":\"from datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING, Any\\nfrom uuid import UUID, uuid4\\n\\nfrom pydantic import BaseModel\\nfrom sqlalchemy import JSON, Column\\nfrom sqlmodel import Field, Relationship, SQLModel\\n\\nfrom langflow.schema.serialize import UUIDstr\\n\\nif TYPE_CHECKING:\\n    from langflow.services.database.models.api_key.model import ApiKey\\n    from langflow.services.database.models.deployment.model import Deployment\\n    from langflow.services.database.models.deployment_provider_account.model import DeploymentProviderAccount\\n    from langflow.services.database.models.file.model import File\\n    from langflow.services.database.models.flow.model import Flow\\n    from langflow.services.database.models.folder.model import Folder\\n    from langflow.services.database.models.variable.model import Variable\\n\\n\\nclass UserOptin(BaseModel):\\n    github_starred: bool = Field(default=False)\\n    dialog_dismissed: bool = Field(default=False)\\n    discord_clicked: bool = Field(default=False)\\n    # Add more opt-in actions as needed\\n\\n\\nclass User(SQLModel, table=True):  # type: ignore[call-arg]\\n    id: UUIDstr = Field(default_factory=uuid4, primary_key=True, unique=True)\\n    username: str = Field(index=True, unique=True)\\n    password: str = Field()\\n    profile_image: str | None = Field(default=None, nullable=True)\\n    is_active: bool = Field(default=False)\\n    is_superuser: bool = Field(default=False)\\n    create_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))\\n    updated_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))\\n    last_login_at: datetime | None = Field(default=None, nullable=True)\\n    api_keys: list[\\\"ApiKey\\\"] = Relationship(\\n        back_populates=\\\"user\\\",\\n        sa_relationship_kwargs={\\\"cascade\\\": \\\"delete\\\"},\\n    )\\n    store_api_key: str | None = Field(default=None, nullable=True)\\n    flows: list[\\\"Flow\\\"] = Relationship(back_populates=\\\"user\\\")\\n    # User is a secondary parent, so cascade=\\\"delete\\\" (no \\\"delete-orphan\\\").\\n    # Orphan management is handled by the owning models\\n    # (DeploymentProviderAccount, Folder) which use \\\"all, delete, delete-orphan\\\".\\n    deployment_provider_accounts: list[\\\"DeploymentProviderAccount\\\"] = Relationship(\\n        back_populates=\\\"user\\\",\\n        sa_relationship_kwargs={\\\"cascade\\\": \\\"delete\\\"},\\n    )\\n    deployments: list[\\\"Deployment\\\"] = Relationship(\\n        back_populates=\\\"user\\\",\\n        sa_relationship_kwargs={\\\"cascade\\\": \\\"delete\\\"},\\n    )\\n    variables: list[\\\"Variable\\\"] = Relationship(\\n        back_populates=\\\"user\\\",\\n        sa_relationship_kwargs={\\\"cascade\\\": \\\"delete\\\"},\\n    )\\n    files: list[\\\"File\\\"] = Relationship(\\n        back_populates=\\\"user\\\",\\n        sa_relationship_kwargs={\\\"cascade\\\": \\\"delete\\\"},\\n    )\\n    folders: list[\\\"Folder\\\"] = Relationship(\\n        back_populates=\\\"user\\\",\\n        sa_relationship_kwargs={\\\"cascade\\\": \\\"delete\\\"},\\n    )\\n    optins: dict[str, Any] | None = Field(\\n        sa_column=Column(JSON, default=lambda: UserOptin().model_dump(), nullable=True)\\n    )\\n\\n\\nclass UserCreate(SQLModel):\\n    username: str = Field()\\n    password: str = Field()\\n    optins: dict[str, Any] | None = Field(\\n        default={\\\"github_starred\\\": False, \\\"dialog_dismissed\\\": False, \\\"discord_clicked\\\": False}\\n    )\\n\\n\\nclass UserRead(SQLModel):\\n    id: UUID = Field(default_factory=uuid4)\\n    username: str = Field()\\n    profile_image: str | None = Field()\\n    store_api_key: str | None = Field(nullable=True)\\n    is_active: bool = Field()\\n    is_superuser: bool = Field()\\n    create_at: datetime = Field()\\n    updated_at: datetime = Field()\\n    last_login_at: datetime | None = Field(nullable=True)\\n    optins: dict[str, Any] | None = Field(default=None)\\n\\n\\nclass UserUpdate(SQLModel):\\n    username: str | None = None\\n    profile_image: str | None = None\\n    password: str | None = None\\n    is_active: bool | None = None\\n    is_superuser: bool | None = None\\n    last_login_at: datetime | None = None\\n    optins: dict[str, Any] | None = None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/variable/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f725ff79fcb83644f952f178b28b91599fa38e589d630aa9edc22ec1e4a03a97\",\"content\":\"from .model import Variable, VariableCreate, VariableRead, VariableUpdate\\n\\n__all__ = [\\\"Variable\\\", \\\"VariableCreate\\\", \\\"VariableRead\\\", \\\"VariableUpdate\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/variable/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"815e5e2ba0b5fed20d1887e9292fb7f668d67d278f6fc51bfd12ea1e6a314238\",\"content\":\"from datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING\\nfrom uuid import UUID, uuid4\\n\\nfrom pydantic import ValidationInfo, field_validator\\nfrom sqlmodel import JSON, Column, DateTime, Field, Relationship, SQLModel, func\\n\\nfrom langflow.services.variable.constants import CREDENTIAL_TYPE\\n\\nif TYPE_CHECKING:\\n    from langflow.services.database.models.user.model import User\\n\\n\\ndef utc_now():\\n    return datetime.now(timezone.utc)\\n\\n\\nclass VariableBase(SQLModel):\\n    name: str = Field(description=\\\"Name of the variable\\\")\\n    value: str = Field(description=\\\"Encrypted value of the variable\\\")\\n    default_fields: list[str] | None = Field(sa_column=Column(JSON))\\n    type: str | None = Field(None, description=\\\"Type of the variable\\\")\\n\\n\\nclass Variable(VariableBase, table=True):  # type: ignore[call-arg]\\n    id: UUID | None = Field(\\n        default_factory=uuid4,\\n        primary_key=True,\\n        description=\\\"Unique ID for the variable\\\",\\n    )\\n    # name is unique per user\\n    created_at: datetime | None = Field(\\n        default=None,\\n        sa_column=Column(DateTime(timezone=True), server_default=func.now(), nullable=True),\\n        description=\\\"Creation time of the variable\\\",\\n    )\\n    updated_at: datetime | None = Field(\\n        default=None,\\n        sa_column=Column(DateTime(timezone=True), nullable=True),\\n        description=\\\"Last update time of the variable\\\",\\n    )\\n    is_environment_managed: bool | None = Field(\\n        default=None,\\n        nullable=True,\\n        description=\\\"True for environment imports, False for user overrides, None for legacy rows\\\",\\n    )\\n    default_fields: list[str] | None = Field(sa_column=Column(JSON))\\n    # foreign key to user table\\n    user_id: UUID = Field(description=\\\"User ID associated with this variable\\\", foreign_key=\\\"user.id\\\")\\n    user: \\\"User\\\" = Relationship(back_populates=\\\"variables\\\")\\n\\n\\nclass VariableCreate(VariableBase):\\n    created_at: datetime | None = Field(default_factory=utc_now, description=\\\"Creation time of the variable\\\")\\n\\n\\nclass VariableRead(SQLModel):\\n    id: UUID\\n    name: str | None = Field(None, description=\\\"Name of the variable\\\")\\n    type: str | None = Field(None, description=\\\"Type of the variable\\\")\\n    value: str | None = Field(None, description=\\\"Encrypted value of the variable\\\")\\n    has_value: bool = Field(\\n        default=False,\\n        description=\\\"Whether the variable has a non-empty stored value without exposing credential contents\\\",\\n    )\\n    default_fields: list[str] | None = Field(None, description=\\\"Default fields for the variable\\\")\\n    is_owner: bool = Field(default=False, description=\\\"Whether the caller owns this variable\\\")\\n    can_manage_shares: bool = Field(\\n        default=False,\\n        description=\\\"Whether the caller may open share administration for this variable\\\",\\n    )\\n    validation_error: str | None = Field(\\n        None, description=\\\"Validation error message if this is a model provider credential with an invalid key\\\"\\n    )\\n    is_valid: bool | None = Field(\\n        None, description=\\\"Whether this model provider credential has a valid key (None if not a provider credential)\\\"\\n    )\\n\\n    @field_validator(\\\"value\\\")\\n    @classmethod\\n    def validate_value(cls, value: str, info: ValidationInfo):\\n        if info.data.get(\\\"type\\\") == CREDENTIAL_TYPE:\\n            return None\\n        return value\\n\\n\\nclass VariableUpdate(SQLModel):\\n    id: UUID  # Include the ID for updating\\n    name: str | None = Field(None, description=\\\"Name of the variable\\\")\\n    value: str | None = Field(None, description=\\\"Encrypted value of the variable\\\")\\n    default_fields: list[str] | None = Field(None, description=\\\"Default fields for the variable\\\")\\n    type: str | None = Field(None, description=\\\"Type of the variable\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/vertex_builds/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7c75a39939306f884d8108d9c11f6afd7c1d7588b170411ec09c2ab6d109ae02\",\"content\":\"from .model import VertexBuildTable\\n\\n__all__ = [\\\"VertexBuildTable\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/vertex_builds/crud.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7b797ab1f4a5501cf3a4b83f0480f375059619a9a1b033143b70b770479dc48a\",\"content\":\"from uuid import UUID\\n\\nfrom sqlmodel import col, delete, func, select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.vertex_builds.model import VertexBuildBase, VertexBuildTable\\nfrom langflow.services.deps import get_settings_service\\n\\n\\nasync def get_vertex_builds_by_flow_id(\\n    db: AsyncSession,\\n    flow_id: UUID,\\n    user_id: UUID,\\n    limit: int | None = 1000,\\n) -> list[VertexBuildTable]:\\n    \\\"\\\"\\\"Get the most recent vertex builds for a given flow ID.\\n\\n    This function retrieves vertex builds associated with a specific flow, ordered by timestamp.\\n    It uses a subquery to get the latest timestamp for each build ID to ensure we get the most\\n    recent versions.\\n\\n    Args:\\n        db (AsyncSession): The database session for executing queries.\\n        flow_id (UUID): The unique identifier of the flow to get builds for. Can be string or UUID.\\n        limit (int | None, optional): Maximum number of builds to return. Defaults to 1000.\\n        user_id (UUID): Results are restricted to flows owned by this user.\\n\\n    Returns:\\n        list[VertexBuildTable]: List of vertex builds, ordered chronologically by timestamp.\\n\\n    Note:\\n        If flow_id is provided as a string, it will be converted to UUID automatically.\\n    \\\"\\\"\\\"\\n    if isinstance(flow_id, str):\\n        flow_id = UUID(flow_id)\\n    subquery = (\\n        select(VertexBuildTable.id, func.max(VertexBuildTable.timestamp).label(\\\"max_timestamp\\\"))\\n        .where(VertexBuildTable.flow_id == flow_id)\\n        .group_by(VertexBuildTable.id)\\n        .subquery()\\n    )\\n    stmt = (\\n        select(VertexBuildTable)\\n        .join(\\n            subquery, (VertexBuildTable.id == subquery.c.id) & (VertexBuildTable.timestamp == subquery.c.max_timestamp)\\n        )\\n        .where(VertexBuildTable.flow_id == flow_id)\\n        .order_by(col(VertexBuildTable.timestamp))\\n        .limit(limit)\\n    )\\n\\n    stmt = stmt.join(Flow, VertexBuildTable.flow_id == Flow.id).where(Flow.user_id == user_id)\\n\\n    builds = await db.exec(stmt)\\n    return list(builds)\\n\\n\\nasync def log_vertex_build(\\n    db: AsyncSession,\\n    vertex_build: VertexBuildBase,\\n    *,\\n    max_builds_to_keep: int | None = None,\\n    max_builds_per_vertex: int | None = None,\\n) -> VertexBuildTable:\\n    \\\"\\\"\\\"Log a vertex build and maintain build history within specified limits.\\n\\n    This function performs a series of operations in a single transaction:\\n    1. Inserts the new build record\\n    2. Enforces per-vertex build limit by removing older builds\\n    3. Enforces global build limit across all vertices\\n    4. Commits the transaction\\n\\n    Args:\\n        db (AsyncSession): The database session for executing queries.\\n        vertex_build (VertexBuildBase): The vertex build data to log.\\n        max_builds_to_keep (int | None, optional): Maximum number of builds to keep globally.\\n            If None, uses system settings.\\n        max_builds_per_vertex (int | None, optional): Maximum number of builds to keep per vertex.\\n            If None, uses system settings.\\n\\n    Returns:\\n        VertexBuildTable: The newly created vertex build record.\\n\\n    Raises:\\n        IntegrityError: If there's a database constraint violation.\\n        Exception: For any other database-related errors.\\n\\n    Note:\\n        The function uses a transaction to ensure atomicity of all operations.\\n        If any operation fails, all changes are rolled back.\\n    \\\"\\\"\\\"\\n    table = VertexBuildTable(**vertex_build.model_dump())\\n\\n    try:\\n        settings = get_settings_service().settings\\n        max_global = max_builds_to_keep or settings.max_vertex_builds_to_keep\\n        max_per_vertex = max_builds_per_vertex or settings.max_vertex_builds_per_vertex\\n\\n        # 1) Insert and flush the new build so queries can see it\\n        db.add(table)\\n        await db.flush()\\n\\n        # 2) Delete older builds for this vertex, keeping newest max_per_vertex\\n        keep_vertex_subq = (\\n            select(VertexBuildTable.build_id)\\n            .where(\\n                VertexBuildTable.flow_id == vertex_build.flow_id,\\n                VertexBuildTable.id == vertex_build.id,\\n            )\\n            .order_by(col(VertexBuildTable.timestamp).desc(), col(VertexBuildTable.build_id).desc())\\n            .limit(max_per_vertex)\\n        )\\n        delete_vertex_older = delete(VertexBuildTable).where(\\n            VertexBuildTable.flow_id == vertex_build.flow_id,\\n            VertexBuildTable.id == vertex_build.id,\\n            col(VertexBuildTable.build_id).not_in(keep_vertex_subq),\\n        )\\n        await db.exec(delete_vertex_older)\\n\\n        # 3) Delete older builds globally, keeping newest max_global\\n        keep_global_subq = (\\n            select(VertexBuildTable.build_id)\\n            .order_by(col(VertexBuildTable.timestamp).desc(), col(VertexBuildTable.build_id).desc())\\n            .limit(max_global)\\n        )\\n        delete_global_older = delete(VertexBuildTable).where(col(VertexBuildTable.build_id).not_in(keep_global_subq))\\n        await db.exec(delete_global_older)\\n\\n        # 4) Commit transaction\\n        await db.commit()\\n\\n    except Exception:\\n        await db.rollback()\\n        raise\\n\\n    return table\\n\\n\\nasync def delete_vertex_builds_by_flow_id(db: AsyncSession, flow_id: UUID, user_id: UUID) -> None:\\n    \\\"\\\"\\\"Delete all vertex builds associated with a specific flow ID.\\n\\n    Args:\\n        db (AsyncSession): The database session for executing queries.\\n        flow_id (UUID): The unique identifier of the flow whose builds should be deleted.\\n        user_id (UUID): Deletion is restricted to flows owned by this user.\\n\\n    Note:\\n        This operation is permanent and cannot be undone. Use with caution.\\n        The function commits the transaction automatically.\\n    \\\"\\\"\\\"\\n    owned_flow_subquery = select(Flow.id).where(Flow.id == flow_id, Flow.user_id == user_id)\\n    stmt = delete(VertexBuildTable).where(col(VertexBuildTable.flow_id).in_(owned_flow_subquery))\\n    await db.exec(stmt)\\n\\n\\nasync def delete_vertex_builds_by_flow_id_unchecked(db: AsyncSession, flow_id: UUID) -> None:\\n    \\\"\\\"\\\"Delete all vertex builds for a flow without ownership checks.\\n\\n    This helper exists for internal cleanup paths (e.g. test teardown)\\n    where no authenticated user context is available.\\n    \\\"\\\"\\\"\\n    stmt = delete(VertexBuildTable).where(VertexBuildTable.flow_id == flow_id)\\n    await db.exec(stmt)\\n\\n\\nasync def get_vertex_builds_by_job_id(db: AsyncSession, job_id: str | UUID) -> list[VertexBuildTable]:\\n    \\\"\\\"\\\"Get all vertex builds associated with a specific job ID.\\n\\n    Args:\\n        db (AsyncSession): The database session for executing queries.\\n        job_id (str | UUID): The unique identifier of the job to get builds for.\\n\\n    Returns:\\n        list[VertexBuildTable]: List of vertex builds, ordered chronologically by timestamp.\\n    \\\"\\\"\\\"\\n    if isinstance(job_id, str):\\n        job_id = UUID(job_id)\\n\\n    stmt = select(VertexBuildTable).where(VertexBuildTable.job_id == job_id).order_by(col(VertexBuildTable.timestamp))\\n\\n    builds = await db.exec(stmt)\\n    return list(builds)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/models/vertex_builds/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a7c9eef82b61fcf07f2b71bfacda808bdb66619a5f16e2cef979f7876f06dcd2\",\"content\":\"from datetime import datetime, timezone\\nfrom uuid import UUID, uuid4\\n\\nfrom pydantic import BaseModel, field_serializer, field_validator\\nfrom sqlalchemy import Text\\nfrom sqlmodel import JSON, Column, Field, SQLModel\\n\\nfrom langflow.serialization.serialization import get_max_items_length, get_max_text_length, serialize\\n\\n\\nclass VertexBuildBase(SQLModel):\\n    timestamp: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))\\n    id: str = Field(nullable=False)\\n    data: dict | None = Field(default=None, sa_column=Column(JSON))\\n    artifacts: dict | None = Field(default=None, sa_column=Column(JSON))\\n    params: str | None = Field(default=None, sa_column=Column(Text, nullable=True))\\n    valid: bool = Field(nullable=False)\\n    flow_id: UUID = Field()\\n    job_id: UUID | None = Field(default=None, index=True)\\n\\n    # Needed for Column(JSON)\\n    class Config:\\n        arbitrary_types_allowed = True\\n\\n    @field_validator(\\\"flow_id\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_flow_id(cls, value):\\n        if value is None:\\n            return value\\n        if isinstance(value, str):\\n            value = UUID(value)\\n        return value\\n\\n    @field_serializer(\\\"timestamp\\\")\\n    @classmethod\\n    def serialize_timestamp(cls, value):\\n        if value.tzinfo is None:\\n            value = value.replace(tzinfo=timezone.utc)\\n        return value\\n\\n    @field_serializer(\\\"data\\\")\\n    def serialize_data(self, data) -> dict:\\n        \\\"\\\"\\\"Serializes the `data` field with enforced limits on text length and item count.\\n\\n        Returns:\\n            dict: The serialized representation of the data field.\\n        \\\"\\\"\\\"\\n        return serialize(data, max_length=get_max_text_length(), max_items=get_max_items_length())\\n\\n    @field_serializer(\\\"artifacts\\\")\\n    def serialize_artifacts(self, data) -> dict:\\n        \\\"\\\"\\\"Serializes the artifacts field, applying limits on text length and item count.\\n\\n        Returns:\\n            dict: The serialized artifacts dictionary with enforced size constraints.\\n        \\\"\\\"\\\"\\n        return serialize(data, max_length=get_max_text_length(), max_items=get_max_items_length())\\n\\n    @field_serializer(\\\"params\\\")\\n    def serialize_params(self, data) -> str:\\n        \\\"\\\"\\\"Serialize the `params` field to a string with enforced limits on text length and item count.\\n\\n        Returns:\\n            str: The serialized representation of the `params` data.\\n        \\\"\\\"\\\"\\n        return serialize(data, max_length=get_max_text_length(), max_items=get_max_items_length())\\n\\n\\nclass VertexBuildTable(VertexBuildBase, table=True):  # type: ignore[call-arg]\\n    __tablename__ = \\\"vertex_build\\\"\\n    build_id: UUID | None = Field(default_factory=uuid4, primary_key=True)\\n\\n\\nclass VertexBuildMapModel(BaseModel):\\n    vertex_builds: dict[str, list[VertexBuildTable]]\\n\\n    @classmethod\\n    def from_list_of_dicts(cls, vertex_build_dicts: list[VertexBuildTable]):\\n        vertex_build_map: dict[str, list[VertexBuildTable]] = {}\\n        for vertex_build in vertex_build_dicts:\\n            if vertex_build.id not in vertex_build_map:\\n                vertex_build_map[vertex_build.id] = []\\n            vertex_build_map[vertex_build.id].append(vertex_build)\\n        return cls(vertex_builds=vertex_build_map)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5dc4da8aba2a808b70296318173f7e20e7d133c10255ae131d49719869804bf1\",\"content\":\"from __future__ import annotations\\n\\nimport asyncio\\nimport os\\nimport re\\nimport sqlite3\\nimport sys\\nimport time\\nfrom contextlib import asynccontextmanager, contextmanager, nullcontext\\nfrom datetime import datetime, timezone\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING\\n\\nimport anyio\\nimport sqlalchemy as sa\\nfrom alembic import command, util\\nfrom alembic.config import Config\\nfrom lfx.log.logger import logger\\nfrom lfx.observability import instrument_database\\nfrom lfx.services.deps import session_scope\\nfrom sqlalchemy import event, inspect\\nfrom sqlalchemy.dialects import sqlite as dialect_sqlite\\nfrom sqlalchemy.engine import Engine, make_url\\nfrom sqlalchemy.exc import OperationalError\\nfrom sqlalchemy.ext.asyncio import AsyncEngine, async_sessionmaker, create_async_engine\\nfrom sqlmodel import SQLModel, select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession as SQLModelAsyncSession\\nfrom tenacity import retry, stop_after_attempt, wait_fixed\\n\\nfrom langflow.helpers.windows_postgres_helper import configure_windows_postgres_event_loop\\nfrom langflow.initial_setup.constants import STARTER_FOLDER_NAME\\nfrom langflow.services.base import Service\\nfrom langflow.services.database import models\\nfrom langflow.services.database.constants import (\\n    MIN_POSTGRESQL_MAJOR_VERSION,\\n    POSTGRESQL_VERSION_REQUIRED_MESSAGE,\\n)\\nfrom langflow.services.database.migration import get_current_alembic_heads\\nfrom langflow.services.database.models.user.crud import get_user_by_username\\nfrom langflow.services.database.session import NoopSession\\nfrom langflow.services.database.utils import Result, TableResults\\nfrom langflow.services.deps import get_settings_service\\nfrom langflow.services.utils import teardown_superuser\\n\\nif TYPE_CHECKING:\\n    from lfx.services.settings.service import SettingsService\\n\\n\\nclass UnsupportedPostgreSQLVersionError(Exception):\\n    \\\"\\\"\\\"Raised when the PostgreSQL version is below the minimum required.\\\"\\\"\\\"\\n\\n\\n_PG_VERSION_QUERY = sa.text(\\\"SELECT current_setting('server_version_num'), current_setting('server_version')\\\")\\n\\n# Stable namespace for the schema-migration advisory lock. The lock serializes\\n# concurrent ``alembic upgrade`` runs across workers so they do not race to\\n# CREATE TYPE / CREATE TABLE on a fresh database. Picked once and never changed\\n# so independent processes converge on the same lock; the value itself is\\n# arbitrary, just has to fit in a Postgres bigint and not collide with other\\n# advisory locks the application takes (currently none).\\n_MIGRATION_ADVISORY_LOCK_ID = 0x4C616E67666C6F77  # ASCII \\\"Langflow\\\"\\n_MIGRATION_LOCK_DEFAULT_TIMEOUT_S = 300.0\\n_MIGRATION_LOCK_POLL_INTERVAL_S = 2.0\\n\\n\\ndef _migration_lock_timeout_s() -> float:\\n    raw = os.getenv(\\\"LANGFLOW_MIGRATION_LOCK_TIMEOUT_S\\\")\\n    if raw is None:\\n        return _MIGRATION_LOCK_DEFAULT_TIMEOUT_S\\n    try:\\n        return float(raw)\\n    except ValueError:\\n        logger.warning(\\n            \\\"Ignoring invalid LANGFLOW_MIGRATION_LOCK_TIMEOUT_S=%r; falling back to %.0fs.\\\",\\n            raw,\\n            _MIGRATION_LOCK_DEFAULT_TIMEOUT_S,\\n        )\\n        return _MIGRATION_LOCK_DEFAULT_TIMEOUT_S\\n\\n\\ndef _acquire_migration_lock_or_raise(conn, lock_id: int) -> None:\\n    \\\"\\\"\\\"Acquire the advisory lock with a bounded wait, logging progress.\\n\\n    Blocking ``pg_advisory_lock`` has no upper bound and ``lock_timeout`` does\\n    not apply to advisory locks, so a worker hung mid-migration would silently\\n    block every other worker forever. Instead poll ``pg_try_advisory_lock`` with\\n    a configurable timeout and log when we're waiting, so operators see why\\n    boot is stuck.\\n    \\\"\\\"\\\"\\n    if conn.execute(sa.text(f\\\"SELECT pg_try_advisory_lock({lock_id})\\\")).scalar():\\n        return\\n\\n    timeout = _migration_lock_timeout_s()\\n    logger.info(\\n        \\\"Migration advisory lock %s held by another worker; waiting up to %.0fs.\\\",\\n        lock_id,\\n        timeout,\\n    )\\n    deadline = time.monotonic() + timeout\\n    while time.monotonic() < deadline:\\n        time.sleep(_MIGRATION_LOCK_POLL_INTERVAL_S)\\n        if conn.execute(sa.text(f\\\"SELECT pg_try_advisory_lock({lock_id})\\\")).scalar():\\n            logger.info(\\\"Acquired migration advisory lock %s after waiting.\\\", lock_id)\\n            return\\n\\n    msg = (\\n        f\\\"Could not acquire migration advisory lock {lock_id} within \\\"\\n        f\\\"{timeout:.0f}s. Another worker is likely hung mid-migration. \\\"\\n        \\\"Investigate the worker holding the lock or restart the deployment \\\"\\n        \\\"with a single worker so migrations can run cleanly. Override the \\\"\\n        \\\"wait via LANGFLOW_MIGRATION_LOCK_TIMEOUT_S (seconds) if your migration \\\"\\n        \\\"legitimately needs longer.\\\"\\n    )\\n    raise RuntimeError(msg)\\n\\n\\ndef _normalize_sync_postgres_url(database_url: str) -> str:\\n    \\\"\\\"\\\"Return a sync-driver Postgres URL from a possibly async one.\\n\\n    Strips the ``+asyncpg`` / ``+aiosqlite`` suffix and upgrades the legacy\\n    ``postgres://`` scheme to ``postgresql://`` so :func:`sa.create_engine`\\n    picks the default sync driver. Centralised so the advisory-lock helper and\\n    the table-creation lock path stay in sync with :func:`check_postgresql_version_sync`.\\n    \\\"\\\"\\\"\\n    sync_url = database_url\\n    if sync_url.startswith(\\\"postgres://\\\"):\\n        sync_url = \\\"postgresql://\\\" + sync_url.split(\\\"://\\\", 1)[1]\\n    for async_driver in (\\\"+asyncpg\\\", \\\"+aiosqlite\\\"):\\n        sync_url = sync_url.replace(async_driver, \\\"\\\")\\n    return sync_url\\n\\n\\n@contextmanager\\ndef _postgres_migration_lock(database_url: str):\\n    \\\"\\\"\\\"Hold a Postgres session-level advisory lock for the duration of the block.\\n\\n    Workers starting concurrently against a fresh PostgreSQL each call\\n    ``command.upgrade(\\\"head\\\")``; without coordination they race on\\n    ``CREATE TYPE`` / ``CREATE TABLE`` and the losers fail with\\n    ``UniqueViolation``. Holding a session-level advisory lock serialises the\\n    upgrade so only one worker mutates the schema at a time; the others wait\\n    here (bounded, with progress logging) and then find the schema already at\\n    head.\\n\\n    No-op for non-PostgreSQL URLs. SQLite has no advisory locks (and Langflow\\n    runs single-process on it anyway).\\n    \\\"\\\"\\\"\\n    if not database_url.startswith((\\\"postgresql\\\", \\\"postgres\\\")):\\n        yield\\n        return\\n\\n    engine = sa.create_engine(_normalize_sync_postgres_url(database_url))\\n    try:\\n        with engine.connect() as conn:\\n            logger.debug(\\\"Acquiring migration advisory lock %s\\\", _MIGRATION_ADVISORY_LOCK_ID)\\n            _acquire_migration_lock_or_raise(conn, _MIGRATION_ADVISORY_LOCK_ID)\\n            try:\\n                yield\\n            finally:\\n                logger.debug(\\\"Releasing migration advisory lock %s\\\", _MIGRATION_ADVISORY_LOCK_ID)\\n                # Session-level locks auto-release on connection close, but\\n                # explicit unlock keeps the connection reusable if alembic\\n                # internals ever hand us one back.\\n                conn.execute(sa.text(f\\\"SELECT pg_advisory_unlock({_MIGRATION_ADVISORY_LOCK_ID})\\\"))\\n    finally:\\n        engine.dispose()\\n\\n\\ndef _check_version_row(version_num_str: str, version_str: str) -> None:\\n    \\\"\\\"\\\"Raise ``UnsupportedPostgreSQLVersionError`` when the version is too old.\\\"\\\"\\\"\\n    if int(version_num_str) < MIN_POSTGRESQL_MAJOR_VERSION * 10000:\\n        msg = f\\\"Running PostgreSQL {version_str}. {POSTGRESQL_VERSION_REQUIRED_MESSAGE}\\\"\\n        logger.error(msg)\\n        raise UnsupportedPostgreSQLVersionError(msg)\\n\\n\\ndef check_postgresql_version_sync(database_url: str) -> None:\\n    \\\"\\\"\\\"Pre-flight check: verify PostgreSQL >= 15 using a synchronous connection.\\n\\n    Call this *before* starting uvicorn/gunicorn so a version mismatch\\n    results in a clean ``sys.exit(1)`` rather than a messy lifespan failure.\\n    Silently returns when the URL is not PostgreSQL.\\n    \\\"\\\"\\\"\\n    if not database_url.startswith((\\\"postgresql\\\", \\\"postgres\\\")):\\n        return\\n\\n    from sqlalchemy import create_engine\\n\\n    engine = create_engine(_normalize_sync_postgres_url(database_url))\\n    try:\\n        with engine.connect() as conn:\\n            row = conn.execute(_PG_VERSION_QUERY).fetchone()\\n            _check_version_row(*row)\\n    finally:\\n        engine.dispose()\\n\\n\\ndef get_sqlite_database_file_path(database_url: str) -> Path | None:\\n    \\\"\\\"\\\"Return the on-disk file path for a SQLite URL, or ``None`` when there is none.\\n\\n    Returns ``None`` for non-SQLite URLs and for in-memory SQLite databases\\n    (``sqlite://`` and ``sqlite:///:memory:``), which have no file on disk. The\\n    returned path is kept exactly as written in the URL (relative paths are *not*\\n    resolved) so callers can report it back to the user verbatim.\\n    \\\"\\\"\\\"\\n    if not database_url.startswith(\\\"sqlite\\\"):\\n        return None\\n    try:\\n        database = make_url(database_url).database\\n    except Exception:  # noqa: BLE001 - defensive: malformed URLs are handled elsewhere\\n        return None\\n    if not database or database == \\\":memory:\\\":\\n        return None\\n    return Path(database)\\n\\n\\ndef check_sqlite_database_path(database_url: str) -> None:\\n    \\\"\\\"\\\"Fail fast with an actionable message when a SQLite database cannot be opened.\\n\\n    SQLite does not create intermediate directories, and relative paths in\\n    ``LANGFLOW_DATABASE_URL`` are resolved by SQLAlchemy against the current\\n    working directory at connect time. When the resolved parent directory is\\n    missing the raw ``sqlite3.OperationalError`` (\\\"unable to open database file\\\")\\n    is opaque, so surface where Langflow actually tried to open the database and\\n    how a relative path was resolved. No-op for non-SQLite and in-memory URLs.\\n\\n    Note: this only improves diagnostics; it does not change which URLs are\\n    accepted nor create any directories. See issue #13634.\\n    \\\"\\\"\\\"\\n    db_path = get_sqlite_database_file_path(database_url)\\n    if db_path is None:\\n        return\\n\\n    resolved = db_path.resolve()\\n    logger.debug(f\\\"Using SQLite database at {resolved}\\\")\\n\\n    parent = resolved.parent\\n    if parent.exists():\\n        return\\n\\n    msg = (\\n        f\\\"Cannot open the SQLite database at '{resolved}': the parent directory \\\"\\n        f\\\"'{parent}' does not exist, and SQLite does not create intermediate \\\"\\n        f\\\"directories. \\\"\\n    )\\n    if db_path.is_absolute():\\n        msg += \\\"Create the directory before starting Langflow, or point LANGFLOW_DATABASE_URL at an existing path.\\\"\\n    else:\\n        msg += (\\n            f\\\"The relative path '{db_path}' from LANGFLOW_DATABASE_URL was resolved against the current working \\\"\\n            f\\\"directory ('{Path.cwd()}'). Set LANGFLOW_DATABASE_URL to an absolute path \\\"\\n            f\\\"(e.g. 'sqlite:///{resolved}'), or create the directory before starting Langflow.\\\"\\n        )\\n    raise ValueError(msg)\\n\\n\\nclass DatabaseService(Service):\\n    name = \\\"database_service\\\"\\n\\n    def __init__(self, settings_service: SettingsService):\\n        self._logged_pragma = False\\n        self.settings_service = settings_service\\n        if settings_service.settings.database_url is None:\\n            msg = \\\"No database URL provided\\\"\\n            raise ValueError(msg)\\n        self.database_url: str = settings_service.settings.database_url\\n\\n        configure_windows_postgres_event_loop(source=\\\"database_service\\\")\\n\\n        self._sanitize_database_url()\\n\\n        # This file is in langflow.services.database.manager.py\\n        # the ini is in langflow\\n        langflow_dir = Path(__file__).parent.parent.parent\\n        self.script_location = langflow_dir / \\\"alembic\\\"\\n        self.alembic_cfg_path = langflow_dir / \\\"alembic.ini\\\"\\n\\n        # register the event listener for sqlite as part of this class.\\n        # Using decorator will make the method not able to use self\\n        event.listen(Engine, \\\"connect\\\", self.on_connection)\\n        if self.settings_service.settings.database_connection_retry:\\n            self.engine = self._create_engine_with_retry()\\n        else:\\n            self.engine = self._create_engine()\\n        # Here rather than in the app factory: this is an AsyncEngine, and the instrumentor\\n        # patches the sync engine underneath it. Instrumenting globally instead (no engine\\n        # argument) attaches to pool events only, which yields a connect span per checkout and\\n        # not a single query span. Verified against a live backend: 13 connect spans and zero\\n        # db.statement for one API request.\\n        instrument_database(self.engine)\\n\\n        # Create async session maker for efficient session creation\\n        # This is the recommended SQLAlchemy 2.0+ pattern\\n        # IMPORTANT: Must use SQLModel's AsyncSession (not SQLAlchemy's) for exec() method\\n        self.async_session_maker = async_sessionmaker(\\n            self.engine,\\n            class_=SQLModelAsyncSession,  # SQLModel's AsyncSession with exec() support\\n            expire_on_commit=False,\\n        )\\n\\n        # Check if Alembic should log to stdout or a file.\\n        # If file, check if the provided path is absolute, cross-platform.\\n        alembic_log_file = self.settings_service.settings.alembic_log_file\\n        self.alembic_log_to_stdout = self.settings_service.settings.alembic_log_to_stdout\\n        if self.alembic_log_to_stdout:\\n            self.alembic_log_path = None\\n        elif Path(alembic_log_file).is_absolute():\\n            self.alembic_log_path = Path(alembic_log_file)\\n        else:\\n            # Resolve relative log paths against the writable runtime config\\n            # directory, not the installed package directory. The package dir is\\n            # read-only in hardened deployments (non-root containers, read-only\\n            # root filesystems, Kubernetes), where writing into it raises OSError\\n            # and crashes startup. config_dir is always writable (it defaults to\\n            # platformdirs' user cache dir and is created on startup).\\n            config_dir = getattr(self.settings_service.settings, \\\"config_dir\\\", None)\\n            base_dir = Path(config_dir) if config_dir else langflow_dir\\n            self.alembic_log_path = base_dir / alembic_log_file\\n\\n    async def initialize_alembic_log_file(self):\\n        log_path = self.alembic_log_path\\n        if self.alembic_log_to_stdout or log_path is None:\\n            return\\n        # Ensure the directory and file for the alembic log file exists. The\\n        # migration log is diagnostic-only, so a read-only filesystem (hardened\\n        # containers / Kubernetes) must never abort startup: warn and move on.\\n        try:\\n            await anyio.Path(log_path.parent).mkdir(parents=True, exist_ok=True)\\n            await anyio.Path(log_path).touch(exist_ok=True)\\n        except OSError as exc:\\n            await logger.awarning(\\n                f\\\"Could not initialize the Alembic migration log at '{log_path}' ({exc}). \\\"\\n                \\\"Migration output falls back to stdout. Set LANGFLOW_ALEMBIC_LOG_FILE to a writable path \\\"\\n                \\\"or LANGFLOW_ALEMBIC_LOG_TO_STDOUT=true to silence this warning.\\\"\\n            )\\n\\n    def reload_engine(self) -> None:\\n        self._sanitize_database_url()\\n        if self.settings_service.settings.database_connection_retry:\\n            self.engine = self._create_engine_with_retry()\\n        else:\\n            self.engine = self._create_engine()\\n\\n        self.async_session_maker = async_sessionmaker(\\n            self.engine,\\n            class_=SQLModelAsyncSession,\\n            expire_on_commit=False,\\n        )\\n\\n    def _sanitize_database_url(self):\\n        \\\"\\\"\\\"Create the engine for the database.\\\"\\\"\\\"\\n        url_components = self.database_url.split(\\\"://\\\", maxsplit=1)\\n\\n        driver = url_components[0]\\n\\n        if driver == \\\"sqlite\\\":\\n            driver = \\\"sqlite+aiosqlite\\\"\\n        elif driver in {\\\"postgresql\\\", \\\"postgres\\\"}:\\n            if driver == \\\"postgres\\\":\\n                logger.warning(\\n                    \\\"The postgres dialect in the database URL is deprecated. \\\"\\n                    \\\"Use postgresql instead. \\\"\\n                    \\\"To avoid this warning, update the database URL.\\\"\\n                )\\n            driver = \\\"postgresql+psycopg\\\"\\n\\n        self.database_url = f\\\"{driver}://{url_components[1]}\\\"\\n\\n    def _build_connection_kwargs(self):\\n        \\\"\\\"\\\"Build connection kwargs by merging deprecated settings with db_connection_settings.\\n\\n        Returns:\\n            dict: Connection kwargs with deprecated settings overriding db_connection_settings\\n        \\\"\\\"\\\"\\n        settings = self.settings_service.settings\\n        # Start with db_connection_settings as base\\n        connection_kwargs = settings.db_connection_settings.copy()\\n\\n        # Override individual settings if explicitly set\\n        if \\\"pool_size\\\" in settings.model_fields_set:\\n            logger.warning(\\\"pool_size is deprecated. Use db_connection_settings['pool_size'] instead.\\\")\\n            connection_kwargs[\\\"pool_size\\\"] = settings.pool_size\\n        if \\\"max_overflow\\\" in settings.model_fields_set:\\n            logger.warning(\\\"max_overflow is deprecated. Use db_connection_settings['max_overflow'] instead.\\\")\\n            connection_kwargs[\\\"max_overflow\\\"] = settings.max_overflow\\n\\n        return connection_kwargs\\n\\n    def _create_engine(self) -> AsyncEngine:\\n        # Get connection settings from config, with defaults if not specified\\n        # if the user specifies an empty dict, we allow it.\\n        kwargs = self._build_connection_kwargs()\\n\\n        poolclass_key = kwargs.get(\\\"poolclass\\\")\\n        if poolclass_key is not None:\\n            pool_class = getattr(sa.pool, poolclass_key, None)\\n            if pool_class and issubclass(pool_class, sa.pool.Pool):\\n                logger.debug(f\\\"Using poolclass: {poolclass_key}.\\\")\\n                kwargs[\\\"poolclass\\\"] = pool_class\\n            else:\\n                logger.error(f\\\"Invalid poolclass '{poolclass_key}' specified. Using default pool class.\\\")\\n                kwargs.pop(\\\"poolclass\\\", None)\\n\\n        return create_async_engine(\\n            self.database_url,\\n            connect_args=self._get_connect_args(),\\n            **kwargs,\\n        )\\n\\n    @retry(wait=wait_fixed(2), stop=stop_after_attempt(10))\\n    def _create_engine_with_retry(self) -> AsyncEngine:\\n        \\\"\\\"\\\"Create the engine for the database with retry logic.\\\"\\\"\\\"\\n        return self._create_engine()\\n\\n    def _get_connect_args(self):\\n        settings = self.settings_service.settings\\n\\n        if settings.db_driver_connection_settings is not None:\\n            return settings.db_driver_connection_settings\\n\\n        if settings.database_url and settings.database_url.startswith(\\\"sqlite\\\"):\\n            return {\\n                \\\"check_same_thread\\\": False,\\n                \\\"timeout\\\": settings.db_connect_timeout,\\n            }\\n        # For PostgreSQL, set the timezone to UTC\\n        if settings.database_url and settings.database_url.startswith((\\\"postgresql\\\", \\\"postgres\\\")):\\n            return {\\\"options\\\": \\\"-c timezone=utc\\\"}\\n        return {}\\n\\n    def on_connection(self, dbapi_connection, _connection_record) -> None:\\n        if isinstance(dbapi_connection, sqlite3.Connection | dialect_sqlite.aiosqlite.AsyncAdapt_aiosqlite_connection):\\n            pragmas: dict = self.settings_service.settings.sqlite_pragmas or {}\\n            pragmas_list = []\\n            for key, val in pragmas.items():\\n                pragmas_list.append(f\\\"PRAGMA {key} = {val}\\\")\\n            if not self._logged_pragma:\\n                logger.debug(f\\\"sqlite connection, setting pragmas: {pragmas_list}\\\")\\n                self._logged_pragma = True\\n            if pragmas_list:\\n                cursor = dbapi_connection.cursor()\\n                try:\\n                    for pragma in pragmas_list:\\n                        try:\\n                            cursor.execute(pragma)\\n                        except OperationalError:\\n                            logger.exception(f\\\"Failed to set PRAGMA {pragma}\\\")\\n                        except GeneratorExit:\\n                            logger.error(f\\\"Failed to set PRAGMA {pragma}\\\")\\n                finally:\\n                    cursor.close()\\n\\n    @asynccontextmanager\\n    async def _with_session(self):\\n        \\\"\\\"\\\"Internal method to create a session. DO NOT USE DIRECTLY.\\n\\n        Use session_scope() for write operations or session_scope_readonly() for read operations.\\n        This method does not handle commits - it only provides a raw session.\\n        \\\"\\\"\\\"\\n        if self.settings_service.settings.use_noop_database:\\n            yield NoopSession()\\n        else:\\n            # Use async_session_maker - the recommended SQLAlchemy 2.0+ pattern\\n            # Provides efficient session creation and proper connection pooling\\n            async with self.async_session_maker() as session:\\n                yield session\\n\\n    async def ensure_postgresql_version(self) -> None:\\n        \\\"\\\"\\\"If the database is PostgreSQL, ensure it is version 15 or higher.\\n\\n        Langflow's schema uses UNIQUE NULLS DISTINCT, which is only supported in PostgreSQL 15+.\\n        Logs the message and raises UnsupportedPostgreSQLVersionError if the version is too old.\\n        \\\"\\\"\\\"\\n        if not self.database_url.startswith((\\\"postgresql\\\", \\\"postgres\\\")):\\n            return\\n        if self.settings_service.settings.use_noop_database:\\n            return\\n        async with session_scope() as session:\\n            result = await session.execute(_PG_VERSION_QUERY)\\n            version_num_str, version_str = result.fetchone()\\n        # Raise AFTER session_scope exits so session_scope doesn't log a\\n        # noisy \\\"An error occurred during the session scope.\\\" traceback.\\n        _check_version_row(version_num_str, version_str)\\n\\n    async def assign_orphaned_flows_to_superuser(self) -> None:\\n        \\\"\\\"\\\"Assign orphaned flows to the default superuser when auto login is enabled.\\\"\\\"\\\"\\n        settings_service = get_settings_service()\\n\\n        if not settings_service.auth_settings.AUTO_LOGIN:\\n            return\\n\\n        async with session_scope() as session:\\n            # Fetch orphaned flows\\n            stmt = (\\n                select(models.Flow)\\n                .join(models.Folder)\\n                .where(\\n                    models.Flow.user_id == None,  # noqa: E711\\n                    sa.or_(models.Folder.name != STARTER_FOLDER_NAME, models.Folder.user_id.is_not(None)),\\n                )\\n            )\\n            orphaned_flows = (await session.exec(stmt)).all()\\n\\n            if not orphaned_flows:\\n                return\\n\\n            await logger.adebug(\\\"Assigning orphaned flows to the default superuser\\\")\\n\\n            # Retrieve superuser\\n            superuser_username = settings_service.auth_settings.SUPERUSER\\n            superuser = await get_user_by_username(session, superuser_username)\\n\\n            if not superuser:\\n                error_message = \\\"Default superuser not found\\\"\\n                await logger.aerror(error_message)\\n                raise RuntimeError(error_message)\\n\\n            # Get existing flow names for the superuser\\n            existing_names: set[str] = set(\\n                (await session.exec(select(models.Flow.name).where(models.Flow.user_id == superuser.id))).all()\\n            )\\n\\n            # Process orphaned flows\\n            for flow in orphaned_flows:\\n                flow.user_id = superuser.id\\n                flow.name = self._generate_unique_flow_name(flow.name, existing_names)\\n                existing_names.add(flow.name)\\n                session.add(flow)\\n\\n            # Commit changes\\n            await session.commit()\\n            await logger.adebug(\\\"Successfully assigned orphaned flows to the default superuser\\\")\\n\\n    @staticmethod\\n    def _generate_unique_flow_name(original_name: str, existing_names: set[str]) -> str:\\n        \\\"\\\"\\\"Generate a unique flow name by adding or incrementing a suffix.\\\"\\\"\\\"\\n        if original_name not in existing_names:\\n            return original_name\\n\\n        match = re.search(r\\\"^(.*) \\\\((\\\\d+)\\\\)$\\\", original_name)\\n        if match:\\n            base_name, current_number = match.groups()\\n            new_name = f\\\"{base_name} ({int(current_number) + 1})\\\"\\n        else:\\n            new_name = f\\\"{original_name} (1)\\\"\\n\\n        # Ensure unique name by incrementing suffix\\n        while new_name in existing_names:\\n            match = re.match(r\\\"^(.*) \\\\((\\\\d+)\\\\)$\\\", new_name)\\n            if match is not None:\\n                base_name, current_number = match.groups()\\n            else:\\n                error_message = \\\"Invalid format: match is None\\\"\\n                raise ValueError(error_message)\\n\\n            new_name = f\\\"{base_name} ({int(current_number) + 1})\\\"\\n\\n        return new_name\\n\\n    @staticmethod\\n    def _check_schema_health(connection) -> bool:\\n        inspector = inspect(connection)\\n\\n        model_mapping: dict[str, type[SQLModel]] = {\\n            \\\"flow\\\": models.Flow,\\n            \\\"user\\\": models.User,\\n            \\\"apikey\\\": models.ApiKey,\\n            \\\"job\\\": models.Job,\\n            # Add other SQLModel classes here\\n        }\\n\\n        # To account for tables that existed in older versions\\n        legacy_tables = [\\\"flowstyle\\\"]\\n\\n        for table, model in model_mapping.items():\\n            expected_columns = list(model.model_fields.keys())\\n\\n            try:\\n                available_columns = [col[\\\"name\\\"] for col in inspector.get_columns(table)]\\n            except sa.exc.NoSuchTableError:\\n                logger.debug(f\\\"Missing table: {table}\\\")\\n                return False\\n\\n            for column in expected_columns:\\n                if column not in available_columns:\\n                    logger.debug(f\\\"Missing column: {column} in table {table}\\\")\\n                    return False\\n\\n        for table in legacy_tables:\\n            if table in inspector.get_table_names():\\n                logger.warning(f\\\"Legacy table exists: {table}\\\")\\n\\n        return True\\n\\n    async def check_schema_health(self) -> None:\\n        async with self.engine.begin() as conn:\\n            await conn.run_sync(self._check_schema_health)\\n\\n    @staticmethod\\n    def init_alembic(alembic_cfg) -> None:\\n        logger.info(\\\"Initializing alembic\\\")\\n        command.ensure_version(alembic_cfg)\\n        # alembic_cfg.attributes[\\\"connection\\\"].commit()\\n        command.upgrade(alembic_cfg, \\\"head\\\")\\n\\n    def _open_alembic_log_buffer(self):\\n        \\\"\\\"\\\"Open the Alembic migration log for writing, falling back to stdout.\\n\\n        The migration log is diagnostic-only output. If the target path cannot\\n        be written -- e.g. the installed package directory or the root\\n        filesystem is read-only, as in hardened container/Kubernetes deployments\\n        (non-root user or read-only root filesystem) -- startup must not abort.\\n        Fall back to stdout rather than letting OSError propagate through the\\n        FastAPI lifespan. Returns a context manager yielding the buffer Alembic\\n        writes its output to.\\n        \\\"\\\"\\\"\\n        log_path = self.alembic_log_path\\n        if self.alembic_log_to_stdout or log_path is None:\\n            return nullcontext(sys.stdout)\\n        try:\\n            # _run_migrations can run before initialize_alembic_log_file(), so\\n            # make sure the parent directory exists before opening for writing.\\n            log_path.parent.mkdir(parents=True, exist_ok=True)\\n            return log_path.open(\\\"w\\\", encoding=\\\"utf-8\\\")\\n        except OSError as exc:\\n            logger.warning(\\n                f\\\"Could not open the Alembic migration log at '{log_path}' ({exc}). \\\"\\n                \\\"Falling back to stdout. Set LANGFLOW_ALEMBIC_LOG_FILE to a writable path \\\"\\n                \\\"or LANGFLOW_ALEMBIC_LOG_TO_STDOUT=true to silence this warning.\\\"\\n            )\\n            return nullcontext(sys.stdout)\\n\\n    def _run_migrations(self, should_initialize_alembic, fix) -> None:\\n        # First we need to check if alembic has been initialized\\n        # If not, we need to initialize it\\n        # if not self.script_location.exists(): # this is not the correct way to check if alembic has been initialized\\n        # We need to check if the alembic_version table exists\\n        # if not, we need to initialize alembic\\n        # stdout should be something like sys.stdout\\n        # which is a buffer\\n        # I don't want to output anything\\n        # subprocess.DEVNULL is an int\\n        buffer_context = self._open_alembic_log_buffer()\\n        # The advisory lock serialises concurrent migration runs across workers\\n        # so they do not race on CREATE TYPE / CREATE TABLE against a fresh PG.\\n        with _postgres_migration_lock(self.database_url), buffer_context as buffer:\\n            alembic_cfg = Config(stdout=buffer)\\n            # alembic_cfg.attributes[\\\"connection\\\"] = session\\n            alembic_cfg.set_main_option(\\\"script_location\\\", str(self.script_location))\\n            alembic_cfg.set_main_option(\\\"sqlalchemy.url\\\", self.database_url.replace(\\\"%\\\", \\\"%%\\\"))\\n\\n            if should_initialize_alembic:\\n                try:\\n                    self.init_alembic(alembic_cfg)\\n                except Exception as exc:\\n                    msg = f\\\"Error initializing alembic: {exc}\\\"\\n                    logger.exception(msg)\\n                    raise RuntimeError(msg) from exc\\n            else:\\n                logger.debug(\\\"Alembic initialized\\\")\\n\\n            try:\\n                buffer.write(f\\\"{datetime.now(tz=timezone.utc).astimezone().isoformat()}: Checking migrations\\\\n\\\")\\n                command.check(alembic_cfg)\\n            except Exception as exc:  # noqa: BLE001\\n                logger.debug(f\\\"Error checking migrations: {exc}\\\")\\n                if isinstance(exc, util.exc.CommandError | util.exc.AutogenerateDiffsDetected):\\n                    command.upgrade(alembic_cfg, \\\"head\\\")\\n                    time.sleep(3)\\n\\n            try:\\n                buffer.write(f\\\"{datetime.now(tz=timezone.utc).astimezone()}: Checking migrations\\\\n\\\")\\n                command.check(alembic_cfg)\\n            except util.exc.AutogenerateDiffsDetected as exc:\\n                logger.exception(\\\"Error checking migrations\\\")\\n                if not fix:\\n                    msg = f\\\"There's a mismatch between the models and the database.\\\\n{exc}\\\"\\n                    raise RuntimeError(msg) from exc\\n\\n            if fix:\\n                self.try_downgrade_upgrade_until_success(alembic_cfg)\\n\\n    async def run_migrations(self, *, fix=False) -> None:\\n        async with session_scope() as session:\\n            should_initialize_alembic = not await get_current_alembic_heads(session)\\n            if should_initialize_alembic:\\n                await logger.adebug(\\\"Alembic not initialized\\\")\\n        await asyncio.to_thread(self._run_migrations, should_initialize_alembic, fix)\\n\\n    def _current_alembic_revisions(self) -> set[str]:\\n        \\\"\\\"\\\"Read current revisions from the configured database, never alembic.ini.\\\"\\\"\\\"\\n        engine = sa.create_engine(_normalize_sync_postgres_url(self.database_url))\\n        try:\\n            with engine.connect() as connection:\\n                return set(connection.execute(sa.text(\\\"SELECT version_num FROM alembic_version\\\")).scalars())\\n        finally:\\n            engine.dispose()\\n\\n    def _run_migration_downgrade(self, *, expected_current_revision: str, target_revision: str) -> None:\\n        \\\"\\\"\\\"Downgrade the configured database only from one explicitly expected revision.\\\"\\\"\\\"\\n        buffer_context = self._open_alembic_log_buffer()\\n        with _postgres_migration_lock(self.database_url), buffer_context as buffer:\\n            current_revisions = self._current_alembic_revisions()\\n            if current_revisions != {expected_current_revision}:\\n                found = \\\", \\\".join(sorted(current_revisions)) or \\\"none\\\"\\n                msg = (\\n                    \\\"Refusing migration downgrade: expected current revision \\\"\\n                    f\\\"{expected_current_revision}, found {found}\\\"\\n                )\\n                raise RuntimeError(msg)\\n\\n            alembic_cfg = Config(stdout=buffer)\\n            alembic_cfg.set_main_option(\\\"script_location\\\", str(self.script_location))\\n            alembic_cfg.set_main_option(\\\"sqlalchemy.url\\\", self.database_url.replace(\\\"%\\\", \\\"%%\\\"))\\n            command.downgrade(alembic_cfg, target_revision)\\n\\n    async def run_migration_downgrade(\\n        self,\\n        *,\\n        expected_current_revision: str,\\n        target_revision: str,\\n    ) -> None:\\n        \\\"\\\"\\\"Safely downgrade the configured database in a worker thread.\\\"\\\"\\\"\\n        await asyncio.to_thread(\\n            self._run_migration_downgrade,\\n            expected_current_revision=expected_current_revision,\\n            target_revision=target_revision,\\n        )\\n\\n    @staticmethod\\n    def try_downgrade_upgrade_until_success(alembic_cfg, retries=5) -> None:\\n        # Try -1 then head, if it fails, try -2 then head, etc.\\n        # until we reach the number of retries\\n        for i in range(1, retries + 1):\\n            try:\\n                command.check(alembic_cfg)\\n                break\\n            except util.exc.AutogenerateDiffsDetected:\\n                # downgrade to base and upgrade again\\n                logger.warning(\\\"AutogenerateDiffsDetected\\\")\\n                command.downgrade(alembic_cfg, f\\\"-{i}\\\")\\n                # wait for the database to be ready\\n                time.sleep(3)\\n                command.upgrade(alembic_cfg, \\\"head\\\")\\n\\n    async def run_migrations_test(self):\\n        # This method is used for testing purposes only\\n        # We will check that all models are in the database\\n        # and that the database is up to date with all columns\\n        # get all models that are subclasses of SQLModel\\n        sql_models = [\\n            model for model in models.__dict__.values() if isinstance(model, type) and issubclass(model, SQLModel)\\n        ]\\n        # Use engine.begin() for proper async connection management with NullPool\\n        async with self.engine.begin() as conn:\\n            return [\\n                TableResults(sql_model.__tablename__, await conn.run_sync(self.check_table, sql_model))\\n                for sql_model in sql_models\\n            ]\\n\\n    @staticmethod\\n    def check_table(connection, model):\\n        results = []\\n        inspector = inspect(connection)\\n        table_name = model.__tablename__\\n        expected_columns = list(model.__fields__.keys())\\n        available_columns = []\\n        try:\\n            available_columns = [col[\\\"name\\\"] for col in inspector.get_columns(table_name)]\\n            results.append(Result(name=table_name, type=\\\"table\\\", success=True))\\n        except sa.exc.NoSuchTableError:\\n            logger.exception(f\\\"Missing table: {table_name}\\\")\\n            results.append(Result(name=table_name, type=\\\"table\\\", success=False))\\n\\n        for column in expected_columns:\\n            if column not in available_columns:\\n                logger.error(f\\\"Missing column: {column} in table {table_name}\\\")\\n                results.append(Result(name=column, type=\\\"column\\\", success=False))\\n            else:\\n                results.append(Result(name=column, type=\\\"column\\\", success=True))\\n        return results\\n\\n    @staticmethod\\n    def _create_db_and_tables(connection) -> None:\\n        from sqlalchemy import inspect\\n\\n        inspector = inspect(connection)\\n        table_names = inspector.get_table_names()\\n        current_tables = [\\n            \\\"flow\\\",\\n            \\\"user\\\",\\n            \\\"apikey\\\",\\n            \\\"folder\\\",\\n            \\\"message\\\",\\n            \\\"variable\\\",\\n            \\\"transaction\\\",\\n            \\\"vertex_build\\\",\\n            \\\"job\\\",\\n        ]\\n\\n        if table_names and all(table in table_names for table in current_tables):\\n            logger.debug(\\\"Database and tables already exist\\\")\\n            return\\n\\n        logger.debug(\\\"Creating database and tables\\\")\\n\\n        for table in SQLModel.metadata.sorted_tables:\\n            try:\\n                table.create(connection, checkfirst=True)\\n            except OperationalError as oe:\\n                logger.warning(f\\\"Table {table} already exists, skipping. Exception: {oe}\\\")\\n            except Exception as exc:\\n                msg = f\\\"Error creating table {table}\\\"\\n                logger.exception(msg)\\n                raise RuntimeError(msg) from exc\\n\\n        # Now check if the required tables exist, if not, something went wrong.\\n        inspector = inspect(connection)\\n        table_names = inspector.get_table_names()\\n        for table in current_tables:\\n            if table not in table_names:\\n                logger.error(\\\"Something went wrong creating the database and tables.\\\")\\n                logger.error(\\\"Please check your database settings.\\\")\\n                msg = \\\"Something went wrong creating the database and tables.\\\"\\n                raise RuntimeError(msg)\\n\\n        logger.debug(\\\"Database and tables created successfully\\\")\\n\\n    @retry(wait=wait_fixed(2), stop=stop_after_attempt(10))\\n    async def create_db_and_tables_with_retry(self) -> None:\\n        await self.create_db_and_tables()\\n\\n    async def create_db_and_tables(self) -> None:\\n        if not self.database_url.startswith((\\\"postgresql\\\", \\\"postgres\\\")):\\n            # SQLite / non-PG: original async path; advisory lock does not apply.\\n            async with self.engine.begin() as conn:\\n                await conn.run_sync(self._create_db_and_tables)\\n            return\\n\\n        # Postgres: serialise CREATE TYPE / CREATE TABLE across workers under\\n        # the same advisory lock that protects run_migrations. Without this,\\n        # concurrent workers booting against a fresh database race on\\n        # ``table.create(checkfirst=True)`` and the losers fail with\\n        # ``UniqueViolation`` on ``pg_type_typname_nsp_index``. The lock is\\n        # acquired synchronously; run in a worker thread so a contended-lock\\n        # poll does not block the event loop.\\n        await asyncio.to_thread(self._create_db_and_tables_with_lock)\\n\\n    def _create_db_and_tables_with_lock(self) -> None:\\n        \\\"\\\"\\\"Postgres path: hold the migration advisory lock for the DDL.\\n\\n        Opens its own sync engine so the DDL runs on the same driver the lock\\n        uses; the application's async engine is unaffected.\\n        \\\"\\\"\\\"\\n        with _postgres_migration_lock(self.database_url):\\n            sync_engine = sa.create_engine(_normalize_sync_postgres_url(self.database_url))\\n            try:\\n                with sync_engine.begin() as conn:\\n                    self._create_db_and_tables(conn)\\n            finally:\\n                sync_engine.dispose()\\n\\n    async def teardown(self) -> None:\\n        await logger.adebug(\\\"Tearing down database\\\")\\n        try:\\n            settings_service = get_settings_service()\\n            # When AUTO_LOGIN is off, remove the unused default superuser (see teardown_superuser).\\n            async with session_scope() as session:\\n                await teardown_superuser(settings_service, session)\\n        except Exception:\\n            await logger.aexception(\\\"Error tearing down database\\\")\\n            raise\\n        finally:\\n            await self.engine.dispose()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/session.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7041a8416767f40f7fa56c7784cf280b5b3bb726f9621f977ef95289b39790dd\",\"content\":\"class NoopSession:\\n    class NoopBind:\\n        class NoopConnect:\\n            async def __aenter__(self):\\n                return self\\n\\n            async def __aexit__(self, exc_type, exc, tb):\\n                pass\\n\\n            async def run_sync(self, fn, *args, **kwargs):  # noqa: ARG002\\n                return None\\n\\n        def connect(self):\\n            return self.NoopConnect()\\n\\n    bind = NoopBind()\\n\\n    async def connection(self):\\n        \\\"\\\"\\\"Return a no-op async connection for session-level database probes.\\\"\\\"\\\"\\n        return self.NoopBind.NoopConnect()\\n\\n    async def add(self, *args, **kwargs):\\n        pass\\n\\n    async def commit(self):\\n        pass\\n\\n    async def rollback(self):\\n        pass\\n\\n    async def execute(self, *args, **kwargs):  # noqa: ARG002\\n        return None\\n\\n    async def query(self, *args, **kwargs):  # noqa: ARG002\\n        return []\\n\\n    async def close(self):\\n        pass\\n\\n    async def refresh(self, *args, **kwargs):\\n        pass\\n\\n    async def delete(self, *args, **kwargs):\\n        pass\\n\\n    async def __aenter__(self):\\n        return self\\n\\n    async def __aexit__(self, exc_type, exc, tb):\\n        pass\\n\\n    async def get(self, *args, **kwargs):  # noqa: ARG002\\n        return None\\n\\n    async def exec(self, *args, **kwargs):  # noqa: ARG002\\n        class _NoopResult:\\n            def first(self):\\n                return None\\n\\n            def all(self):\\n                return []\\n\\n            def one_or_none(self):\\n                return None\\n\\n            def __iter__(self):\\n                return iter([])\\n\\n        return _NoopResult()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/database/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3da51d9c36cd228048b122dfd560e50e550376e61b1df0b9c7033e9555e6411e\",\"content\":\"from __future__ import annotations\\n\\nfrom contextlib import asynccontextmanager\\nfrom dataclasses import dataclass\\nfrom typing import TYPE_CHECKING\\nfrom uuid import UUID\\n\\nfrom alembic.util.exc import CommandError\\nfrom lfx.log.logger import logger\\nfrom sqlmodel import text\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\nif TYPE_CHECKING:\\n    from langflow.services.database.service import DatabaseService\\n\\n\\nasync def initialize_database(*, fix_migration: bool = False) -> None:\\n    await logger.adebug(\\\"Initializing database\\\")\\n    from langflow.services.deps import get_db_service\\n\\n    database_service: DatabaseService = get_db_service()\\n    await database_service.ensure_postgresql_version()\\n    # Fail fast with a clear, actionable message when a SQLite path cannot be\\n    # opened (e.g. a relative LANGFLOW_DATABASE_URL whose parent directory does\\n    # not exist), instead of the opaque \\\"Error creating DB and tables\\\" below.\\n    # See issue #13634.\\n    from langflow.services.database.service import check_sqlite_database_path\\n\\n    check_sqlite_database_path(database_service.database_url)\\n    try:\\n        if database_service.settings_service.settings.database_connection_retry:\\n            await database_service.create_db_and_tables_with_retry()\\n        else:\\n            await database_service.create_db_and_tables()\\n    except Exception as exc:\\n        # if the exception involves tables already existing\\n        # we can ignore it\\n        if \\\"already exists\\\" not in str(exc):\\n            msg = \\\"Error creating DB and tables\\\"\\n            await logger.aexception(msg)\\n            raise RuntimeError(msg) from exc\\n    try:\\n        await database_service.check_schema_health()\\n    except Exception as exc:\\n        msg = \\\"Error checking schema health\\\"\\n        logger.exception(msg)\\n        raise RuntimeError(msg) from exc\\n    try:\\n        await database_service.run_migrations(fix=fix_migration)\\n    except CommandError as exc:\\n        error_message = str(exc)\\n        if (\\n            \\\"overlaps with other requested revisions\\\" in error_message\\n            or \\\"Can't locate revision identified by\\\" in error_message\\n        ):\\n            # Wrong revision in the DB: delete alembic_version and re-run migrations\\n            logger.warning(\\\"Wrong revision in DB, deleting alembic_version table and running migrations again\\\")\\n            from langflow.services.deps import session_scope\\n\\n            async with session_scope() as session:\\n                await session.exec(text(\\\"DROP TABLE alembic_version\\\"))\\n            await database_service.run_migrations(fix=fix_migration)\\n        else:\\n            raise\\n    except Exception as exc:\\n        error_message = str(exc)\\n        # if the exception involves tables already existing\\n        # we can ignore it\\n        if \\\"already exists\\\" not in error_message:\\n            logger.exception(exc)\\n            raise\\n        await logger.adebug(\\\"Migration attempted to create existing table, skipping.\\\")\\n    await logger.adebug(\\\"Database initialized\\\")\\n\\n\\n@asynccontextmanager\\nasync def session_getter(db_service: DatabaseService):\\n    try:\\n        session = AsyncSession(db_service.engine, expire_on_commit=False)\\n        yield session\\n    except Exception:\\n        await logger.aexception(\\\"Session rollback because of exception\\\")\\n        await session.rollback()\\n        raise\\n    finally:\\n        await session.close()\\n\\n\\ndef require_non_empty(value: str | None, error_msg: str) -> str:\\n    \\\"\\\"\\\"Return a stripped non-empty string, or raise ``ValueError``.\\\"\\\"\\\"\\n    stripped = (value or \\\"\\\").strip()\\n    if not stripped:\\n        raise ValueError(error_msg)\\n    return stripped\\n\\n\\ndef validate_non_empty_string(v: str, info: object) -> str:\\n    \\\"\\\"\\\"Validate a string field is non-empty after stripping whitespace.\\n\\n    Intended for use inside ``@field_validator`` methods on SQLModel/Pydantic\\n    models.  Raises ``ValueError`` with the field name if the value is blank.\\n    \\\"\\\"\\\"\\n    stripped = v.strip()\\n    if not stripped:\\n        field = getattr(info, \\\"field_name\\\", \\\"Field\\\")\\n        msg = f\\\"{field} must not be empty\\\"\\n        raise ValueError(msg)\\n    return stripped\\n\\n\\ndef validate_non_empty_string_preserve_value(v: str, info: object) -> str:\\n    \\\"\\\"\\\"Validate a string field is non-empty without normalizing its value.\\\"\\\"\\\"\\n    if not v.strip():\\n        field = getattr(info, \\\"field_name\\\", \\\"Field\\\")\\n        msg = f\\\"{field} must not be empty\\\"\\n        raise ValueError(msg)\\n    return v\\n\\n\\ndef validate_non_empty_string_optional(v: str | None, info: object) -> str | None:\\n    \\\"\\\"\\\"Like :func:`validate_non_empty_string` but allows ``None`` (skip).\\\"\\\"\\\"\\n    if v is None:\\n        return v\\n    return validate_non_empty_string(v, info)\\n\\n\\ndef normalize_string_or_none(v: str | None) -> str | None:\\n    \\\"\\\"\\\"Strip whitespace from *v* and return ``None`` if the result is blank.\\\"\\\"\\\"\\n    if v is None:\\n        return None\\n    stripped = v.strip()\\n    return stripped if stripped else None\\n\\n\\ndef parse_uuid(value: UUID | str, *, field_name: str = \\\"value\\\") -> UUID:\\n    \\\"\\\"\\\"Parse a UUID from a string or pass through a UUID.\\n\\n    Raises ValueError if the string is empty or not a valid UUID.\\n    The *field_name* parameter is included in the error message for context.\\n    \\\"\\\"\\\"\\n    if isinstance(value, UUID):\\n        return value\\n    if isinstance(value, str):\\n        stripped = value.strip()\\n        if not stripped:\\n            msg = f\\\"{field_name} must not be empty\\\"\\n            raise ValueError(msg)\\n        try:\\n            return UUID(stripped)\\n        except ValueError as exc:\\n            msg = f\\\"{field_name} is not a valid UUID: {stripped!r}\\\"\\n            raise ValueError(msg) from exc\\n    msg = f\\\"{field_name} must be a UUID or string, got {type(value).__name__}\\\"\\n    raise TypeError(msg)\\n\\n\\n@dataclass\\nclass Result:\\n    name: str\\n    type: str\\n    success: bool\\n\\n\\n@dataclass\\nclass TableResults:\\n    table_name: str\\n    results: list[Result]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/deployment_artifacts/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3dac26b67eb6254f124486e98626aae8a750fd6ebbb2bc7aaa6e9a70c67f8411\",\"content\":\"\\\"\\\"\\\"Safe, deterministic Editor deployment artifacts.\\\"\\\"\\\"\\n\\nfrom .builder import (\\n    LFPKG_MEDIA_TYPE,\\n    EmptyProjectArtifactError,\\n    ProjectArtifact,\\n    ProjectArtifactError,\\n    ProjectArtifactFlow,\\n    ProjectArtifactLimitError,\\n    ProjectArtifactLimits,\\n    ProjectArtifactNotFoundError,\\n    build_project_artifact,\\n)\\n\\n__all__ = [\\n    \\\"LFPKG_MEDIA_TYPE\\\",\\n    \\\"EmptyProjectArtifactError\\\",\\n    \\\"ProjectArtifact\\\",\\n    \\\"ProjectArtifactError\\\",\\n    \\\"ProjectArtifactFlow\\\",\\n    \\\"ProjectArtifactLimitError\\\",\\n    \\\"ProjectArtifactLimits\\\",\\n    \\\"ProjectArtifactNotFoundError\\\",\\n    \\\"build_project_artifact\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/deployment_artifacts/builder.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"91020d05b7bea69991c8ae300f3621a133af9c212bc3b7800a5637caad072a80\",\"content\":\"\\\"\\\"\\\"Build a deterministic, secret-scrubbed package from one persisted project.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport hashlib\\nimport io\\nimport json\\nimport stat\\nimport zipfile\\nfrom copy import deepcopy\\nfrom dataclasses import dataclass, field\\nfrom functools import partial\\nfrom typing import TYPE_CHECKING, Any, TypeVar\\n\\nfrom lfx.helpers.base_model import coalesce_bool\\nfrom sqlmodel import col, select\\n\\nfrom langflow.services.authorization import (\\n    FlowAction,\\n    KnowledgeBaseAction,\\n    ProjectAction,\\n    ensure_flows_permission,\\n    ensure_knowledge_base_permission,\\n    ensure_project_permission,\\n)\\nfrom langflow.services.authorization.fetch import authorized_or_owner_scoped\\nfrom langflow.services.database.models.flow.model import Flow, FlowRead\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom langflow.services.database.models.knowledge_base.model import KnowledgeBaseRecord\\nfrom langflow.services.database.models.memory_base.model import MemoryBase\\nfrom langflow.utils.flow_secrets import strip_secret_field_values_in_place\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Callable, Iterator, Sequence\\n    from uuid import UUID\\n\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n    from langflow.services.database.models.user.model import User, UserRead\\n\\nLFPKG_MEDIA_TYPE = \\\"application/vnd.langflow.lfpkg+zip\\\"\\n\\n_FIXED_ZIP_TIMESTAMP = (1980, 1, 1, 0, 0, 0)\\n_ZIP_FILE_MODE = stat.S_IFREG | 0o644\\n_MAX_JSON_DEPTH = 128\\n_MAX_JSON_ITEMS = 500_000\\n_MAX_ARTIFACT_JSON_ITEMS = 2_000_000\\n_FLOW_PAGE_SIZE = 4\\n_ASCII_CONTROL_CUTOFF = 0x20\\n_UTF8_ONE_BYTE_MAX = 0x7F\\n_UTF8_TWO_BYTE_MAX = 0x7FF\\n_UTF8_THREE_BYTE_MAX = 0xFFFF\\n_UNICODE_SURROGATE_MIN = 0xD800\\n_UNICODE_SURROGATE_MAX = 0xDFFF\\n_VOLATILE_TOP_LEVEL_FIELDS = frozenset(\\n    {\\\"updated_at\\\", \\\"created_at\\\", \\\"user_id\\\", \\\"folder_id\\\", \\\"workspace_id\\\", \\\"access_type\\\", \\\"gradient\\\"}\\n)\\n_VOLATILE_NODE_FIELDS = frozenset({\\\"positionAbsolute\\\", \\\"dragging\\\", \\\"selected\\\"})\\n\\n_T = TypeVar(\\\"_T\\\")\\n\\n\\nclass ProjectArtifactError(ValueError):\\n    \\\"\\\"\\\"Base class for safe, caller-visible package construction failures.\\\"\\\"\\\"\\n\\n\\nclass EmptyProjectArtifactError(ProjectArtifactError):\\n    \\\"\\\"\\\"Raised when a project has no flows to package.\\\"\\\"\\\"\\n\\n\\nclass ProjectArtifactNotFoundError(ProjectArtifactError):\\n    \\\"\\\"\\\"Raised when the requested project is not visible to the caller.\\\"\\\"\\\"\\n\\n\\nclass ProjectArtifactLimitError(ProjectArtifactError):\\n    \\\"\\\"\\\"Raised when package input exceeds a configured resource ceiling.\\\"\\\"\\\"\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass ProjectArtifactLimits:\\n    \\\"\\\"\\\"Resource ceilings applied before returning an in-memory package.\\\"\\\"\\\"\\n\\n    max_flow_count: int = 500\\n    max_flow_bytes: int = 8 * 1024 * 1024\\n    max_expanded_bytes: int = 64 * 1024 * 1024\\n\\n    def __post_init__(self) -> None:\\n        for field_name in (\\\"max_flow_count\\\", \\\"max_flow_bytes\\\", \\\"max_expanded_bytes\\\"):\\n            value = getattr(self, field_name)\\n            if isinstance(value, bool) or not isinstance(value, int) or value <= 0:\\n                msg = f\\\"{field_name} must be a positive integer\\\"\\n                raise ValueError(msg)\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass ProjectArtifactFlow:\\n    \\\"\\\"\\\"Manifest metadata for one packaged flow.\\\"\\\"\\\"\\n\\n    flow_id: UUID\\n    name: str\\n    path: str\\n    sha256: str\\n    size: int\\n    required_variables: tuple[str, ...]\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass ProjectArtifact:\\n    \\\"\\\"\\\"Immutable package bytes and non-secret response metadata.\\\"\\\"\\\"\\n\\n    content: bytes\\n    filename: str\\n    media_type: str\\n    project_id: UUID\\n    project_name: str\\n    flows: tuple[ProjectArtifactFlow, ...]\\n    # MB/KB the packaged flows reference, shaped for the Control Plane's SyncRequest.\\n    # Empty when no flow references a Memory Base or Knowledge Base.\\n    dependencies: dict[str, Any] = field(default_factory=dict)\\n\\n    @property\\n    def flow_count(self) -> int:\\n        \\\"\\\"\\\"Return the number of flow payloads in the package.\\\"\\\"\\\"\\n        return len(self.flows)\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass _FlowSnapshot:\\n    flow_id: UUID\\n    name: str\\n    payload: dict[str, Any]\\n    owner_id: UUID | None = None\\n\\n\\n@dataclass(frozen=True, slots=True)\\nclass _SnapshotBatch:\\n    snapshots: tuple[_FlowSnapshot, ...]\\n    estimated_bytes: int\\n    item_count: int\\n\\n\\ndef _canonical_json_bytes(value: object) -> bytes:\\n    return json.dumps(value, ensure_ascii=False, separators=(\\\",\\\", \\\":\\\"), sort_keys=True).encode()\\n\\n\\ndef _zip_info(path: str) -> zipfile.ZipInfo:\\n    info = zipfile.ZipInfo(filename=path, date_time=_FIXED_ZIP_TIMESTAMP)\\n    info.compress_type = zipfile.ZIP_STORED\\n    info.create_system = 3\\n    info.external_attr = _ZIP_FILE_MODE << 16\\n    info.internal_attr = 0\\n    info.extra = b\\\"\\\"\\n    info.comment = b\\\"\\\"\\n    return info\\n\\n\\ndef _normalized_flow_bytes(snapshot: _FlowSnapshot) -> tuple[bytes, tuple[str, ...]]:\\n    # Scrubbing and volatile-field removal mutate nested values in place. Copy\\n    # first so aliases held by the snapshot or persisted Flow data stay intact.\\n    scrubbed = deepcopy(snapshot.payload)\\n    # Deployment scrubbing keeps ``load_from_db`` variable-name references so\\n    # the serving side can provision credentials under the same names; the\\n    # collected names feed the manifest's required-variables listing.\\n    variable_references: set[str] = set()\\n    scrubbed[\\\"data\\\"] = strip_secret_field_values_in_place(scrubbed.get(\\\"data\\\"), variable_references=variable_references)\\n    # Deployment packages retain runtime-native code strings. The normal git\\n    # export path splits code into one list element per line, which is useful\\n    # for diffs but can amplify a newline-heavy value into millions of Python\\n    # objects before serialization.\\n    for key in _VOLATILE_TOP_LEVEL_FIELDS:\\n        scrubbed.pop(key, None)\\n    data = scrubbed.get(\\\"data\\\")\\n    if isinstance(data, dict):\\n        nodes = data.get(\\\"nodes\\\")\\n        if isinstance(nodes, list):\\n            for node in nodes:\\n                if isinstance(node, dict):\\n                    for key in _VOLATILE_NODE_FIELDS:\\n                        node.pop(key, None)\\n    return _canonical_json_bytes(scrubbed), tuple(sorted(variable_references))\\n\\n\\ndef _json_string_size(value: str) -> int:\\n    \\\"\\\"\\\"Return a conservative UTF-8 JSON string size without allocating bytes.\\\"\\\"\\\"\\n    total = 2  # surrounding quotes\\n    for character in value:\\n        codepoint = ord(character)\\n        if _UNICODE_SURROGATE_MIN <= codepoint <= _UNICODE_SURROGATE_MAX:\\n            msg = \\\"project artifact text contains an invalid Unicode surrogate\\\"\\n            raise ProjectArtifactError(msg)\\n        if character in {'\\\"', \\\"\\\\\\\\\\\"}:\\n            total += 2\\n        elif codepoint < _ASCII_CONTROL_CUTOFF:\\n            total += 6\\n        elif codepoint <= _UTF8_ONE_BYTE_MAX:\\n            total += 1\\n        elif codepoint <= _UTF8_TWO_BYTE_MAX:\\n            total += 2\\n        elif codepoint <= _UTF8_THREE_BYTE_MAX:\\n            total += 3\\n        else:\\n            total += 4\\n    return total\\n\\n\\ndef _preflight_json_value(\\n    value: object,\\n    *,\\n    flow_id: UUID,\\n    max_bytes: int,\\n    max_items: int,\\n) -> tuple[int, int]:\\n    \\\"\\\"\\\"Conservatively bound one JSON-compatible value without serializing it.\\\"\\\"\\\"\\n    total_size = 0\\n    item_count = 0\\n    # Iterator frames keep traversal memory proportional to nesting depth,\\n    # rather than allocating one pending tuple per element in a wide list.\\n    frames: list[tuple[Iterator[object], int]] = [(iter((value,)), 0)]\\n    while frames:\\n        values, depth = frames[-1]\\n        try:\\n            value = next(values)\\n        except StopIteration:\\n            frames.pop()\\n            continue\\n        item_count += 1\\n        if item_count > max_items:\\n            msg = f\\\"flow file {flow_id} exceeds the {max_items}-item structural limit\\\"\\n            raise ProjectArtifactLimitError(msg)\\n        if depth > _MAX_JSON_DEPTH:\\n            msg = f\\\"flow file {flow_id} exceeds the {_MAX_JSON_DEPTH}-level nesting limit\\\"\\n            raise ProjectArtifactLimitError(msg)\\n\\n        if isinstance(value, dict):\\n            # Braces plus one colon per entry and one comma between entries.\\n            total_size += 2 + (2 * len(value))\\n            for key in value:\\n                total_size += _json_string_size(str(key))\\n            if value:\\n                frames.append((iter(value.values()), depth + 1))\\n        elif isinstance(value, (list, tuple)):\\n            total_size += 2 + len(value)\\n            if value:\\n                frames.append((iter(value), depth + 1))\\n        elif isinstance(value, str):\\n            total_size += _json_string_size(value)\\n        elif value is None or isinstance(value, bool):\\n            total_size += 5\\n        elif isinstance(value, (int, float)):\\n            total_size += len(str(value))\\n        else:\\n            msg = f\\\"flow file {flow_id} contains unsupported persisted data\\\"\\n            raise ProjectArtifactError(msg)\\n\\n        if total_size > max_bytes:\\n            msg = f\\\"flow file {flow_id} exceeds the {max_bytes}-byte preflight limit\\\"\\n            raise ProjectArtifactLimitError(msg)\\n    return total_size, item_count\\n\\n\\ndef _snapshot_rows(\\n    rows: tuple[Flow, ...],\\n    *,\\n    limits: ProjectArtifactLimits,\\n    remaining_expanded_bytes: int,\\n    remaining_items: int,\\n) -> _SnapshotBatch:\\n    \\\"\\\"\\\"Detach and bound one small database page outside the event loop.\\\"\\\"\\\"\\n    snapshots: list[_FlowSnapshot] = []\\n    estimated_bytes = 0\\n    item_count = 0\\n    for flow in rows:\\n        # Bound the persisted graph before Pydantic copies it into a detached\\n        # payload, then bound the complete exported model against both the\\n        # per-flow and remaining aggregate budgets.\\n        _preflight_json_value(\\n            flow.data,\\n            flow_id=flow.id,\\n            max_bytes=limits.max_flow_bytes,\\n            max_items=_MAX_JSON_ITEMS,\\n        )\\n        payload = FlowRead.model_validate(flow, from_attributes=True).model_dump(mode=\\\"json\\\")\\n        flow_size, flow_items = _preflight_json_value(\\n            payload,\\n            flow_id=flow.id,\\n            max_bytes=limits.max_flow_bytes,\\n            max_items=_MAX_JSON_ITEMS,\\n        )\\n        if estimated_bytes + flow_size > remaining_expanded_bytes:\\n            msg = f\\\"artifact expanded size exceeds the {limits.max_expanded_bytes}-byte limit\\\"\\n            raise ProjectArtifactLimitError(msg)\\n        if item_count + flow_items > remaining_items:\\n            msg = f\\\"artifact exceeds the {_MAX_ARTIFACT_JSON_ITEMS}-item structural limit\\\"\\n            raise ProjectArtifactLimitError(msg)\\n        estimated_bytes += flow_size\\n        item_count += flow_items\\n        snapshots.append(_FlowSnapshot(flow_id=flow.id, name=flow.name, payload=payload, owner_id=flow.user_id))\\n    return _SnapshotBatch(tuple(snapshots), estimated_bytes, item_count)\\n\\n\\ndef _build_archive(\\n    *,\\n    project_id: UUID,\\n    project_name: str,\\n    snapshots: tuple[_FlowSnapshot, ...],\\n    limits: ProjectArtifactLimits,\\n    dependencies: dict[str, list[dict[str, Any]]] | None = None,\\n) -> ProjectArtifact:\\n    flow_entries: list[ProjectArtifactFlow] = []\\n    files: list[tuple[str, bytes]] = []\\n    expanded_size = 0\\n\\n    # Validate all manifest-only persisted text before serializing any file.\\n    _json_string_size(project_name)\\n    for snapshot in snapshots:\\n        _json_string_size(snapshot.name)\\n\\n    for snapshot in snapshots:\\n        path = f\\\"flows/{snapshot.flow_id}.json\\\"\\n        content, required_variables = _normalized_flow_bytes(snapshot)\\n        size = len(content)\\n        if size > limits.max_flow_bytes:\\n            msg = f\\\"flow file {snapshot.flow_id} is {size} bytes, exceeding the {limits.max_flow_bytes}-byte limit\\\"\\n            raise ProjectArtifactLimitError(msg)\\n        expanded_size += size\\n        if expanded_size > limits.max_expanded_bytes:\\n            msg = f\\\"artifact expanded size exceeds the {limits.max_expanded_bytes}-byte limit\\\"\\n            raise ProjectArtifactLimitError(msg)\\n        files.append((path, content))\\n        flow_entries.append(\\n            ProjectArtifactFlow(\\n                flow_id=snapshot.flow_id,\\n                name=snapshot.name,\\n                path=path,\\n                sha256=hashlib.sha256(content).hexdigest(),\\n                size=size,\\n                required_variables=required_variables,\\n            )\\n        )\\n\\n    manifest = {\\n        # v2 is already assigned to flows[].version_id. Dependencies therefore\\n        # use v3 so an older reader refuses them instead of deploying without\\n        # provisioning resources the packaged flows require.\\n        \\\"schema_version\\\": 3 if dependencies else 1,\\n        \\\"project\\\": {\\\"id\\\": str(project_id), \\\"name\\\": project_name},\\n        # Names of every load_from_db-bound global variable the packaged flows\\n        # reference; the deploy target must provision each name before serving.\\n        \\\"required_variables\\\": sorted({name for flow in flow_entries for name in flow.required_variables}),\\n        \\\"flows\\\": [\\n            {\\n                \\\"id\\\": str(flow.flow_id),\\n                \\\"name\\\": flow.name,\\n                \\\"path\\\": flow.path,\\n                \\\"sha256\\\": flow.sha256,\\n                \\\"size\\\": flow.size,\\n                \\\"required_variables\\\": list(flow.required_variables),\\n            }\\n            for flow in flow_entries\\n        ],\\n    }\\n    if dependencies:\\n        manifest[\\\"dependencies\\\"] = dependencies\\n    manifest_bytes = _canonical_json_bytes(manifest)\\n    if len(manifest_bytes) > limits.max_flow_bytes:\\n        msg = f\\\"manifest file is {len(manifest_bytes)} bytes, exceeding the {limits.max_flow_bytes}-byte limit\\\"\\n        raise ProjectArtifactLimitError(msg)\\n    expanded_size += len(manifest_bytes)\\n    if expanded_size > limits.max_expanded_bytes:\\n        msg = f\\\"artifact expanded size exceeds the {limits.max_expanded_bytes}-byte limit\\\"\\n        raise ProjectArtifactLimitError(msg)\\n\\n    output = io.BytesIO()\\n    with zipfile.ZipFile(output, mode=\\\"w\\\", compression=zipfile.ZIP_STORED, allowZip64=False) as archive:\\n        archive.writestr(_zip_info(\\\"manifest.json\\\"), manifest_bytes)\\n        for path, content in files:\\n            archive.writestr(_zip_info(path), content)\\n\\n    return ProjectArtifact(\\n        content=output.getvalue(),\\n        filename=f\\\"langflow-project-{project_id}.lfpkg\\\",\\n        media_type=LFPKG_MEDIA_TYPE,\\n        project_id=project_id,\\n        project_name=project_name,\\n        flows=tuple(flow_entries),\\n        dependencies=dependencies or {},\\n    )\\n\\n\\nasync def _run_sync_non_abandoning(function: Callable[[], _T]) -> _T:\\n    \\\"\\\"\\\"Delay request cancellation until a capacity-accounted worker exits.\\\"\\\"\\\"\\n    worker = asyncio.create_task(asyncio.to_thread(function))\\n    cancellation_requested = False\\n    while True:\\n        try:\\n            result = await asyncio.shield(worker)\\n            break\\n        except asyncio.CancelledError:\\n            cancellation_requested = True\\n            current_task = asyncio.current_task()\\n            uncancel = getattr(current_task, \\\"uncancel\\\", None)\\n            if callable(uncancel):\\n                uncancel()\\n\\n    if cancellation_requested:\\n        raise asyncio.CancelledError\\n    return result\\n\\n\\nasync def _build_archive_non_abandoning(\\n    *,\\n    project_id: UUID,\\n    project_name: str,\\n    snapshots: tuple[_FlowSnapshot, ...],\\n    limits: ProjectArtifactLimits,\\n    dependencies: dict[str, list[dict[str, Any]]] | None = None,\\n) -> ProjectArtifact:\\n    \\\"\\\"\\\"Build an archive without outliving its caller's capacity lease.\\\"\\\"\\\"\\n    return await _run_sync_non_abandoning(\\n        partial(\\n            _build_archive,\\n            project_id=project_id,\\n            project_name=project_name,\\n            snapshots=snapshots,\\n            limits=limits,\\n            dependencies=dependencies,\\n        )\\n    )\\n\\n\\ndef _collect_dependency_refs(payload: dict[str, Any]) -> tuple[set[str], set[str]]:\\n    \\\"\\\"\\\"Return (memory_base_names, knowledge_base_names) referenced by a flow's nodes.\\n\\n    A flow references a Memory Base by name at ``template.memory_base.value`` (the\\n    MB is flow-scoped) and a Knowledge Base by name at ``template.knowledge_base.value``,\\n    with ``template.new_kb_name.value`` naming a KB the flow creates inline. These\\n    names are the deploy target's provisioning keys \u2014 the same values the serving\\n    plane resolves the MB/KB by at run time.\\n    \\\"\\\"\\\"\\n    mb_names: set[str] = set()\\n    kb_names: set[str] = set()\\n    data = payload.get(\\\"data\\\")\\n    if not isinstance(data, dict):\\n        return mb_names, kb_names\\n    for node in data.get(\\\"nodes\\\") or []:\\n        if not isinstance(node, dict):\\n            continue\\n        template = (((node.get(\\\"data\\\") or {}).get(\\\"node\\\")) or {}).get(\\\"template\\\")\\n        if not isinstance(template, dict):\\n            continue\\n        for field_name, bucket in ((\\\"memory_base\\\", mb_names), (\\\"knowledge_base\\\", kb_names), (\\\"new_kb_name\\\", kb_names)):\\n            entry = template.get(field_name)\\n            value = entry.get(\\\"value\\\") if isinstance(entry, dict) else None\\n            if isinstance(value, str) and value.strip():\\n                bucket.add(value.strip())\\n    return mb_names, kb_names\\n\\n\\n# Non-secret backend routing fields used by the registered Chroma Cloud and\\n# OpenSearch backends. Credential values are represented only by ``*_variable``\\n# pointers, which are handled separately below.\\n_SAFE_BACKEND_ROUTING_KEYS = frozenset(\\n    {\\n        \\\"cloud_host\\\",\\n        \\\"cloud_port\\\",\\n        \\\"cloud_region\\\",\\n        \\\"engine\\\",\\n        \\\"index_name\\\",\\n        \\\"mode\\\",\\n        \\\"space_type\\\",\\n        \\\"text_field\\\",\\n        \\\"use_ssl\\\",\\n        \\\"vector_field\\\",\\n        \\\"verify_certs\\\",\\n    }\\n)\\n_SAFE_BACKEND_VALUE_TYPES = (str, int, float, bool)\\n\\n\\ndef _scrub_backend_config(backend_config: dict[str, Any] | None) -> dict[str, Any]:\\n    \\\"\\\"\\\"Return only deployable routing fields and variable-name pointers.\\\"\\\"\\\"\\n    if not isinstance(backend_config, dict):\\n        return {}\\n    scrubbed: dict[str, Any] = {}\\n    for key, value in backend_config.items():\\n        if not isinstance(key, str):\\n            continue\\n        lowered = key.lower()\\n        if lowered.endswith(\\\"_variable\\\"):\\n            if isinstance(value, str):\\n                scrubbed[key] = value\\n            continue\\n        if lowered in _SAFE_BACKEND_ROUTING_KEYS and isinstance(value, _SAFE_BACKEND_VALUE_TYPES):\\n            scrubbed[key] = value\\n    return scrubbed\\n\\n\\ndef _validated_backend_config(\\n    backend_type: object,\\n    backend_config: object,\\n    *,\\n    resource_kind: str,\\n) -> tuple[str, dict[str, Any]]:\\n    if not isinstance(backend_type, str) or not backend_type.strip():\\n        msg = f\\\"referenced {resource_kind} has no deployable backend type\\\"\\n        raise ProjectArtifactError(msg)\\n    config = backend_config if isinstance(backend_config, dict) else {}\\n    resolved_backend_type = backend_type.strip()\\n    if resolved_backend_type.lower() == \\\"chroma\\\" and str(config.get(\\\"mode\\\", \\\"local\\\")).lower() != \\\"cloud\\\":\\n        msg = f\\\"referenced {resource_kind} uses local Chroma, which cannot be provisioned on the deployment target\\\"\\n        raise ProjectArtifactError(msg)\\n    return resolved_backend_type, _scrub_backend_config(config)\\n\\n\\ndef _required_dependency_string(value: object, *, field_name: str, resource_kind: str) -> str:\\n    if not isinstance(value, str) or not value.strip():\\n        msg = f\\\"referenced {resource_kind} is missing {field_name}\\\"\\n        raise ProjectArtifactError(msg)\\n    return value\\n\\n\\ndef _store_dependency(\\n    items: dict[str, dict[str, Any]],\\n    *,\\n    name: str,\\n    item: dict[str, Any],\\n    resource_kind: str,\\n) -> None:\\n    existing = items.get(name)\\n    if existing is not None and existing != item:\\n        msg = f\\\"referenced {resource_kind} name {name!r} is ambiguous across flow owners\\\"\\n        raise ProjectArtifactError(msg)\\n    items[name] = item\\n\\n\\nasync def _resolve_dependencies(\\n    session: AsyncSession,\\n    *,\\n    user: User | UserRead,\\n    owner_id: UUID,\\n    workspace_id: UUID | None,\\n    project_id: UUID,\\n    snapshots: tuple[_FlowSnapshot, ...],\\n) -> dict[str, list[dict[str, Any]]]:\\n    \\\"\\\"\\\"Resolve the MB/KB names the packaged flows reference to their provisioning specs.\\n\\n    The names come from the flows; the specs come from each flow author's\\n    ``memory_base`` / ``knowledge_base`` rows. Each emitted item is shaped 1:1\\n    with the Control Plane's ``KnowledgeBaseItem`` / ``MemoryBaseItem`` so the\\n    deploy target passes it straight through the same validation with no second\\n    schema to drift. A Memory Base's backend lives on its auto-generated backing\\n    KB, so its ``backendType`` / ``backendConfig`` are read from that KB, and the\\n    backing KB is dropped from the KB list so it is never provisioned twice.\\n    Every resolved resource is authorized before its provisioning metadata is\\n    returned. Returns ``{}`` when the flows reference no MB or KB.\\n    \\\"\\\"\\\"\\n    mb_refs: set[tuple[UUID, str]] = set()\\n    kb_refs: set[tuple[UUID, str]] = set()\\n    for snapshot in snapshots:\\n        refs_mb, refs_kb = _collect_dependency_refs(snapshot.payload)\\n        source_owner_id = getattr(snapshot, \\\"owner_id\\\", None) or owner_id\\n        mb_refs.update((source_owner_id, name) for name in refs_mb)\\n        kb_refs.update((source_owner_id, name) for name in refs_kb)\\n    if not mb_refs and not kb_refs:\\n        return {}\\n\\n    memory_bases: dict[str, dict[str, Any]] = {}\\n    mb_backing_kb_refs: set[tuple[UUID, str]] = set()\\n    if mb_refs:\\n        mb_owner_ids = {ref_owner_id for ref_owner_id, _name in mb_refs}\\n        mb_names = {name for _ref_owner_id, name in mb_refs}\\n        candidate_mb_rows = (\\n            await session.exec(\\n                select(MemoryBase).where(\\n                    col(MemoryBase.user_id).in_(mb_owner_ids),\\n                    col(MemoryBase.name).in_(mb_names),\\n                )\\n            )\\n        ).all()\\n        mb_rows = [mb for mb in candidate_mb_rows if (mb.user_id, mb.name) in mb_refs]\\n        mb_by_ref = {(mb.user_id, mb.name): mb for mb in mb_rows}\\n        if mb_refs - set(mb_by_ref):\\n            msg = \\\"one or more referenced Memory Bases were not found\\\"\\n            raise ProjectArtifactError(msg)\\n\\n        mb_backing_kb_refs = {(mb.user_id, mb.kb_name) for mb in mb_rows if mb.kb_name}\\n        if len(mb_backing_kb_refs) != len(mb_rows):\\n            msg = \\\"a referenced Memory Base has no backing Knowledge Base\\\"\\n            raise ProjectArtifactError(msg)\\n        backing_owner_ids = {backing_owner_id for backing_owner_id, _name in mb_backing_kb_refs}\\n        backing_names = {name for _backing_owner_id, name in mb_backing_kb_refs}\\n        candidate_backing_rows = (\\n            await session.exec(\\n                select(KnowledgeBaseRecord).where(\\n                    col(KnowledgeBaseRecord.user_id).in_(backing_owner_ids),\\n                    col(KnowledgeBaseRecord.name).in_(backing_names),\\n                )\\n            )\\n        ).all()\\n        backing_rows = [kb for kb in candidate_backing_rows if (kb.user_id, kb.name) in mb_backing_kb_refs]\\n        backing_by_ref = {(kb.user_id, kb.name): kb for kb in backing_rows}\\n        if mb_backing_kb_refs - set(backing_by_ref):\\n            msg = \\\"a referenced Memory Base's backing Knowledge Base was not found\\\"\\n            raise ProjectArtifactError(msg)\\n\\n        for mb in sorted(mb_rows, key=lambda row: (row.name, str(row.user_id))):\\n            await ensure_knowledge_base_permission(\\n                user,\\n                KnowledgeBaseAction.READ,\\n                kb_id=mb.id,\\n                kb_user_id=mb.user_id,\\n                kb_name=mb.kb_name,\\n                workspace_id=workspace_id,\\n                project_id=project_id,\\n            )\\n            backing_kb = backing_by_ref[(mb.user_id, mb.kb_name)]\\n            backend_type, backend_config = _validated_backend_config(\\n                backing_kb.backend_type,\\n                backing_kb.backend_config,\\n                resource_kind=\\\"Memory Base\\\",\\n            )\\n            embedding_model = _required_dependency_string(\\n                mb.embedding_model,\\n                field_name=\\\"embedding model\\\",\\n                resource_kind=\\\"Memory Base\\\",\\n            )\\n            if mb.preprocessing and not mb.preproc_model:\\n                msg = \\\"referenced Memory Base is missing its preprocessing model\\\"\\n                raise ProjectArtifactError(msg)\\n            item: dict[str, Any] = {\\n                \\\"name\\\": mb.name,\\n                \\\"flowId\\\": str(mb.flow_id),\\n                \\\"embeddingModel\\\": embedding_model,\\n                \\\"backendType\\\": backend_type,\\n                \\\"backendConfig\\\": backend_config,\\n                \\\"threshold\\\": mb.threshold,\\n                \\\"autoCapture\\\": mb.auto_capture,\\n                \\\"preprocessing\\\": mb.preprocessing,\\n            }\\n            if mb.preproc_model:\\n                item[\\\"preprocModel\\\"] = mb.preproc_model\\n            if mb.preproc_instructions:\\n                item[\\\"preprocInstructions\\\"] = mb.preproc_instructions\\n            if mb.preproc_kill_phrase:\\n                item[\\\"preprocKillPhrase\\\"] = mb.preproc_kill_phrase\\n            _store_dependency(memory_bases, name=mb.name, item=item, resource_kind=\\\"Memory Base\\\")\\n\\n    # Provisioning an MB creates its backing KB; never emit that exact KB on its own.\\n    kb_refs -= mb_backing_kb_refs\\n    knowledge_bases: dict[str, dict[str, Any]] = {}\\n    if kb_refs:\\n        kb_owner_ids = {ref_owner_id for ref_owner_id, _name in kb_refs}\\n        kb_names = {name for _ref_owner_id, name in kb_refs}\\n        candidate_kb_rows = (\\n            await session.exec(\\n                select(KnowledgeBaseRecord).where(\\n                    col(KnowledgeBaseRecord.user_id).in_(kb_owner_ids),\\n                    col(KnowledgeBaseRecord.name).in_(kb_names),\\n                )\\n            )\\n        ).all()\\n        kb_rows = [kb for kb in candidate_kb_rows if (kb.user_id, kb.name) in kb_refs]\\n        kb_by_ref = {(kb.user_id, kb.name): kb for kb in kb_rows}\\n        if kb_refs - set(kb_by_ref):\\n            msg = \\\"one or more referenced Knowledge Bases were not found\\\"\\n            raise ProjectArtifactError(msg)\\n\\n        for kb in sorted(kb_rows, key=lambda row: (row.name, str(row.user_id))):\\n            await ensure_knowledge_base_permission(\\n                user,\\n                KnowledgeBaseAction.READ,\\n                kb_id=kb.id,\\n                kb_user_id=kb.user_id,\\n                kb_name=kb.name,\\n                workspace_id=workspace_id,\\n                project_id=project_id,\\n            )\\n            backend_type, backend_config = _validated_backend_config(\\n                kb.backend_type,\\n                kb.backend_config,\\n                resource_kind=\\\"Knowledge Base\\\",\\n            )\\n            model_selection = kb.model_selection if isinstance(kb.model_selection, dict) else {}\\n            embedding_provider = _required_dependency_string(\\n                model_selection.get(\\\"provider\\\"),\\n                field_name=\\\"embedding provider\\\",\\n                resource_kind=\\\"Knowledge Base\\\",\\n            )\\n            embedding_model = _required_dependency_string(\\n                model_selection.get(\\\"name\\\"),\\n                field_name=\\\"embedding model\\\",\\n                resource_kind=\\\"Knowledge Base\\\",\\n            )\\n            item = {\\n                \\\"name\\\": kb.name,\\n                \\\"embeddingProvider\\\": embedding_provider,\\n                \\\"embeddingModel\\\": embedding_model,\\n                \\\"backendType\\\": backend_type,\\n                \\\"backendConfig\\\": backend_config,\\n            }\\n            if kb.column_config:\\n                item[\\\"columnConfig\\\"] = [\\n                    {\\n                        \\\"columnName\\\": entry.get(\\\"column_name\\\", entry.get(\\\"columnName\\\", \\\"\\\")),\\n                        # Rows can hold flags typed into the column table as strings.\\n                        \\\"vectorize\\\": coalesce_bool(entry.get(\\\"vectorize\\\")),\\n                        \\\"identifier\\\": coalesce_bool(entry.get(\\\"identifier\\\")),\\n                    }\\n                    for entry in kb.column_config\\n                    if isinstance(entry, dict)\\n                ]\\n            _store_dependency(knowledge_bases, name=kb.name, item=item, resource_kind=\\\"Knowledge Base\\\")\\n\\n    dependencies: dict[str, list[dict[str, Any]]] = {}\\n    if knowledge_bases:\\n        dependencies[\\\"knowledgeBases\\\"] = [knowledge_bases[name] for name in sorted(knowledge_bases)]\\n    if memory_bases:\\n        dependencies[\\\"memoryBases\\\"] = [memory_bases[name] for name in sorted(memory_bases)]\\n    return dependencies\\n\\n\\nasync def build_project_artifact(\\n    session: AsyncSession,\\n    user: User | UserRead,\\n    project_id: UUID,\\n    *,\\n    flow_ids: Sequence[UUID] | None = None,\\n    limits: ProjectArtifactLimits | None = None,\\n) -> ProjectArtifact:\\n    \\\"\\\"\\\"Package selected readable flows, or every flow assigned to the project.\\n\\n    The project lookup widens beyond the caller's owner namespace only when the\\n    registered authorization service explicitly supports cross-user fetch. Flow\\n    membership is determined by project folder regardless of author. Read checks\\n    are split into an actor-owned batch and a non-owned batch so the owner override\\n    is never applied to another author's flow, and every check must pass before\\n    any archive is constructed. Flow authorship and revision are revalidated\\n    while packaging so either kind of concurrent change fails consistently.\\n    \\\"\\\"\\\"\\n    selected_flow_ids: tuple[UUID, ...] | None = None\\n    if flow_ids is not None:\\n        if not flow_ids:\\n            msg = \\\"flow_ids must contain at least one flow ID when provided\\\"\\n            raise ProjectArtifactError(msg)\\n        if len(set(flow_ids)) != len(flow_ids):\\n            msg = \\\"flow_ids must not contain duplicate flow IDs\\\"\\n            raise ProjectArtifactError(msg)\\n        selected_flow_ids = tuple(sorted(flow_ids, key=str))\\n\\n    project = await authorized_or_owner_scoped(\\n        session,\\n        Folder,\\n        id_column=Folder.id,\\n        resource_id=project_id,\\n        owner_column=Folder.user_id,\\n        owner_id=user.id,\\n    )\\n    if project is None:\\n        msg = \\\"Project not found\\\"\\n        raise ProjectArtifactNotFoundError(msg)\\n\\n    await ensure_project_permission(\\n        user,\\n        ProjectAction.READ,\\n        project_id=project_id,\\n        project_user_id=project.user_id,\\n        workspace_id=project.workspace_id,\\n    )\\n\\n    effective_limits = limits or ProjectArtifactLimits()\\n    if selected_flow_ids is not None and len(selected_flow_ids) > effective_limits.max_flow_count:\\n        msg = f\\\"selected flow count {len(selected_flow_ids)} exceeds the {effective_limits.max_flow_count}-flow limit\\\"\\n        raise ProjectArtifactLimitError(msg)\\n    revision_statement = select(Flow.id, Flow.user_id, Flow.updated_at).where(Flow.folder_id == project_id)\\n    if selected_flow_ids is not None:\\n        revision_statement = revision_statement.where(col(Flow.id).in_(selected_flow_ids))\\n    revision_rows = list(\\n        (await session.exec(revision_statement.order_by(col(Flow.id)).limit(effective_limits.max_flow_count + 1))).all()\\n    )\\n    if selected_flow_ids is not None and len(revision_rows) != len(selected_flow_ids):\\n        msg = \\\"one or more selected flows were not found in the project\\\"\\n        raise ProjectArtifactNotFoundError(msg)\\n    if not revision_rows:\\n        msg = \\\"project has no flows to package\\\"\\n        raise EmptyProjectArtifactError(msg)\\n    if len(revision_rows) > effective_limits.max_flow_count:\\n        msg = f\\\"project flow count {len(revision_rows)} exceeds the {effective_limits.max_flow_count}-flow limit\\\"\\n        raise ProjectArtifactLimitError(msg)\\n\\n    ordered_revisions = tuple(sorted(revision_rows, key=lambda revision: str(revision[0])))\\n    ordered_flow_ids = tuple(flow_id for flow_id, _flow_user_id, _updated_at in ordered_revisions)\\n    initial_revisions = {flow_id: (flow_user_id, updated_at) for flow_id, flow_user_id, updated_at in ordered_revisions}\\n    actor_owned_flow_ids = [\\n        flow_id for flow_id, flow_user_id, _updated_at in ordered_revisions if flow_user_id == user.id\\n    ]\\n    non_owned_flow_ids = [\\n        flow_id for flow_id, flow_user_id, _updated_at in ordered_revisions if flow_user_id != user.id\\n    ]\\n    for permission_flow_ids, flow_user_id in (\\n        (actor_owned_flow_ids, user.id),\\n        (non_owned_flow_ids, None),\\n    ):\\n        if permission_flow_ids:\\n            await ensure_flows_permission(\\n                user,\\n                FlowAction.READ,\\n                flow_ids=permission_flow_ids,\\n                flow_user_id=flow_user_id,\\n                workspace_id=project.workspace_id,\\n                folder_id=project_id,\\n            )\\n\\n    snapshots: list[_FlowSnapshot] = []\\n    estimated_bytes = 0\\n    item_count = 0\\n    for page_start in range(0, len(ordered_flow_ids), _FLOW_PAGE_SIZE):\\n        page_ids = ordered_flow_ids[page_start : page_start + _FLOW_PAGE_SIZE]\\n        rows = list(\\n            (\\n                await session.exec(\\n                    select(Flow)\\n                    .where(\\n                        col(Flow.id).in_(page_ids),\\n                        Flow.folder_id == project_id,\\n                    )\\n                    .order_by(col(Flow.id))\\n                )\\n            ).all()\\n        )\\n        ordered_rows = tuple(sorted(rows, key=lambda flow: str(flow.id)))\\n        expected_page_revisions = tuple((flow_id, *initial_revisions[flow_id]) for flow_id in page_ids)\\n        if tuple((flow.id, flow.user_id, flow.updated_at) for flow in ordered_rows) != expected_page_revisions:\\n            msg = \\\"project flows changed during packaging\\\"\\n            raise ProjectArtifactError(msg)\\n\\n        remaining_expanded_bytes = effective_limits.max_expanded_bytes - estimated_bytes\\n        remaining_items = _MAX_ARTIFACT_JSON_ITEMS - item_count\\n        if remaining_expanded_bytes <= 0:\\n            msg = f\\\"artifact expanded size exceeds the {effective_limits.max_expanded_bytes}-byte limit\\\"\\n            raise ProjectArtifactLimitError(msg)\\n        if remaining_items <= 0:\\n            msg = f\\\"artifact exceeds the {_MAX_ARTIFACT_JSON_ITEMS}-item structural limit\\\"\\n            raise ProjectArtifactLimitError(msg)\\n        batch = await _run_sync_non_abandoning(\\n            partial(\\n                _snapshot_rows,\\n                ordered_rows,\\n                limits=effective_limits,\\n                remaining_expanded_bytes=remaining_expanded_bytes,\\n                remaining_items=remaining_items,\\n            )\\n        )\\n        snapshots.extend(batch.snapshots)\\n        estimated_bytes += batch.estimated_bytes\\n        item_count += batch.item_count\\n\\n    final_revision_statement = select(Flow.id, Flow.user_id, Flow.updated_at).where(Flow.folder_id == project_id)\\n    if selected_flow_ids is not None:\\n        final_revision_statement = final_revision_statement.where(col(Flow.id).in_(selected_flow_ids))\\n    final_revisions = tuple(\\n        (\\n            await session.exec(\\n                final_revision_statement.order_by(col(Flow.id)).limit(effective_limits.max_flow_count + 1)\\n            )\\n        ).all()\\n    )\\n    if final_revisions != ordered_revisions:\\n        msg = \\\"project flows changed during packaging\\\"\\n        raise ProjectArtifactError(msg)\\n\\n    # Archive construction is intentionally non-abandoning. If the HTTP request\\n    # is cancelled, keep the caller suspended until the worker exits so the\\n    # Enterprise package semaphore continues to account for its memory use.\\n    dependencies = await _resolve_dependencies(\\n        session,\\n        user=user,\\n        owner_id=project.user_id,\\n        workspace_id=project.workspace_id,\\n        project_id=project_id,\\n        snapshots=tuple(snapshots),\\n    )\\n    return await _build_archive_non_abandoning(\\n        project_id=project_id,\\n        project_name=project.name,\\n        snapshots=tuple(snapshots),\\n        limits=effective_limits,\\n        dependencies=dependencies,\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/deps.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0ed8a641d50cd3d6e006cb59ea1a64930c62a83507e4910cf6aed49996a2e879\",\"content\":\"from __future__ import annotations\\n\\nimport sys\\nfrom contextlib import asynccontextmanager\\nfrom typing import TYPE_CHECKING, Union\\n\\nfrom langflow.services.schema import ServiceType\\n\\nif TYPE_CHECKING:\\n    from collections.abc import AsyncGenerator\\n\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n    from langflow.services.cache.service import AsyncBaseCacheService, CacheService\\n    from langflow.services.chat.service import ChatService\\n    from langflow.services.database.service import DatabaseService\\n    from langflow.services.session.service import SessionService\\n    from langflow.services.state.service import StateService\\n    from langflow.services.store.service import StoreService\\n    from langflow.services.task.service import TaskService\\n    from langflow.services.tracing.service import TracingService\\n    from langflow.services.variable.service import VariableService\\n\\n# These imports MUST be outside TYPE_CHECKING because FastAPI uses eval_str=True\\n# to evaluate type annotations, and these types are used as return types for\\n# dependency functions that FastAPI evaluates at module load time.\\nfrom lfx.services.auth.base import BaseAuthService  # noqa: TC002\\nfrom lfx.services.authorization.base import BaseAuthorizationService  # noqa: TC002\\nfrom lfx.services.catalog_policy.base import BaseCatalogPolicyService  # noqa: TC002\\nfrom lfx.services.policy_bundle.base import BasePolicyBundleService  # noqa: TC002\\nfrom lfx.services.settings.service import SettingsService  # noqa: TC002\\n\\nfrom langflow.services.job_queue.service import JobQueueService  # noqa: TC001\\nfrom langflow.services.storage.service import StorageService  # noqa: TC001\\nfrom langflow.services.telemetry.service import TelemetryService  # noqa: TC001\\n\\n\\ndef get_service(service_type: ServiceType, default=None):\\n    \\\"\\\"\\\"Retrieves the service instance for the given service type.\\n\\n    Args:\\n        service_type (ServiceType): The type of service to retrieve.\\n        default (ServiceFactory, optional): The default ServiceFactory to use if the service is not found.\\n            Defaults to None.\\n\\n    Returns:\\n        Any: The service instance.\\n\\n    \\\"\\\"\\\"\\n    from lfx.services.manager import get_service_manager\\n\\n    service_manager = get_service_manager()\\n\\n    if not service_manager.are_factories_registered():\\n        # ! This is a workaround to ensure that the service manager is initialized\\n        # ! Not optimal, but it works for now\\n        from langflow.services.manager import ServiceManager\\n\\n        service_manager.register_factories(ServiceManager.get_factories())\\n    return service_manager.get(service_type, default)\\n\\n\\ndef get_telemetry_service() -> TelemetryService:\\n    \\\"\\\"\\\"Retrieves the TelemetryService instance from the service manager.\\n\\n    Returns:\\n        TelemetryService: The TelemetryService instance.\\n    \\\"\\\"\\\"\\n    from langflow.services.telemetry.factory import TelemetryServiceFactory\\n\\n    return get_service(ServiceType.TELEMETRY_SERVICE, TelemetryServiceFactory())\\n\\n\\ndef get_tracing_service() -> TracingService:\\n    \\\"\\\"\\\"Retrieves the TracingService instance from the service manager.\\n\\n    Returns:\\n        TracingService: The TracingService instance.\\n    \\\"\\\"\\\"\\n    from langflow.services.tracing.factory import TracingServiceFactory\\n\\n    return get_service(ServiceType.TRACING_SERVICE, TracingServiceFactory())\\n\\n\\ndef get_state_service() -> StateService:\\n    \\\"\\\"\\\"Retrieves the StateService instance from the service manager.\\n\\n    Returns:\\n        The StateService instance.\\n    \\\"\\\"\\\"\\n    from langflow.services.state.factory import StateServiceFactory\\n\\n    return get_service(ServiceType.STATE_SERVICE, StateServiceFactory())\\n\\n\\ndef get_storage_service() -> StorageService:\\n    \\\"\\\"\\\"Retrieves the storage service instance.\\n\\n    Returns:\\n        The storage service instance.\\n    \\\"\\\"\\\"\\n    from langflow.services.storage.factory import StorageServiceFactory\\n\\n    return get_service(ServiceType.STORAGE_SERVICE, default=StorageServiceFactory())\\n\\n\\ndef get_variable_service() -> VariableService:\\n    \\\"\\\"\\\"Retrieves the VariableService instance from the service manager.\\n\\n    Returns:\\n        The VariableService instance.\\n\\n    \\\"\\\"\\\"\\n    from langflow.services.variable.factory import VariableServiceFactory\\n\\n    return get_service(ServiceType.VARIABLE_SERVICE, VariableServiceFactory())\\n\\n\\ndef is_settings_service_initialized() -> bool:\\n    \\\"\\\"\\\"Check if the SettingsService is already initialized without triggering initialization.\\n\\n    Returns:\\n        bool: True if the SettingsService is already initialized, False otherwise.\\n    \\\"\\\"\\\"\\n    from lfx.services.manager import get_service_manager\\n\\n    return ServiceType.SETTINGS_SERVICE in get_service_manager().services\\n\\n\\ndef get_settings_service() -> SettingsService:\\n    \\\"\\\"\\\"Retrieves the SettingsService instance.\\n\\n    If the service is not yet initialized, it will be initialized before returning.\\n\\n    Returns:\\n        The SettingsService instance.\\n\\n    Raises:\\n        ValueError: If the service cannot be retrieved or initialized.\\n    \\\"\\\"\\\"\\n    from lfx.services.settings.factory import SettingsServiceFactory\\n\\n    return get_service(ServiceType.SETTINGS_SERVICE, SettingsServiceFactory())\\n\\n\\ndef get_db_service() -> DatabaseService:\\n    \\\"\\\"\\\"Retrieves the DatabaseService instance from the service manager.\\n\\n    Returns:\\n        The DatabaseService instance.\\n\\n    \\\"\\\"\\\"\\n    from langflow.services.database.factory import DatabaseServiceFactory\\n\\n    return get_service(ServiceType.DATABASE_SERVICE, DatabaseServiceFactory())\\n\\n\\nasync def get_session() -> AsyncGenerator[AsyncSession, None]:\\n    msg = \\\"get_session is deprecated, use session_scope instead\\\"\\n    raise NotImplementedError(msg)\\n\\n\\n@asynccontextmanager\\nasync def session_scope() -> AsyncGenerator[AsyncSession, None]:\\n    \\\"\\\"\\\"Context manager for managing an async session scope.\\n\\n    This context manager is used to manage an async session scope for database operations.\\n    It ensures that the session is properly committed if no exceptions occur,\\n    and rolled back if an exception is raised.\\n\\n    Yields:\\n        AsyncSession: The async session object.\\n\\n    Raises:\\n        Exception: If an error occurs during the session scope.\\n\\n    \\\"\\\"\\\"\\n    from lfx.services.deps import session_scope as lfx_session_scope\\n\\n    async with lfx_session_scope() as session:\\n        yield session\\n\\n\\ndef get_cache_service() -> Union[CacheService, AsyncBaseCacheService]:  # noqa: UP007\\n    \\\"\\\"\\\"Retrieves the cache service from the service manager.\\n\\n    Returns:\\n        The cache service instance.\\n    \\\"\\\"\\\"\\n    from langflow.services.cache.factory import CacheServiceFactory\\n\\n    return get_service(ServiceType.CACHE_SERVICE, CacheServiceFactory())\\n\\n\\ndef get_shared_component_cache_service() -> CacheService:\\n    \\\"\\\"\\\"Retrieves the cache service from the service manager.\\n\\n    Returns:\\n        The cache service instance.\\n    \\\"\\\"\\\"\\n    from langflow.services.shared_component_cache.factory import SharedComponentCacheServiceFactory\\n\\n    return get_service(ServiceType.SHARED_COMPONENT_CACHE_SERVICE, SharedComponentCacheServiceFactory())\\n\\n\\ndef get_session_service() -> SessionService:\\n    \\\"\\\"\\\"Retrieves the session service from the service manager.\\n\\n    Returns:\\n        The session service instance.\\n    \\\"\\\"\\\"\\n    from langflow.services.session.factory import SessionServiceFactory\\n\\n    return get_service(ServiceType.SESSION_SERVICE, SessionServiceFactory())\\n\\n\\ndef get_task_service() -> TaskService:\\n    \\\"\\\"\\\"Retrieves the TaskService instance from the service manager.\\n\\n    Returns:\\n        The TaskService instance.\\n\\n    \\\"\\\"\\\"\\n    from langflow.services.task.factory import TaskServiceFactory\\n\\n    return get_service(ServiceType.TASK_SERVICE, TaskServiceFactory())\\n\\n\\ndef get_chat_service() -> ChatService:\\n    \\\"\\\"\\\"Get the chat service instance.\\n\\n    Returns:\\n        ChatService: The chat service instance.\\n    \\\"\\\"\\\"\\n    return get_service(ServiceType.CHAT_SERVICE)\\n\\n\\ndef get_store_service() -> StoreService:\\n    \\\"\\\"\\\"Retrieves the StoreService instance from the service manager.\\n\\n    Returns:\\n        StoreService: The StoreService instance.\\n    \\\"\\\"\\\"\\n    return get_service(ServiceType.STORE_SERVICE)\\n\\n\\ndef get_queue_service() -> JobQueueService:\\n    \\\"\\\"\\\"Retrieves the QueueService instance from the service manager.\\\"\\\"\\\"\\n    from langflow.services.job_queue.factory import JobQueueServiceFactory\\n\\n    return get_service(ServiceType.JOB_QUEUE_SERVICE, JobQueueServiceFactory())\\n\\n\\ndef _is_lfx_no_op_auth_service(service: object) -> bool:\\n    \\\"\\\"\\\"Report whether ``service`` is LFX's no-op auth stub.\\n\\n    Resolved through ``sys.modules`` rather than a direct import so that merely asking the\\n    question cannot import ``lfx.services.auth.service`` -- that import is what registers\\n    the stub for the ``auth_service`` slot in the first place. If the module was never\\n    imported the stub cannot be the resolved service anyway.\\n    \\\"\\\"\\\"\\n    lfx_auth_module = sys.modules.get(\\\"lfx.services.auth.service\\\")\\n    return lfx_auth_module is not None and isinstance(service, lfx_auth_module.AuthService)\\n\\n\\ndef get_auth_service() -> BaseAuthService:\\n    \\\"\\\"\\\"Retrieve the authentication service.\\n\\n    LFX's no-op ``AuthService`` claims the ``auth_service`` slot at import time via\\n    ``@register_service(..., override=True)``, and a registered service class always wins\\n    over the factory passed here as a fallback. That stub must never be the resolved\\n    service in a Langflow process: it raises ``NotImplementedError`` for user/token\\n    operations and answers API-key checks with ``None``. ``register_all_service_factories()``\\n    overrides it during startup, so anything touching auth before (or without) that call\\n    would otherwise get the stub -- swap it out for Langflow's implementation here.\\n\\n    A plugin-provided auth service (e.g. SSO, registered through ``lfx.toml``) is a\\n    different class and is left untouched.\\n    \\\"\\\"\\\"\\n    from langflow.services.auth.factory import AuthServiceFactory\\n\\n    service = get_service(ServiceType.AUTH_SERVICE, AuthServiceFactory())\\n    if not _is_lfx_no_op_auth_service(service):\\n        return service\\n\\n    from lfx.services.manager import get_service_manager\\n\\n    from langflow.services.auth.service import AuthService\\n\\n    service_manager = get_service_manager()\\n    service_manager.register_service_class(ServiceType.AUTH_SERVICE, AuthService, override=True)\\n    service_manager.update(ServiceType.AUTH_SERVICE)\\n    return get_service(ServiceType.AUTH_SERVICE, AuthServiceFactory())\\n\\n\\ndef get_authorization_service() -> BaseAuthorizationService:\\n    \\\"\\\"\\\"Retrieve the authorization service.\\\"\\\"\\\"\\n    from langflow.services.authorization.factory import AuthorizationServiceFactory\\n\\n    return get_service(ServiceType.AUTHORIZATION_SERVICE, AuthorizationServiceFactory())\\n\\n\\ndef get_catalog_policy_service() -> BaseCatalogPolicyService:\\n    \\\"\\\"\\\"Retrieve catalog policy through LFX's validated fail-open dependency.\\\"\\\"\\\"\\n    from lfx.services.deps import get_catalog_policy_service as get_lfx_catalog_policy_service\\n\\n    return get_lfx_catalog_policy_service()\\n\\n\\ndef get_policy_bundle_service() -> BasePolicyBundleService:\\n    \\\"\\\"\\\"Retrieve the shared process-local policy bundle coordinator.\\\"\\\"\\\"\\n    from lfx.services.deps import get_policy_bundle_service as get_lfx_policy_bundle_service\\n\\n    return get_lfx_policy_bundle_service()\\n\\n\\ndef get_job_service():\\n    \\\"\\\"\\\"Retrieves the JobService instance from the service manager.\\n\\n    Returns:\\n        JobService: The JobService instance.\\n    \\\"\\\"\\\"\\n    from langflow.services.jobs.factory import JobServiceFactory\\n\\n    return get_service(ServiceType.JOB_SERVICE, JobServiceFactory())\\n\\n\\ndef get_flow_events_service():\\n    from langflow.services.flow_events.factory import FlowEventsServiceFactory\\n\\n    return get_service(ServiceType.FLOW_EVENTS_SERVICE, FlowEventsServiceFactory())\\n\\n\\ndef get_memory_base_service():\\n    \\\"\\\"\\\"Retrieves the MemoryBaseService instance from the service manager.\\\"\\\"\\\"\\n    from langflow.services.memory_base.factory import MemoryBaseServiceFactory\\n\\n    return get_service(ServiceType.MEMORY_BASE_SERVICE, MemoryBaseServiceFactory())\\n\\n\\ndef get_background_execution_service():\\n    \\\"\\\"\\\"Retrieves the BackgroundExecutionService instance from the service manager.\\\"\\\"\\\"\\n    from langflow.services.background_execution.factory import BackgroundExecutionServiceFactory\\n\\n    return get_service(ServiceType.BACKGROUND_EXECUTION_SERVICE, BackgroundExecutionServiceFactory())\\n\\n\\ndef get_telemetry_writer_service():\\n    \\\"\\\"\\\"Return the TelemetryWriterService instance (always registered when langflow is installed).\\\"\\\"\\\"\\n    from langflow.services.telemetry_writer.factory import TelemetryWriterServiceFactory\\n\\n    return get_service(ServiceType.TELEMETRY_WRITER_SERVICE, TelemetryWriterServiceFactory())\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/event_manager.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8433ea10aae88b9f50fde2be6b64992b318c307f70e774e3c50ca3df8c8f1e20\",\"content\":\"\\\"\\\"\\\"Event Manager for Webhook Real-Time Updates.\\n\\nThis module provides an in-memory event broadcasting system for webhook builds.\\nWhen a UI is connected via SSE, it receives real-time build events.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport json\\nimport time\\nfrom collections import defaultdict\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom loguru import logger\\n\\nif TYPE_CHECKING:\\n    from lfx.events.event_manager import EventManager\\n\\n# Constants\\nSSE_QUEUE_MAX_SIZE = 100\\nSSE_EMIT_TIMEOUT_SECONDS = 1.0\\nSECONDS_PER_MINUTE = 60\\n\\n\\nclass WebhookEventManager:\\n    \\\"\\\"\\\"Manages SSE connections and broadcasts build events for webhooks.\\n\\n    When a flow is open in the UI, it subscribes to webhook events.\\n    When a webhook is triggered, events are emitted to all subscribers.\\n\\n    This provides the same visual experience as clicking \\\"Play\\\" in the UI,\\n    but triggered by external webhook calls.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self) -> None:\\n        \\\"\\\"\\\"Initialize the event manager with empty listeners.\\\"\\\"\\\"\\n        self._listeners: dict[str, set[asyncio.Queue]] = defaultdict(set)\\n        self._vertex_start_times: dict[str, dict[str, float]] = defaultdict(dict)\\n        self._lock = asyncio.Lock()\\n\\n    def record_build_start(self, flow_id: str, vertex_id: str) -> None:\\n        \\\"\\\"\\\"Record when a vertex build starts for duration calculation.\\\"\\\"\\\"\\n        self._vertex_start_times[flow_id][vertex_id] = time.time()\\n\\n    def get_build_duration(self, flow_id: str, vertex_id: str) -> str | None:\\n        \\\"\\\"\\\"Get the formatted build duration for a vertex.\\\"\\\"\\\"\\n        start_time = self._vertex_start_times.get(flow_id, {}).get(vertex_id)\\n        if start_time is None:\\n            return None\\n        elapsed = time.time() - start_time\\n        # Clean up\\n        self._vertex_start_times[flow_id].pop(vertex_id, None)\\n        return self._format_duration(elapsed)\\n\\n    @staticmethod\\n    def _format_duration(seconds: float) -> str:\\n        \\\"\\\"\\\"Format duration in a human-readable way.\\\"\\\"\\\"\\n        if seconds < 1:\\n            return f\\\"{int(seconds * 1000)} ms\\\"\\n        if seconds < SECONDS_PER_MINUTE:\\n            return f\\\"{seconds:.1f} s\\\"\\n        minutes = int(seconds // SECONDS_PER_MINUTE)\\n        secs = seconds % SECONDS_PER_MINUTE\\n        return f\\\"{minutes}m {secs:.1f}s\\\"\\n\\n    async def subscribe(self, flow_id: str) -> asyncio.Queue:\\n        \\\"\\\"\\\"Subscribe to receive events for a specific flow.\\n\\n        Args:\\n            flow_id: The flow ID to subscribe to\\n\\n        Returns:\\n            Queue that will receive events for this flow\\n        \\\"\\\"\\\"\\n        queue: asyncio.Queue = asyncio.Queue(maxsize=SSE_QUEUE_MAX_SIZE)\\n        async with self._lock:\\n            self._listeners[flow_id].add(queue)\\n            listener_count = len(self._listeners[flow_id])\\n\\n        logger.info(f\\\"New subscriber for flow {flow_id}. Total listeners: {listener_count}\\\")\\n        return queue\\n\\n    async def unsubscribe(self, flow_id: str, queue: asyncio.Queue) -> None:\\n        \\\"\\\"\\\"Unsubscribe from flow events.\\n\\n        Args:\\n            flow_id: The flow ID to unsubscribe from\\n            queue: The queue to remove\\n        \\\"\\\"\\\"\\n        async with self._lock:\\n            if flow_id in self._listeners:\\n                self._listeners[flow_id].discard(queue)\\n                listener_count = len(self._listeners[flow_id])\\n\\n                # Clean up empty sets\\n                if not self._listeners[flow_id]:\\n                    del self._listeners[flow_id]\\n                    logger.info(f\\\"All subscribers disconnected for flow {flow_id}\\\")\\n                else:\\n                    logger.info(f\\\"Subscriber disconnected from flow {flow_id}. Remaining: {listener_count}\\\")\\n\\n    async def emit(self, flow_id: str, event_type: str, data: Any) -> None:\\n        \\\"\\\"\\\"Emit an event to all subscribers of a flow.\\n\\n        Args:\\n            flow_id: The flow ID to emit to\\n            event_type: Type of event (build_start, end_vertex, etc.)\\n            data: Event data (will be JSON serialized)\\n        \\\"\\\"\\\"\\n        async with self._lock:\\n            listeners = self._listeners.get(flow_id, set()).copy()\\n\\n        if not listeners:\\n            # No one listening, skip emission (performance optimization)\\n            return\\n\\n        # Prepare event\\n        event = {\\n            \\\"event\\\": event_type,\\n            \\\"data\\\": data,\\n            \\\"timestamp\\\": time.time(),\\n        }\\n\\n        # Send to all queues\\n        dead_queues: set[asyncio.Queue] = set()\\n\\n        for queue in listeners:\\n            try:\\n                await asyncio.wait_for(queue.put(event), timeout=SSE_EMIT_TIMEOUT_SECONDS)\\n            except asyncio.TimeoutError:\\n                # Queue is full (slow consumer), skip this event\\n                logger.warning(f\\\"Queue full for flow {flow_id}, dropping event {event_type}\\\")\\n            except Exception as e:  # noqa: BLE001\\n                # Queue is closed or broken, mark for removal\\n                logger.error(f\\\"Error putting event in queue for flow {flow_id}: {e}\\\")\\n                dead_queues.add(queue)\\n\\n        # Clean up dead queues\\n        if dead_queues:\\n            async with self._lock:\\n                if flow_id in self._listeners:\\n                    self._listeners[flow_id] -= dead_queues\\n                    if not self._listeners[flow_id]:\\n                        del self._listeners[flow_id]\\n\\n    def has_listeners(self, flow_id: str) -> bool:\\n        \\\"\\\"\\\"Check if there are any active listeners for a flow.\\\"\\\"\\\"\\n        return flow_id in self._listeners and len(self._listeners[flow_id]) > 0\\n\\n\\n# Module-level instance (can be replaced in tests via dependency injection)\\n# TODO: Consider migrating to langflow's service manager pattern for better DI\\n_webhook_event_manager: WebhookEventManager | None = None\\n\\n\\ndef get_webhook_event_manager() -> WebhookEventManager:\\n    \\\"\\\"\\\"Get the webhook event manager instance.\\n\\n    Returns:\\n        The WebhookEventManager singleton instance.\\n    \\\"\\\"\\\"\\n    global _webhook_event_manager  # noqa: PLW0603\\n    if _webhook_event_manager is None:\\n        _webhook_event_manager = WebhookEventManager()\\n    return _webhook_event_manager\\n\\n\\n# Backwards compatibility alias\\nwebhook_event_manager = get_webhook_event_manager()\\n\\n\\nclass WebhookForwardingQueue:\\n    \\\"\\\"\\\"Queue adapter that forwards events to the webhook SSE.\\n\\n    This class implements the queue interface expected by EventManager,\\n    forwarding events to connected SSE clients instead of storing them.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, flow_id: str, run_id: str | None = None):\\n        self.flow_id = flow_id\\n        self.run_id = run_id\\n        self._manager = get_webhook_event_manager()\\n\\n    def put_nowait(self, item: tuple[str, bytes, float]) -> None:\\n        \\\"\\\"\\\"Forward event to webhook SSE.\\n\\n        Args:\\n            item: Tuple of (event_id, data_bytes, timestamp) from EventManager\\n        \\\"\\\"\\\"\\n        _event_id, data_bytes, _timestamp = item\\n        try:\\n            data_str = data_bytes.decode(\\\"utf-8\\\").strip()\\n            if not data_str:\\n                return\\n\\n            event_data = json.loads(data_str)\\n            event_type = event_data.get(\\\"event\\\")\\n            event_payload = event_data.get(\\\"data\\\", {})\\n\\n            if self.run_id and isinstance(event_payload, dict):\\n                event_payload[\\\"run_id\\\"] = self.run_id\\n\\n            self._emit_async(event_type, event_payload)\\n        except Exception as exc:  # noqa: BLE001\\n            logger.debug(f\\\"Failed to forward event to webhook SSE: flow_id={self.flow_id}, error={exc}\\\")\\n\\n    def _emit_async(self, event_type: str, event_payload: Any) -> None:\\n        \\\"\\\"\\\"Emit event asynchronously (fire and forget).\\\"\\\"\\\"\\n        try:\\n            loop = asyncio.get_running_loop()\\n            task = loop.create_task(self._manager.emit(self.flow_id, event_type, event_payload))\\n            # Suppress exceptions from fire-and-forget task\\n            task.add_done_callback(lambda t: t.exception() if not t.cancelled() else None)\\n        except RuntimeError:\\n            pass  # No running loop\\n\\n\\ndef create_webhook_event_manager(flow_id: str, run_id: str | None = None) -> EventManager:\\n    \\\"\\\"\\\"Create an EventManager that forwards events to the webhook SSE.\\n\\n    This allows webhook execution to emit real-time build events\\n    (end_vertex with build_data, build_start, etc.) to connected UI clients.\\n\\n    Args:\\n        flow_id: The flow ID to emit events for\\n        run_id: Optional run ID to include in events\\n\\n    Returns:\\n        EventManager configured to forward events to webhook SSE\\n    \\\"\\\"\\\"\\n    from lfx.events.event_manager import EventManager\\n\\n    queue = WebhookForwardingQueue(flow_id, run_id)\\n    manager = EventManager(queue)\\n\\n    # Register all standard events\\n    manager.register_event(\\\"on_token\\\", \\\"token\\\")\\n    manager.register_event(\\\"on_vertices_sorted\\\", \\\"vertices_sorted\\\")\\n    manager.register_event(\\\"on_error\\\", \\\"error\\\")\\n    manager.register_event(\\\"on_end\\\", \\\"end\\\")\\n    manager.register_event(\\\"on_message\\\", \\\"add_message\\\")\\n    manager.register_event(\\\"on_remove_message\\\", \\\"remove_message\\\")\\n    manager.register_event(\\\"on_end_vertex\\\", \\\"end_vertex\\\")\\n    manager.register_event(\\\"on_build_start\\\", \\\"build_start\\\")\\n    manager.register_event(\\\"on_build_end\\\", \\\"build_end\\\")\\n\\n    return manager\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/factory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"972077c84bfa7e387678d15658c7af009c0bf024effb4ef069ac659b5f68f00e\",\"content\":\"import importlib\\nimport inspect\\nfrom typing import get_type_hints\\n\\nfrom cachetools import LRUCache, cached\\nfrom lfx.log.logger import logger\\n\\nfrom langflow.services.base import Service\\nfrom langflow.services.schema import ServiceType\\n\\n\\nclass ServiceFactory:\\n    def __init__(\\n        self,\\n        service_class: type[Service] | None = None,\\n    ) -> None:\\n        if service_class is None:\\n            msg = \\\"service_class is required\\\"\\n            raise ValueError(msg)\\n        self.service_class = service_class\\n        self.dependencies = infer_service_types(self, import_all_services_into_a_dict())\\n\\n    def create(self, *args, **kwargs) -> \\\"Service\\\":\\n        return self.service_class(*args, **kwargs)\\n\\n\\ndef hash_factory(factory: ServiceFactory) -> str:\\n    return factory.service_class.__name__\\n\\n\\ndef hash_dict(d: dict) -> str:\\n    return str(d)\\n\\n\\ndef hash_infer_service_types_args(factory: ServiceFactory, available_services=None) -> str:\\n    factory_hash = hash_factory(factory)\\n    services_hash = hash_dict(available_services)\\n    return f\\\"{factory_hash}_{services_hash}\\\"\\n\\n\\n@cached(cache=LRUCache(maxsize=10), key=hash_infer_service_types_args)\\ndef infer_service_types(factory: ServiceFactory, available_services=None) -> list[\\\"ServiceType\\\"]:\\n    create_method = factory.create\\n\\n    type_hints = get_type_hints(create_method, globalns=available_services)\\n\\n    service_types = []\\n    for param_name, param_type in type_hints.items():\\n        # Skip the return type if it's included in type hints\\n        if param_name == \\\"return\\\":\\n            continue\\n\\n        # Convert the type to the expected enum format directly without appending \\\"_SERVICE\\\"\\n        type_name = param_type.__name__.upper().replace(\\\"SERVICE\\\", \\\"_SERVICE\\\")\\n\\n        try:\\n            # Attempt to find a matching enum value\\n            service_type = ServiceType[type_name]\\n            service_types.append(service_type)\\n        except KeyError as e:\\n            msg = f\\\"No matching ServiceType for parameter type: {param_type.__name__}\\\"\\n            raise ValueError(msg) from e\\n    return service_types\\n\\n\\n@cached(cache=LRUCache(maxsize=1))\\ndef import_all_services_into_a_dict():\\n    # Services are all in langflow.services.{service_name}.service\\n    # and are subclass of Service\\n    # We want to import all of them and put them in a dict\\n    # to use as globals\\n    from langflow.services.base import Service\\n\\n    services = {}\\n    for service_type in ServiceType:\\n        try:\\n            service_name = ServiceType(service_type).value.replace(\\\"_service\\\", \\\"\\\")\\n\\n            # Shared services live in lfx so both the standalone runtime and\\n            # the Langflow application use the same contract and instance.\\n            if service_name in {\\\"mcp_composer\\\", \\\"model_provider_policy\\\", \\\"policy_bundle\\\"}:\\n                module_name = f\\\"lfx.services.{service_name}.service\\\"\\n            else:\\n                module_name = f\\\"langflow.services.{service_name}.service\\\"\\n\\n            module = importlib.import_module(module_name)\\n            services.update(\\n                {\\n                    name: obj\\n                    for name, obj in inspect.getmembers(module, inspect.isclass)\\n                    if isinstance(obj, type) and issubclass(obj, Service) and obj is not Service\\n                }\\n            )\\n        except Exception as exc:\\n            logger.exception(exc)\\n            msg = \\\"Could not initialize services. Please check your settings.\\\"\\n            raise RuntimeError(msg) from exc\\n    # Import settings and auth bases from lfx (used in type hints but not langflow Service subclasses)\\n    from lfx.services.auth.base import BaseAuthService\\n    from lfx.services.authorization.base import BaseAuthorizationService\\n    from lfx.services.catalog_policy.base import BaseCatalogPolicyService\\n    from lfx.services.policy_bundle.base import BasePolicyBundleService\\n    from lfx.services.settings.service import SettingsService\\n\\n    services[\\\"BaseAuthService\\\"] = BaseAuthService\\n    services[\\\"BaseAuthorizationService\\\"] = BaseAuthorizationService\\n    services[\\\"BaseCatalogPolicyService\\\"] = BaseCatalogPolicyService\\n    services[\\\"BasePolicyBundleService\\\"] = BasePolicyBundleService\\n    services[\\\"SettingsService\\\"] = SettingsService\\n    return services\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/flow/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/flow/flow_runner.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1aad5c1b4cd005a61a6cce2d79e0a7347692e74b7d26fbdfe2daa84c8e66749b\",\"content\":\"import json\\nimport os\\nfrom pathlib import Path\\nfrom uuid import UUID, uuid4\\n\\nimport aiofiles\\nfrom lfx.graph import Graph\\nfrom lfx.graph.vertex.param_handler import ParameterHandler\\nfrom lfx.log.logger import configure, logger\\nfrom lfx.utils.util import update_settings\\nfrom sqlmodel import delete, select\\n\\nfrom langflow.api.utils import cascade_delete_flow\\nfrom langflow.load.utils import replace_tweaks_with_env\\nfrom langflow.processing.process import process_tweaks, run_graph\\nfrom langflow.services.cache.service import AsyncBaseCacheService\\nfrom langflow.services.database.migration import get_current_alembic_heads\\nfrom langflow.services.database.models import Flow, User, Variable\\nfrom langflow.services.database.utils import initialize_database\\nfrom langflow.services.deps import get_auth_service, get_cache_service, get_storage_service, session_scope\\n\\n\\nclass LangflowRunnerExperimental:\\n    \\\"\\\"\\\"LangflowRunnerExperimental orchestrates flow execution without a dedicated server.\\n\\n    .. warning::\\n        This class is currently **experimental** and in a **beta phase**.\\n        Its API and behavior may change in future releases. Use with caution in production environments.\\n\\n    Usage:\\n    ------\\n    Instantiate the class and call the `run` method with the desired flow and input.\\n\\n    Example:\\n        runner = LangflowRunnerExperimental()\\n        result = await runner.run(flow=\\\"path/to/flow.json\\\", input_value=\\\"Hello\\\", session_id=str(uuid.uuid4()))\\n\\n    \\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        *,\\n        should_initialize_db: bool = True,\\n        log_level: str | None = None,\\n        log_file: str | None = None,\\n        log_rotation: str | None = None,\\n        disable_logs: bool = False,\\n    ):\\n        self.should_initialize_db = should_initialize_db\\n        log_file_path = Path(log_file) if log_file else None\\n        configure(\\n            log_level=log_level,\\n            log_file=log_file_path,\\n            log_rotation=log_rotation,\\n            disable=disable_logs,\\n        )\\n\\n    async def run(\\n        self,\\n        session_id: str,  # UUID required currently\\n        flow: Path | str | dict,\\n        input_value: str,\\n        *,\\n        input_type: str = \\\"chat\\\",\\n        output_type: str = \\\"all\\\",\\n        cache: str | None = None,\\n        stream: bool = False,\\n        user_id: str | None = None,\\n        generate_user: bool = False,  # If True, generates a new user for the flow\\n        cleanup: bool = True,  # If True, clears flow state after execution\\n        tweaks_values: dict | None = None,\\n    ):\\n        try:\\n            await logger.ainfo(f\\\"Start Handling {session_id=}\\\")\\n            await self.init_db_if_needed()\\n            # Update settings with cache and components path\\n            await update_settings(cache=cache)\\n            if generate_user:\\n                user = await self.generate_user()\\n                user_id = str(user.id)\\n            flow_dict = await self.prepare_flow_and_add_to_db(\\n                flow=flow,\\n                user_id=user_id,\\n                session_id=session_id,\\n                tweaks_values=tweaks_values,\\n            )\\n            return await self.run_flow(\\n                input_value=input_value,\\n                session_id=session_id,\\n                flow_dict=flow_dict,\\n                input_type=input_type,\\n                output_type=output_type,\\n                user_id=user_id,\\n                stream=stream,\\n            )\\n        finally:\\n            if cleanup and user_id:\\n                await self.clear_user_state(user_id=user_id)\\n\\n    async def run_flow(\\n        self,\\n        *,\\n        input_value: str,\\n        session_id: str,\\n        flow_dict: dict,\\n        input_type: str = \\\"chat\\\",\\n        output_type: str = \\\"all\\\",\\n        user_id: str | None = None,\\n        stream: bool = False,\\n    ):\\n        graph = await self.create_graph_from_flow(session_id, flow_dict, user_id=user_id)\\n        try:\\n            result = await self.run_graph(input_value, input_type, output_type, session_id, graph, stream=stream)\\n        finally:\\n            await self.clear_flow_state(flow_dict)\\n        await logger.ainfo(f\\\"Finish Handling {session_id=}\\\")\\n        return result\\n\\n    async def prepare_flow_and_add_to_db(\\n        self,\\n        *,\\n        flow: Path | str | dict,\\n        user_id: str | None = None,\\n        custom_flow_id: str | None = None,\\n        session_id: str | None = None,\\n        tweaks_values: dict | None = None,\\n    ) -> dict:\\n        flow_dict = await self.get_flow_dict(flow)\\n        session_id = session_id or custom_flow_id or str(uuid4())\\n        if custom_flow_id:\\n            flow_dict[\\\"id\\\"] = custom_flow_id\\n        flow_dict = self.process_tweaks(flow_dict, tweaks_values=tweaks_values)\\n        await self.clear_flow_state(flow_dict)\\n        await self.add_flow_to_db(flow_dict, user_id=user_id)\\n        return flow_dict\\n\\n    def process_tweaks(self, flow_dict: dict, tweaks_values: dict | None = None) -> dict:\\n        tweaks: dict | None = None\\n        tweaks_values = tweaks_values or os.environ.copy()\\n        for vertex in Graph.from_payload(flow_dict).vertices:\\n            param_handler = ParameterHandler(vertex, get_storage_service())\\n            field_params, load_from_db_fields = param_handler.process_field_parameters()\\n            for db_field in load_from_db_fields:\\n                if field_params[db_field]:\\n                    tweaks = tweaks or {}\\n                    tweaks[vertex.id] = tweaks.get(vertex.id, {})\\n                    tweaks[vertex.id][db_field] = field_params[db_field]\\n        if tweaks is not None:\\n            tweaks = replace_tweaks_with_env(tweaks=tweaks, env_vars=tweaks_values)\\n            # Built here from resolved load_from_db values, not sent by a caller,\\n            # so the deployment policy does not judge them. The floor still does.\\n            flow_dict = process_tweaks(flow_dict, tweaks, caller_supplied=False)\\n\\n        # Recursively update load_from_db fields\\n        def update_load_from_db(obj):\\n            if isinstance(obj, dict):\\n                for key, value in obj.items():\\n                    if key == \\\"load_from_db\\\" and value is True:\\n                        obj[key] = False\\n                    else:\\n                        update_load_from_db(value)\\n            elif isinstance(obj, list):\\n                for item in obj:\\n                    update_load_from_db(item)\\n\\n        update_load_from_db(flow_dict)\\n        return flow_dict\\n\\n    async def generate_user(self) -> User:\\n        async with session_scope() as session:\\n            user_id = str(uuid4())\\n            hashed = get_auth_service().get_password_hash(str(uuid4()))\\n            user = User(id=user_id, username=user_id, password=hashed, is_active=True)\\n            session.add(user)\\n            await session.flush()\\n            await session.refresh(user)\\n            return user\\n\\n    @staticmethod\\n    async def add_flow_to_db(flow_dict: dict, user_id: str | None):\\n        async with session_scope() as session:\\n            flow_db = Flow(\\n                name=flow_dict.get(\\\"name\\\"), id=UUID(flow_dict[\\\"id\\\"]), data=flow_dict.get(\\\"data\\\", {}), user_id=user_id\\n            )\\n            session.add(flow_db)\\n\\n    @staticmethod\\n    async def run_graph(\\n        input_value: str,\\n        input_type: str,\\n        output_type: str,\\n        session_id: str,\\n        graph: Graph,\\n        *,\\n        stream: bool,\\n    ):\\n        return await run_graph(\\n            graph=graph,\\n            session_id=session_id,\\n            input_value=input_value,\\n            fallback_to_env_vars=True,\\n            input_type=input_type,\\n            output_type=output_type,\\n            stream=stream,\\n        )\\n\\n    @staticmethod\\n    async def create_graph_from_flow(session_id: str, flow_dict: dict, user_id: str | None = None):\\n        graph = Graph.from_payload(\\n            payload=flow_dict, flow_id=flow_dict[\\\"id\\\"], flow_name=flow_dict.get(\\\"name\\\"), user_id=user_id\\n        )\\n        graph.session_id = session_id\\n        graph.set_run_id(session_id)\\n        graph.user_id = user_id\\n        await graph.initialize_run()\\n        return graph\\n\\n    @staticmethod\\n    async def clear_flow_state(flow_dict: dict):\\n        cache_service = get_cache_service()\\n        if isinstance(cache_service, AsyncBaseCacheService):\\n            await cache_service.clear()\\n        else:\\n            cache_service.clear()\\n        async with session_scope() as session:\\n            flow_id = flow_dict[\\\"id\\\"]\\n            uuid_obj = flow_id if isinstance(flow_id, UUID) else UUID(str(flow_id))\\n            await cascade_delete_flow(session, uuid_obj)\\n\\n    @staticmethod\\n    async def clear_user_state(user_id: str):\\n        async with session_scope() as session:\\n            flows = await session.exec(select(Flow.id).where(Flow.user_id == user_id))\\n            flow_ids: list[UUID] = [fid for fid in flows.scalars().all() if fid is not None]\\n            for flow_id in flow_ids:\\n                await cascade_delete_flow(session, flow_id)\\n            await session.exec(delete(Variable).where(Variable.user_id == user_id))\\n            await session.exec(delete(User).where(User.id == user_id))\\n\\n    async def init_db_if_needed(self):\\n        if not await self.database_exists_check() and self.should_initialize_db:\\n            await logger.ainfo(\\\"Initializing database...\\\")\\n            await initialize_database(fix_migration=True)\\n            self.should_initialize_db = False\\n            await logger.ainfo(\\\"Database initialized.\\\")\\n\\n    @staticmethod\\n    async def database_exists_check():\\n        async with session_scope() as session:\\n            return bool(await get_current_alembic_heads(session))\\n\\n    @staticmethod\\n    async def get_flow_dict(flow: Path | str | dict) -> dict:\\n        if isinstance(flow, str | Path):\\n            async with aiofiles.open(Path(flow), encoding=\\\"utf-8\\\") as f:\\n                content = await f.read()\\n                return json.loads(content)\\n        # If input is a dictionary, assume it's a JSON object\\n        elif isinstance(flow, dict):\\n            return flow\\n        error_msg = \\\"Input must be a file path (str or Path object) or a JSON object (dict).\\\"\\n        raise TypeError(error_msg)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/flow_events/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"24f16507ff9a9b69fa5be12d50e8e00c07a3cd0e655ee5cb06f41ed51046b8fe\",\"content\":\"from langflow.services.flow_events.service import FLOW_EVENT_TYPES, FlowEvent, FlowEventsService\\n\\n__all__ = [\\\"FLOW_EVENT_TYPES\\\", \\\"FlowEvent\\\", \\\"FlowEventsService\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/flow_events/factory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"23c51f4e27c1912ddd73c931981077bd7f38f240ce06753a33b062e0b7e1fd3d\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom typing_extensions import override\\n\\nfrom langflow.services.factory import ServiceFactory\\nfrom langflow.services.flow_events.service import FlowEventsService\\n\\nif TYPE_CHECKING:\\n    from lfx.services.settings.service import SettingsService\\n\\n\\nclass FlowEventsServiceFactory(ServiceFactory):\\n    def __init__(self) -> None:\\n        super().__init__(FlowEventsService)\\n\\n    @override\\n    def create(self, settings_service: SettingsService):\\n        return FlowEventsService(cache_dir=settings_service.settings.cache_dir)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/flow_events/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ebd407b6065ff48205df8d2b7eb92b9535085bba32b51ee529433ac3037deaf2\",\"content\":\"from __future__ import annotations\\n\\nimport sqlite3\\nimport tempfile\\nimport threading\\nimport time\\nfrom dataclasses import dataclass\\nfrom pathlib import Path\\nfrom typing import Literal, get_args\\n\\nfrom langflow.services.base import Service\\n\\nFLOW_EVENT_TYPES = Literal[\\n    \\\"component_added\\\",\\n    \\\"component_removed\\\",\\n    \\\"component_configured\\\",\\n    \\\"connection_added\\\",\\n    \\\"connection_removed\\\",\\n    \\\"flow_updated\\\",\\n    \\\"flow_settled\\\",\\n]\\n\\n\\n@dataclass(frozen=True)\\nclass FlowEvent:\\n    type: str\\n    timestamp: float\\n    summary: str = \\\"\\\"\\n\\n\\n_SCHEMA = \\\"\\\"\\\"\\nCREATE TABLE IF NOT EXISTS flow_events (\\n    flow_id    TEXT NOT NULL,\\n    ts         REAL NOT NULL,\\n    type       TEXT NOT NULL,\\n    summary    TEXT NOT NULL DEFAULT '',\\n    expires_at REAL NOT NULL\\n);\\nCREATE INDEX IF NOT EXISTS idx_flow_events_flow_ts ON flow_events(flow_id, ts);\\nCREATE INDEX IF NOT EXISTS idx_flow_events_expires ON flow_events(expires_at);\\n\\\"\\\"\\\"\\n\\n\\nclass FlowEventsService(Service):\\n    \\\"\\\"\\\"SQLite-backed event queue keyed by flow_id.\\n\\n    Uses Python's stdlib sqlite3 in WAL mode for cross-worker visibility (multiple\\n    uvicorn/gunicorn workers share the same on-disk database file). TTL-based\\n    cleanup is performed lazily on each write and read.\\n\\n    Limitations:\\n    - Events are ephemeral: lost on disk cleanup or container restart.\\n      This is acceptable since events only drive transient UI state (banner, canvas lock).\\n    - Multiple browser tabs polling the same flow will each see events independently\\n      but may show slightly different banner/lock state due to independent polling cycles.\\n    \\\"\\\"\\\"\\n\\n    name = \\\"flow_events_service\\\"\\n\\n    TTL_SECONDS: float = 60.0\\n    SETTLE_TIMEOUT: float = 10.0\\n    MAX_EVENTS_PER_FLOW: int = 1000\\n\\n    _VALID_EVENT_TYPES: frozenset[str] = frozenset(get_args(FLOW_EVENT_TYPES))\\n\\n    def __init__(self, cache_dir: str | Path | None = None) -> None:\\n        if cache_dir is None:\\n            cache_dir = Path(tempfile.gettempdir()) / \\\"langflow_flow_events\\\"\\n        cache_dir = Path(cache_dir)\\n        cache_dir.mkdir(parents=True, exist_ok=True)\\n        self._db_path = cache_dir / \\\"flow_events.sqlite\\\"\\n        # isolation_level=None puts pysqlite in autocommit mode so we manage\\n        # transactions explicitly via BEGIN/COMMIT.\\n        self._conn = sqlite3.connect(\\n            str(self._db_path),\\n            isolation_level=None,\\n            check_same_thread=False,\\n            timeout=5.0,\\n        )\\n        # Serialize use of the single connection across asyncio tasks / FastAPI threads\\n        # in this worker. WAL handles cross-worker concurrency.\\n        self._lock = threading.Lock()\\n        with self._lock:\\n            self._conn.execute(\\\"PRAGMA journal_mode=WAL\\\")\\n            self._conn.execute(\\\"PRAGMA synchronous=NORMAL\\\")\\n            self._conn.execute(\\\"PRAGMA busy_timeout=5000\\\")\\n            self._conn.executescript(_SCHEMA)\\n\\n    def append(self, flow_id: str, event_type: str, summary: str = \\\"\\\") -> FlowEvent:\\n        if event_type not in self._VALID_EVENT_TYPES:\\n            msg = f\\\"Invalid event type: {event_type!r}. Must be one of {sorted(self._VALID_EVENT_TYPES)}\\\"\\n            raise ValueError(msg)\\n\\n        now = time.time()\\n        event = FlowEvent(type=event_type, timestamp=now, summary=summary)\\n        expires_at = now + self.TTL_SECONDS\\n\\n        with self._lock:\\n            self._conn.execute(\\\"BEGIN IMMEDIATE\\\")\\n            try:\\n                # Opportunistic TTL cleanup across all flows.\\n                self._conn.execute(\\\"DELETE FROM flow_events WHERE expires_at < ?\\\", (now,))\\n                self._conn.execute(\\n                    \\\"INSERT INTO flow_events (flow_id, ts, type, summary, expires_at) VALUES (?, ?, ?, ?, ?)\\\",\\n                    (flow_id, now, event_type, summary, expires_at),\\n                )\\n                # Bound per-flow size: keep only the most recent MAX_EVENTS_PER_FLOW rows.\\n                # Order by (ts, rowid) so events appended in the same microsecond have a\\n                # stable, insertion-aware ordering when picking which rows to drop.\\n                self._conn.execute(\\n                    \\\"\\\"\\\"\\n                    DELETE FROM flow_events\\n                    WHERE rowid IN (\\n                        SELECT rowid FROM flow_events\\n                        WHERE flow_id = ?\\n                        ORDER BY ts DESC, rowid DESC\\n                        LIMIT -1 OFFSET ?\\n                    )\\n                    \\\"\\\"\\\",\\n                    (flow_id, self.MAX_EVENTS_PER_FLOW),\\n                )\\n                self._conn.execute(\\\"COMMIT\\\")\\n            except Exception:\\n                self._conn.execute(\\\"ROLLBACK\\\")\\n                raise\\n\\n        return event\\n\\n    def get_since(self, flow_id: str, since: float) -> tuple[list[FlowEvent], bool]:\\n        \\\"\\\"\\\"Return (events_after_since, settled).\\n\\n        settled is True if:\\n        - No events exist for this flow, OR\\n        - A flow_settled event exists after `since`, OR\\n        - The most recent event is older than SETTLE_TIMEOUT seconds.\\n        \\\"\\\"\\\"\\n        now = time.time()\\n        with self._lock:\\n            rows = self._conn.execute(\\n                \\\"\\\"\\\"\\n                SELECT type, ts, summary\\n                FROM flow_events\\n                WHERE flow_id = ? AND expires_at >= ?\\n                ORDER BY ts ASC, rowid ASC\\n                \\\"\\\"\\\",\\n                (flow_id, now),\\n            ).fetchall()\\n\\n        all_events = [FlowEvent(type=r[0], timestamp=r[1], summary=r[2]) for r in rows]\\n        after = [e for e in all_events if e.timestamp > since]\\n\\n        if not after and not all_events:\\n            return [], True\\n\\n        if any(e.type == \\\"flow_settled\\\" for e in after):\\n            return after, True\\n\\n        last_event_age = time.time() - all_events[-1].timestamp\\n        settled = last_event_age >= self.SETTLE_TIMEOUT\\n\\n        return after, settled\\n\\n    async def teardown(self) -> None:\\n        with self._lock:\\n            self._conn.close()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/job_queue/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/job_queue/factory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bb970a2c7f0affbeef60992ea42fe2742b875e730b765b75b3c0f94125e54604\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom typing_extensions import override\\n\\nfrom langflow.services.factory import ServiceFactory\\nfrom langflow.services.job_queue.service import JobQueueService, RedisJobQueueService\\n\\nif TYPE_CHECKING:\\n    from lfx.services.settings.service import SettingsService\\n\\n\\nclass JobQueueServiceFactory(ServiceFactory):\\n    def __init__(self):\\n        super().__init__(JobQueueService)\\n\\n    @override\\n    def create(self, settings_service: SettingsService):\\n        settings = settings_service.settings\\n        if settings.job_queue_type == \\\"redis\\\":\\n            host = settings.redis_queue_host or settings.redis_host\\n            port = settings.redis_queue_port or settings.redis_port\\n            return RedisJobQueueService(\\n                host=host,\\n                port=port,\\n                db=settings.redis_queue_db,\\n                url=settings.redis_queue_url,\\n                ttl=settings.redis_queue_ttl,\\n                startup_grace_s=settings.redis_queue_startup_grace_s,\\n                cancel_marker_ttl=settings.redis_queue_cancel_marker_ttl,\\n                cancel_channel_enabled=settings.redis_queue_cancel_channel_enabled,\\n                polling_stale_threshold_s=settings.redis_queue_polling_stale_threshold_s,\\n                polling_watchdog_interval_s=settings.redis_queue_polling_watchdog_interval_s,\\n            )\\n        return JobQueueService()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/job_queue/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7f48d86ad73b93d9291b5978c2539b5f7b63d640f127eb1feb7db4a39ac7fbed\",\"content\":\"from __future__ import annotations\\n\\nimport asyncio\\nimport contextlib\\nimport time\\nfrom typing import TYPE_CHECKING, Any\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Coroutine\\n\\nfrom lfx.log.logger import logger\\n\\nfrom langflow.events.event_manager import EventManager\\nfrom langflow.services.base import Service\\n\\nif TYPE_CHECKING:\\n    from uuid import UUID\\n\\n# Sentinel value written to Redis Streams to signal end-of-stream to consumers.\\n_STREAM_SENTINEL_DATA = b\\\"__sentinel__\\\"\\n\\n# Shared Redis key prefix for job event streams. Producer (RedisJobQueueService) and\\n# consumer (RedisQueueWrapper) MUST agree on this \u2014 keep a single source of truth.\\n_STREAM_PREFIX = \\\"langflow:queue:\\\"\\n_OWNER_PREFIX = \\\"langflow:owner:\\\"\\n# Pub/Sub channel for cross-worker cancel signals. Any worker can publish here;\\n# the producer worker subscribes when the job starts and cancels the local task.\\n_CANCEL_CHANNEL_PREFIX = \\\"langflow:cancel:\\\"\\n# Activity heartbeat key written by polling and streaming responses. The\\n# polling watchdog scans these to detect abandoned builds (client gave up).\\n_ACTIVITY_PREFIX = \\\"langflow:activity:\\\"\\n# Presence key for jobs started through the public (unauthenticated) build\\n# endpoint. Allows the public events/cancel endpoints to reject job_ids that\\n# belong to private-flow builds. Uses the same TTL as the stream/owner keys.\\n_PUBLIC_JOB_PREFIX = \\\"langflow:public_job:\\\"\\n\\n\\nclass JobQueueNotFoundError(Exception):\\n    \\\"\\\"\\\"Exception raised when a job queue is not found.\\\"\\\"\\\"\\n\\n    def __init__(self, job_id: str) -> None:\\n        self.job_id = job_id\\n        super().__init__(f\\\"Job queue not found for job_id: {job_id}\\\")\\n\\n\\nclass JobQueueBackendUnavailableError(Exception):\\n    \\\"\\\"\\\"Raised when the configured job queue backend (e.g. Redis) is unreachable.\\n\\n    Route handlers translate this into a clean HTTP 503 so callers get an\\n    actionable message instead of a raw redis ``ConnectionError`` stack trace.\\n    \\\"\\\"\\\"\\n\\n\\ndef _is_backend_connection_error(exc: BaseException) -> bool:\\n    \\\"\\\"\\\"Return True if *exc* indicates the Redis backend is unreachable.\\n\\n    Covers both builtin socket-level errors and redis-py's own\\n    ``ConnectionError`` / ``TimeoutError`` (which are NOT subclasses of the\\n    builtins). ``redis`` is an optional dependency, so its exception types are\\n    imported lazily \u2014 this only runs on a failure path, never the hot path.\\n    \\\"\\\"\\\"\\n    if isinstance(exc, ConnectionError | TimeoutError | OSError):\\n        return True\\n    try:\\n        from redis.exceptions import ConnectionError as RedisConnectionError\\n        from redis.exceptions import TimeoutError as RedisTimeoutError\\n    except ImportError:\\n        return False\\n    return isinstance(exc, RedisConnectionError | RedisTimeoutError)\\n\\n\\ndef _redact_url_credentials(url: str) -> str:\\n    \\\"\\\"\\\"Strip userinfo from a URL so credentials never reach logs or HTTP responses.\\\"\\\"\\\"\\n    from urllib.parse import urlparse, urlunparse\\n\\n    try:\\n        parsed = urlparse(url)\\n    except ValueError:\\n        return \\\"<redacted>\\\"\\n    if parsed.username is None and parsed.password is None:\\n        return url\\n    host = parsed.hostname or \\\"\\\"\\n    netloc = f\\\"***@{host}:{parsed.port}\\\" if parsed.port else f\\\"***@{host}\\\"\\n    return urlunparse(parsed._replace(netloc=netloc))\\n\\n\\nclass JobQueueService(Service):\\n    \\\"\\\"\\\"Asynchronous service for managing job-specific queues and their associated tasks.\\n\\n    This service allows clients to:\\n      - Create dedicated asyncio queues for individual jobs.\\n      - Associate each queue with an EventManager, enabling event-driven handling.\\n      - Launch and manage asynchronous tasks that process these job queues.\\n      - Safely clean up resources by cancelling active tasks and emptying queues.\\n      - Automatically perform periodic cleanup of inactive or completed job queues.\\n\\n    The cleanup process follows a two-phase approach:\\n      1. When a task is cancelled or fails, it is marked for cleanup by setting a timestamp\\n      2. The actual cleanup only occurs after CLEANUP_GRACE_PERIOD seconds have elapsed\\n         since the task was marked\\n\\n    Attributes:\\n        name (str): Unique identifier for the service.\\n        _queues (dict[str, tuple[asyncio.Queue, EventManager, asyncio.Task | None, float | None]]):\\n            Dictionary mapping job IDs to a tuple containing:\\n              * The job's asyncio.Queue instance.\\n              * The associated EventManager instance.\\n              * The asyncio.Task processing the job (if any).\\n              * The cleanup timestamp (if any).\\n        _cleanup_task (asyncio.Task | None): Background task for periodic cleanup.\\n        _closed (bool): Flag indicating whether the service is currently active.\\n        CLEANUP_GRACE_PERIOD (int): Number of seconds to wait after a task is marked for cleanup\\n            before actually removing it. This grace period allows for:\\n              * Pending operations to complete\\n              * Related systems to finish their work\\n              * Inspection or recovery if needed\\n            Default is 300 seconds (5 minutes).\\n\\n    Example:\\n        service = JobQueueService()\\n        await service.start()\\n        queue, event_manager = service.create_queue(\\\"job123\\\")\\n        service.start_job(\\\"job123\\\", some_async_coroutine())\\n        # Retrieve and use the queue data as needed\\n        data = service.get_queue_data(\\\"job123\\\")\\n        await service.cleanup_job(\\\"job123\\\")\\n        await service.stop()\\n    \\\"\\\"\\\"\\n\\n    name = \\\"job_queue_service\\\"\\n\\n    # Backend label used on OpenTelemetry metrics. Subclasses override.\\n    _backend_label: str = \\\"memory\\\"\\n\\n    def __init__(self) -> None:\\n        \\\"\\\"\\\"Initialize the JobQueueService.\\n\\n        Sets up the internal registry for job queues, initializes the cleanup task, and sets the service state\\n        to active.\\n        \\\"\\\"\\\"\\n        self._queues: dict[str, tuple[asyncio.Queue, EventManager, asyncio.Task | None, float | None]] = {}\\n        self._job_owners: dict[str, UUID] = {}\\n        self._public_jobs: set[str] = set()\\n        self._cleanup_task: asyncio.Task | None = None\\n        self._closed = False\\n        self.ready = False\\n        self.CLEANUP_GRACE_PERIOD = 300  # 5 minutes before cleaning up marked tasks\\n        # Cached OpenTelemetry handle (resolved lazily on first emit).\\n        # _otel_resolved is True after the first lookup attempt, including failures,\\n        # so we don't retry on every bump. _otel remains None when lookup fails.\\n        self._otel: Any = None\\n        self._otel_resolved: bool = False\\n\\n    def _get_otel(self) -> Any:\\n        \\\"\\\"\\\"Best-effort lookup of the OpenTelemetry singleton. Cached after first call.\\n\\n        Returns the ``ot`` handle, or ``None`` if telemetry is unavailable. Never raises \u2014\\n        instrumentation must not break the queue.\\n        \\\"\\\"\\\"\\n        if self._otel_resolved:\\n            return self._otel\\n        self._otel_resolved = True\\n        try:\\n            from langflow.services.deps import get_telemetry_service\\n\\n            self._otel = get_telemetry_service().ot\\n        except Exception:  # noqa: BLE001 - telemetry must not crash the queue\\n            self._otel = None\\n        return self._otel\\n\\n    def _emit_otel_counter(self, metric_name: str, labels: dict[str, str], value: float = 1.0) -> None:\\n        \\\"\\\"\\\"Best-effort OpenTelemetry counter bump. Silent on failure.\\\"\\\"\\\"\\n        ot = self._get_otel()\\n        if ot is None:\\n            return\\n        with contextlib.suppress(Exception):\\n            ot.increment_counter(metric_name, labels, value)\\n\\n    def _emit_otel_up_down(self, metric_name: str, value: float, labels: dict[str, str]) -> None:\\n        \\\"\\\"\\\"Best-effort OpenTelemetry up-down counter delta. Silent on failure.\\\"\\\"\\\"\\n        ot = self._get_otel()\\n        if ot is None:\\n            return\\n        with contextlib.suppress(Exception):\\n            ot.up_down_counter(metric_name, value, labels)\\n\\n    def is_started(self) -> bool:\\n        \\\"\\\"\\\"Check if the JobQueueService has started.\\n\\n        Returns:\\n            bool: True if the service has started, False otherwise.\\n        \\\"\\\"\\\"\\n        return self._cleanup_task is not None\\n\\n    @property\\n    def cross_worker_cancel_enabled(self) -> bool:\\n        \\\"\\\"\\\"True when this backend can deliver cancels across worker processes.\\n\\n        Callers using ``signal_cancel`` to reach a build owned by another\\n        worker must check this first: when False, ``signal_cancel`` exists but\\n        is a no-op (returns 0 without setting the persistent marker), so\\n        treating its return value as a successful cross-worker dispatch is\\n        misleading.\\n        \\\"\\\"\\\"\\n        return False\\n\\n    def set_ready(self) -> None:\\n        if not self.is_started():\\n            self.start()\\n        super().set_ready()\\n\\n    def start(self) -> None:\\n        \\\"\\\"\\\"Start the JobQueueService and begin the periodic cleanup routine.\\n\\n        This method marks the service as active and launches a background task that\\n        periodically checks and cleans up job queues whose tasks have been completed or cancelled.\\n        \\\"\\\"\\\"\\n        self._closed = False\\n        self._cleanup_task = asyncio.create_task(self._periodic_cleanup())\\n        logger.debug(\\\"JobQueueService started: periodic cleanup task initiated.\\\")\\n\\n    async def stop(self) -> None:\\n        \\\"\\\"\\\"Gracefully stop the JobQueueService by terminating background operations and cleaning up all resources.\\n\\n        This coroutine performs the following steps:\\n            1. Marks the service as closed, preventing further job queue creation.\\n            2. Cancels the background periodic cleanup task and awaits its termination.\\n            3. Iterates over all registered job queues to clean up their resources\u2014cancelling active tasks and\\n            clearing queued items.\\n        \\\"\\\"\\\"\\n        self._closed = True\\n        if self._cleanup_task:\\n            self._cleanup_task.cancel()\\n            await asyncio.wait([self._cleanup_task])\\n            if not self._cleanup_task.cancelled():\\n                exc = self._cleanup_task.exception()\\n                if exc is not None:\\n                    raise exc\\n\\n        # Clean up each registered job queue.\\n        for job_id in list(self._queues.keys()):\\n            await self.cleanup_job(job_id)\\n        await logger.adebug(\\\"JobQueueService stopped: all job queues have been cleaned up.\\\")\\n\\n    async def teardown(self) -> None:\\n        await self.stop()\\n\\n    def metrics_snapshot(self) -> dict[str, Any]:\\n        \\\"\\\"\\\"Return a read-only snapshot of queue metrics for ops/monitoring.\\n\\n        Subclasses extend this dict with backend-specific fields (e.g.\\n        :class:`RedisJobQueueService` adds bridge / wrapper / cancel stats).\\n        Callers MUST NOT mutate the returned mapping \u2014 it is a fresh copy.\\n        \\\"\\\"\\\"\\n        return {\\n            \\\"backend\\\": \\\"memory\\\",\\n            \\\"active_jobs\\\": len(self._queues),\\n        }\\n\\n    def create_queue(self, job_id: str) -> tuple[asyncio.Queue, EventManager]:\\n        \\\"\\\"\\\"Create and register a new queue along with its corresponding event manager for a job.\\n\\n        Args:\\n            job_id (str): Unique identifier for the job.\\n\\n        Returns:\\n            tuple[asyncio.Queue, EventManager]: A tuple containing:\\n                - The asyncio.Queue instance for handling the job's tasks or messages.\\n                - The EventManager instance for event handling tied to the queue.\\n        \\\"\\\"\\\"\\n        if self._closed:\\n            msg = \\\"Queue service is closed\\\"\\n            raise RuntimeError(msg)\\n\\n        existing_queue = self._queues.get(job_id)\\n        if existing_queue:\\n            msg = f\\\"Queue for job_id {job_id} already exists\\\"\\n            raise ValueError(msg)\\n\\n        main_queue: asyncio.Queue = asyncio.Queue()\\n        event_manager: EventManager = self._create_default_event_manager(main_queue)\\n\\n        # Register the queue without an active task.\\n        self._queues[job_id] = (main_queue, event_manager, None, None)\\n        self._emit_otel_up_down(\\\"langflow_job_queue_active_jobs\\\", 1, {\\\"backend\\\": self._backend_label})\\n        logger.debug(f\\\"Queue and event manager successfully created for job_id {job_id}\\\")\\n        return main_queue, event_manager\\n\\n    def start_job(self, job_id: str, task_coro: Coroutine) -> None:\\n        \\\"\\\"\\\"Start an asynchronous task for a given job, replacing any existing active task.\\n\\n        The method performs the following:\\n          - Verifies the presence of a registered queue for the job.\\n          - Cancels any currently running task associated with the job.\\n          - Launches a new asynchronous task using the provided coroutine.\\n          - Updates the internal registry with the new task.\\n\\n        The coroutine is wrapped with :meth:`_guarded_task` so that any unhandled\\n        exception causes an ``on_error`` event to be emitted and the end-of-stream\\n        sentinel to be written before the task exits. This guarantees that\\n        cross-worker consumers can always distinguish a clean end from a crash \u2014\\n        both paths terminate with the sentinel in the Redis Stream, but a crash\\n        will be preceded by an ``error`` event.\\n\\n        Args:\\n            job_id (str): Unique identifier for the job.\\n            task_coro: A coroutine representing the job's asynchronous task.\\n        \\\"\\\"\\\"\\n        if job_id not in self._queues:\\n            msg = f\\\"No queue found for job_id {job_id}\\\"\\n            logger.error(msg)\\n            raise ValueError(msg)\\n\\n        if self._closed:\\n            msg = \\\"Queue service is closed\\\"\\n            logger.error(msg)\\n            raise RuntimeError(msg)\\n\\n        main_queue, event_manager, existing_task, _ = self._queues[job_id]\\n        if existing_task and not existing_task.done():\\n            logger.debug(f\\\"Existing task for job_id {job_id} detected; cancelling it.\\\")\\n            existing_task.cancel()\\n\\n        # Wrap the coroutine so that any crash emits on_error + sentinel before exit.\\n        task = asyncio.create_task(self._guarded_task(job_id, task_coro, event_manager, main_queue))\\n        self._queues[job_id] = (main_queue, event_manager, task, None)\\n        logger.debug(f\\\"New task started for job_id {job_id}\\\")\\n\\n    @staticmethod\\n    async def _guarded_task(\\n        job_id: str,\\n        task_coro: Coroutine,\\n        event_manager: EventManager,\\n        main_queue: asyncio.Queue,\\n    ) -> None:\\n        \\\"\\\"\\\"Run *task_coro* and guarantee the end-of-stream sentinel is written on crash.\\n\\n        A well-behaved build coroutine (``generate_flow_events``) writes the sentinel\\n        itself after emitting ``on_end``. If the coroutine raises an unexpected\\n        exception before doing so, this wrapper:\\n\\n        1. Emits an ``on_error`` event so consumers can distinguish a crash from a\\n           clean end \u2014 both cases deliver ``(None, None, ts)`` as the terminal item,\\n           but a crash is always preceded by an error event in the stream.\\n        2. Puts the raw ``(None, None, ts)`` sentinel so the bridge flushes and\\n           writes ``_STREAM_SENTINEL_DATA`` to the Redis Stream before cleanup\\n           deletes the key, preventing consumers from hanging indefinitely.\\n\\n        ``asyncio.CancelledError`` is not caught here; the caller\\n        (``cancel_job`` / ``cancel_flow_build``) is responsible for user-initiated\\n        cancel paths and any backend-specific end-of-stream delivery.\\n        \\\"\\\"\\\"\\n        try:\\n            await task_coro\\n        except asyncio.CancelledError:\\n            raise\\n        except Exception as exc:\\n            await logger.aerror(\\n                f\\\"Unhandled exception in build task for job_id {job_id}: {exc}\\\",\\n                exc_info=True,\\n            )\\n            # 1. Emit an error event so the stream carries the failure record.\\n            with contextlib.suppress(Exception):\\n                event_manager.on_error(data={\\\"error\\\": str(exc)})\\n            # 2. Write the sentinel so the bridge terminates and flushes to Redis.\\n            with contextlib.suppress(Exception):\\n                main_queue.put_nowait((None, None, time.time()))\\n            raise\\n\\n    def get_queue_data(self, job_id: str) -> tuple[asyncio.Queue, EventManager, asyncio.Task | None, float | None]:\\n        \\\"\\\"\\\"Retrieve the complete data structure associated with a job's queue.\\n\\n        Args:\\n            job_id (str): Unique identifier for the job.\\n\\n        Returns:\\n            tuple[asyncio.Queue, EventManager, asyncio.Task | None, float | None]:\\n                A tuple containing the job's main queue, its linked event manager, the associated task (if any),\\n                and the cleanup timestamp (if any).\\n\\n        Raises:\\n            JobQueueNotFoundError: If the job_id is not found.\\n            RuntimeError: If the service is closed.\\n        \\\"\\\"\\\"\\n        if self._closed:\\n            msg = f\\\"Queue service is closed for job_id: {job_id}\\\"\\n            raise RuntimeError(msg)\\n\\n        try:\\n            return self._queues[job_id]\\n        except KeyError as exc:\\n            raise JobQueueNotFoundError(job_id) from exc\\n\\n    async def register_job_owner(self, job_id: str, user_id: UUID) -> None:\\n        \\\"\\\"\\\"Register the authenticated user who initiated a build job.\\\"\\\"\\\"\\n        self._job_owners[job_id] = user_id\\n\\n    async def get_job_owner(self, job_id: str) -> UUID | None:\\n        \\\"\\\"\\\"Return the user ID that owns a job, or None if not tracked.\\\"\\\"\\\"\\n        return self._job_owners.get(job_id)\\n\\n    async def register_public_job(self, job_id: str) -> None:\\n        \\\"\\\"\\\"Mark a job as started through the public (unauthenticated) build endpoint.\\n\\n        Only jobs registered here may be accessed via the public events/cancel endpoints.\\n        This prevents unauthenticated callers from reading or cancelling private-flow jobs.\\n\\n        Async (even though the base implementation is a synchronous set add):\\n        RedisJobQueueService overrides this to also persist the marker to Redis\\n        *before returning*, so a request landing on a different worker immediately\\n        after registration sees the marker via is_public_job_async.\\n        \\\"\\\"\\\"\\n        self._public_jobs.add(job_id)\\n\\n    def is_public_job(self, job_id: str) -> bool:\\n        \\\"\\\"\\\"Return True if the job was started through the public build endpoint.\\\"\\\"\\\"\\n        return job_id in self._public_jobs\\n\\n    async def is_public_job_async(self, job_id: str) -> bool:\\n        \\\"\\\"\\\"Return True if the job was started through the public build endpoint.\\n\\n        Base implementation is synchronous (in-memory set lookup).\\n        RedisJobQueueService overrides this to also check Redis for cross-worker\\n        correctness in multi-worker deployments.\\n        \\\"\\\"\\\"\\n        return self.is_public_job(job_id)\\n\\n    async def cleanup_job(self, job_id: str) -> None:\\n        \\\"\\\"\\\"Clean up and release resources for a specific job.\\n\\n        The cleanup process includes:\\n          1. Verifying if the job's queue is registered.\\n          2. Cancelling the running task (if active) and awaiting its termination.\\n          3. Clearing all items from the job's queue.\\n          4. Removing the job's entry from the internal registry.\\n\\n        Args:\\n            job_id (str): Unique identifier for the job to be cleaned up.\\n        \\\"\\\"\\\"\\n        if job_id not in self._queues:\\n            await logger.adebug(f\\\"No queue found for job_id {job_id} during cleanup.\\\")\\n            return\\n\\n        await logger.adebug(f\\\"Commencing cleanup for job_id {job_id}\\\")\\n        main_queue, _event_manager, task, _ = self._queues[job_id]\\n\\n        # Cancel the associated task if it is still running.\\n        if task and not task.done():\\n            await logger.adebug(f\\\"Cancelling active task for job_id {job_id}\\\")\\n            task.cancel()\\n            try:\\n                await task\\n            except asyncio.CancelledError as exc:\\n                # Check if this was a user-initiated cancellation (user called task.cancel())\\n                if task.cancelled():\\n                    # User-initiated cancellation so we explicitly called task.cancel() above\\n                    await logger.adebug(f\\\"Task for job_id {job_id} was successfully cancelled.\\\")\\n                    # Re-raise with user cancellation message code\\n                    exc.args = (\\\"LANGFLOW_USER_CANCELLED\\\",)\\n                    raise\\n                # System-initiated cancellation for other reasons\\n                await logger.adebug(f\\\"Task for job_id {job_id} was cancelled by system.\\\")\\n                exc.args = (\\\"LANGFLOW_SYSTEM_CANCELLED\\\",)\\n                raise\\n            except Exception as exc:\\n                await logger.aerror(f\\\"Error in task for job_id {job_id} during cancellation: {exc}\\\")\\n                raise\\n        await logger.adebug(f\\\"Task cancellation complete for job_id {job_id}\\\")\\n\\n        # Clear the queue since we just cancelled the task or it has completed\\n        items_cleared = 0\\n        while not main_queue.empty():\\n            try:\\n                main_queue.get_nowait()\\n                items_cleared += 1\\n            except asyncio.QueueEmpty:\\n                break\\n\\n        await logger.adebug(f\\\"Removed {items_cleared} items from queue for job_id {job_id}\\\")\\n        # Remove the job entry from the registry\\n        if self._queues.pop(job_id, None) is not None:\\n            self._emit_otel_up_down(\\\"langflow_job_queue_active_jobs\\\", -1, {\\\"backend\\\": self._backend_label})\\n        self._job_owners.pop(job_id, None)\\n        self._public_jobs.discard(job_id)\\n        await logger.adebug(f\\\"Cleanup successful for job_id {job_id}: resources have been released.\\\")\\n\\n    async def cancel_job(self, job_id: str) -> None:\\n        \\\"\\\"\\\"Cancel an active job and release its resources.\\n\\n        The in-memory backend can use the normal cleanup path directly. Backends\\n        with cross-worker consumers can override this hook when cancellation needs\\n        extra coordination before resource teardown.\\n        \\\"\\\"\\\"\\n        await self.cleanup_job(job_id)\\n\\n    async def _periodic_cleanup(self) -> None:\\n        \\\"\\\"\\\"Execute a periodic task that cleans up completed or cancelled job queues.\\n\\n        This internal coroutine continuously:\\n          - Sleeps for a fixed interval (60 seconds).\\n          - Initiates the cleanup of job queues by calling _cleanup_old_queues.\\n          - Monitors and logs any exceptions during the cleanup cycle.\\n\\n        The loop terminates when the service is marked as closed.\\n        \\\"\\\"\\\"\\n        while not self._closed:\\n            try:\\n                await asyncio.sleep(60)  # Sleep for 60 seconds before next cleanup attempt.\\n                await self._cleanup_old_queues()\\n            except asyncio.CancelledError:\\n                await logger.adebug(\\\"Periodic cleanup task received cancellation signal.\\\")\\n                raise\\n            except Exception as exc:  # noqa: BLE001\\n                await logger.aerror(f\\\"Exception encountered during periodic cleanup: {exc}\\\")\\n\\n    async def _cleanup_old_queues(self) -> None:\\n        \\\"\\\"\\\"Scan all registered job queues and clean up those with completed, failed or orphaned tasks.\\\"\\\"\\\"\\n        current_time = asyncio.get_running_loop().time()\\n\\n        for job_id in list(self._queues.keys()):\\n            _, _, task, cleanup_time = self._queues[job_id]\\n\\n            should_cleanup = False\\n            cleanup_reason = \\\"\\\"\\n\\n            # Case 1: Orphaned queue (created but task never started)\\n            if task is None:\\n                should_cleanup = True\\n                cleanup_reason = \\\"Orphaned queue (no task associated)\\\"\\n            # Case 2: Task has finished (Success, Failure, or Cancellation)\\n            elif task.done():\\n                should_cleanup = True\\n                if task.cancelled():\\n                    cleanup_reason = \\\"Task cancelled\\\"\\n                elif task.exception() is not None:\\n                    # Don't try to log the exception yet as it might be handled elsewhere;\\n                    # the grace period allows other systems to inspect it if needed.\\n                    cleanup_reason = \\\"Task failed with exception\\\"\\n                else:\\n                    cleanup_reason = \\\"Task completed successfully\\\"\\n\\n            if should_cleanup:\\n                if cleanup_time is None:\\n                    # Mark for cleanup by setting the timestamp\\n                    self._queues[job_id] = (\\n                        self._queues[job_id][0],\\n                        self._queues[job_id][1],\\n                        self._queues[job_id][2],\\n                        current_time,\\n                    )\\n                    await logger.adebug(f\\\"Job queue for job_id {job_id} marked for cleanup - {cleanup_reason}\\\")\\n                elif current_time - cleanup_time >= self.CLEANUP_GRACE_PERIOD:\\n                    # Enough time has passed, perform the actual cleanup\\n                    await logger.adebug(f\\\"Cleaning up job_id {job_id} after grace period due to: {cleanup_reason}\\\")\\n                    await self.cleanup_job(job_id)\\n\\n    def _create_default_event_manager(self, queue: asyncio.Queue) -> EventManager:\\n        \\\"\\\"\\\"Creates the default event manager with predefined events.\\n\\n        Args:\\n            queue (asyncio.Queue): The queue to be associated with the event manager.\\n\\n        Returns:\\n            EventManager: The configured EventManager instance.\\n        \\\"\\\"\\\"\\n        manager = EventManager(queue)\\n        # Registering predefined events\\n        event_names_types = [\\n            (\\\"on_token\\\", \\\"token\\\"),\\n            (\\\"on_vertices_sorted\\\", \\\"vertices_sorted\\\"),\\n            (\\\"on_error\\\", \\\"error\\\"),\\n            (\\\"on_end\\\", \\\"end\\\"),\\n            (\\\"on_message\\\", \\\"add_message\\\"),\\n            (\\\"on_remove_message\\\", \\\"remove_message\\\"),\\n            (\\\"on_end_vertex\\\", \\\"end_vertex\\\"),\\n            (\\\"on_build_start\\\", \\\"build_start\\\"),\\n            (\\\"on_build_end\\\", \\\"build_end\\\"),\\n            (\\\"on_log\\\", \\\"log\\\"),\\n        ]\\n        for name, event_type in event_names_types:\\n            manager.register_event(name, event_type)\\n        return manager\\n\\n\\nclass RedisQueueWrapper:\\n    \\\"\\\"\\\"Consumer-side asyncio.Queue interface backed by a Redis Stream.\\n\\n    Created by :class:`RedisJobQueueService` when :meth:`get_queue_data` is called\\n    for a job that was started on a different worker process. A background\\n    ``_fill_task`` reads from the Redis Stream and populates a local buffer so that\\n    the rest of ``build.py`` can use the familiar ``asyncio.Queue`` interface.\\n\\n    Stream protocol\\n    ---------------\\n    * Normal event  \u2192  ``XADD key * event_id <str> data <bytes> ts <float>``\\n    * End-of-stream \u2192  ``XADD key * event_id __sentinel__ data __sentinel__ ts <float>``\\n\\n    Self-termination\\n    ----------------\\n    The fill task exits when it:\\n    1. Receives the end-of-stream sentinel from the stream, **or**\\n    2. Detects that the stream key no longer exists (job was cleaned up).\\n    In both cases it puts ``(None, None, timestamp)`` into the local buffer so\\n    that consumers in ``build.py`` see the normal end-of-stream signal.\\n    \\\"\\\"\\\"\\n\\n    STREAM_PREFIX = _STREAM_PREFIX\\n\\n    # Tunables for the background fill task. Kept as class-level constants so\\n    # subclasses or tests can override without touching the loop body.\\n    _XREAD_BLOCK_MS = 1000  # how long XREAD blocks waiting for new entries\\n    _XREAD_BATCH_COUNT = 100  # max entries fetched per XREAD call\\n    _READ_ERROR_BACKOFF_S = 0.5  # backoff after a transient XREAD failure\\n    # Default grace period. Overridable per-instance via the constructor so the\\n    # value can be driven from settings (LANGFLOW_REDIS_QUEUE_STARTUP_GRACE_S).\\n    # Protects against the early-poll race where the consumer wrapper is created\\n    # before the producer worker has issued its first XADD.\\n    _STARTUP_GRACE_S = 30.0\\n    # Hard cap on in-process buffered events per consumer. Bounds memory when a\\n    # slow client falls behind a fast producer; without it, the buffer can grow\\n    # without limit until the consumer drains it.\\n    _BUFFER_MAXSIZE = 10_000\\n\\n    def __init__(self, job_id: str, client: Any, ttl: int, startup_grace_s: float | None = None) -> None:\\n        self._job_id = job_id\\n        self._client = client\\n        self._ttl = ttl\\n        # Allow callers to override the class-level grace period (driven by settings).\\n        if startup_grace_s is not None:\\n            self._STARTUP_GRACE_S = startup_grace_s\\n        self._buffer: asyncio.Queue = asyncio.Queue(maxsize=self._BUFFER_MAXSIZE)\\n        self._last_id = \\\"0-0\\\"  # read from the beginning of the stream\\n        # Flips to True the first time XREAD returns messages for this stream.\\n        # Until then, \\\"stream key does not exist\\\" is NOT treated as end-of-stream\\n        # \u2014 it just means the producer hasn't written its first event yet.\\n        self._observed_stream: bool = False\\n        self._created_at: float = time.monotonic()\\n        # Flips to True after the very first XREAD call returns (regardless of\\n        # whether it had results). empty() returns False until this flag is set\\n        # so that the while-not-empty drain loop in build.py suspends on get()\\n        # and lets the fill task populate the buffer before the loop exits.\\n        self._first_read_done: bool = False\\n        self._fill_task: asyncio.Task = asyncio.create_task(self._fill_from_redis())\\n        # Defense-in-depth: if the fill task is cancelled or crashes with an\\n        # unhandled exception, deliver an end-of-stream sentinel into the buffer\\n        # so consumers waiting on ``await get()`` are unblocked. The clean exit\\n        # paths inside ``_fill_from_redis`` already put the sentinel themselves;\\n        # this callback only fires when those paths are bypassed.\\n        self._fill_task.add_done_callback(self._on_fill_done)\\n\\n    def _on_fill_done(self, task: asyncio.Task) -> None:\\n        \\\"\\\"\\\"Ensure the consumer is unblocked if the fill task exits unexpectedly.\\n\\n        A clean exit (sentinel received, stream cleaned up, grace exhausted)\\n        already puts the sentinel into the buffer. Cancellation and unhandled\\n        exceptions skip that path \u2014 this callback catches both gaps so the\\n        consumer's ``await queue.get()`` never blocks forever.\\n\\n        Done callbacks run synchronously, so we use the non-blocking\\n        ``put_nowait``. If the buffer happens to be at capacity (slow consumer\\n        + bounded buffer), evict the oldest item to make room: losing one event\\n        is strictly preferable to leaving the consumer stuck.\\n        \\\"\\\"\\\"\\n        if not task.cancelled() and task.exception() is None:\\n            # Clean exit: _fill_from_redis already put the sentinel.\\n            return\\n        if not task.cancelled():\\n            exc = task.exception()\\n            logger.error(\\n                f\\\"RedisQueueWrapper fill task raised for job {self._job_id}: {exc!r} \\\"\\n                \\\"\u2014 delivering end-of-stream sentinel so the consumer is not left hanging.\\\"\\n            )\\n        if self._buffer.full():\\n            with contextlib.suppress(asyncio.QueueEmpty):\\n                self._buffer.get_nowait()\\n        with contextlib.suppress(asyncio.QueueFull):\\n            self._buffer.put_nowait((None, None, time.time()))\\n\\n    @property\\n    def _stream_key(self) -> str:\\n        return f\\\"{self.STREAM_PREFIX}{self._job_id}\\\"\\n\\n    async def _fill_from_redis(self) -> None:\\n        \\\"\\\"\\\"Read events from the Redis Stream and forward them to the local buffer.\\\"\\\"\\\"\\n        _error_start: float | None = None\\n        try:\\n            while True:\\n                try:\\n                    results = await self._client.xread(\\n                        {self._stream_key: self._last_id},\\n                        block=self._XREAD_BLOCK_MS,\\n                        count=self._XREAD_BATCH_COUNT,\\n                    )\\n                except Exception as exc:  # noqa: BLE001\\n                    now = time.monotonic()\\n                    if _error_start is None:\\n                        _error_start = now\\n                    elapsed = now - _error_start\\n                    await logger.awarning(\\n                        f\\\"RedisQueueWrapper read error for {self._job_id} (elapsed {elapsed:.1f}s): {exc}\\\"\\n                    )\\n                    if elapsed >= self._STARTUP_GRACE_S:\\n                        await logger.aerror(\\n                            f\\\"RedisQueueWrapper: persistent Redis error for {self._job_id} \\\"\\n                            f\\\"after {elapsed:.1f}s; delivering end-of-stream sentinel.\\\"\\n                        )\\n                        await self._buffer.put((None, None, time.time()))\\n                        return\\n                    await asyncio.sleep(self._READ_ERROR_BACKOFF_S)\\n                    continue\\n                _error_start = None  # reset on successful XREAD\\n\\n                self._first_read_done = True\\n                if results:\\n                    self._observed_stream = True\\n                    for _, messages in results:\\n                        for msg_id, fields in messages:\\n                            data = fields.get(b\\\"data\\\")\\n                            ts = float(fields.get(b\\\"ts\\\", b\\\"0\\\") or b\\\"0\\\")\\n                            if data == _STREAM_SENTINEL_DATA:\\n                                await self._buffer.put((None, None, ts))\\n                                self._last_id = msg_id.decode() if isinstance(msg_id, bytes) else msg_id\\n                                return\\n                            event_id = (fields.get(b\\\"event_id\\\") or b\\\"\\\").decode()\\n                            await self._buffer.put((event_id, data, ts))\\n                            # Advance cursor only after the item is safely in the buffer.\\n                            # Advancing before the await would skip this message on cancellation.\\n                            self._last_id = msg_id.decode() if isinstance(msg_id, bytes) else msg_id\\n                # No results within the block timeout.\\n                elif not self._observed_stream:\\n                    # Stream hasn't appeared yet \u2014 the producer may not have issued its\\n                    # first XADD (early-poll race between workers). Keep blocking until\\n                    # the startup grace period expires to avoid a false end-of-stream.\\n                    elapsed = time.monotonic() - self._created_at\\n                    if elapsed > self._STARTUP_GRACE_S:\\n                        await logger.awarning(\\n                            f\\\"RedisQueueWrapper: stream for {self._job_id} never appeared \\\"\\n                            f\\\"after {elapsed:.1f}s; treating as end-of-stream.\\\"\\n                        )\\n                        await self._buffer.put((None, None, time.time()))\\n                        return\\n                    # Otherwise keep looping \u2014 next XREAD will block again.\\n                elif not await self._client.exists(self._stream_key):\\n                    # Stream was observed before and the key is now gone \u2014 the job\\n                    # was cleaned up on the producer side; signal end-of-stream.\\n                    await self._buffer.put((None, None, time.time()))\\n                    return\\n        except asyncio.CancelledError:\\n            return\\n\\n    # ------------------------------------------------------------------\\n    # asyncio.Queue-compatible interface used by build.py\\n    # ------------------------------------------------------------------\\n\\n    def empty(self) -> bool:\\n        # Before the first XREAD completes the local buffer is empty even if\\n        # Redis already has events queued. Returning False here causes the\\n        # while-not-empty drain loop in build.py to suspend on await get(),\\n        # which yields to the event loop so the fill task can run its first\\n        # XREAD and populate the buffer. After warm-up, delegate to the\\n        # actual buffer state.\\n        return self._first_read_done and self._buffer.empty()\\n\\n    async def get(self):\\n        return await self._buffer.get()\\n\\n    def get_nowait(self):\\n        return self._buffer.get_nowait()\\n\\n    def put_nowait(self, item) -> None:\\n        \\\"\\\"\\\"No-op: this wrapper is consumer-only; producers write via the bridge.\\\"\\\"\\\"\\n\\n    def fill_done(self) -> bool:\\n        \\\"\\\"\\\"Return True if the background fill task has finished.\\\"\\\"\\\"\\n        return self._fill_task.done()\\n\\n    async def cancel(self) -> None:\\n        \\\"\\\"\\\"Cancel the background fill task.\\\"\\\"\\\"\\n        if not self._fill_task.done():\\n            self._fill_task.cancel()\\n            with contextlib.suppress(asyncio.CancelledError):\\n                await self._fill_task\\n\\n    async def finish_with_sentinel(self) -> None:\\n        \\\"\\\"\\\"Stop the fill task and wake active consumers with an end-of-stream item.\\n\\n        Mirrors ``_on_fill_done``: when the buffer is full because the consumer\\n        is gone or slow, evict the oldest item and ``put_nowait`` the sentinel\\n        instead of awaiting. Losing one buffered event is strictly preferable\\n        to a teardown that hangs forever on a closed-out consumer.\\n        \\\"\\\"\\\"\\n        if not self._fill_task.done():\\n            self._fill_task.cancel()\\n            with contextlib.suppress(asyncio.CancelledError):\\n                await self._fill_task\\n        if self._buffer.full():\\n            with contextlib.suppress(asyncio.QueueEmpty):\\n                self._buffer.get_nowait()\\n        with contextlib.suppress(asyncio.QueueFull):\\n            self._buffer.put_nowait((None, None, time.time()))\\n\\n\\nclass RedisJobQueueService(JobQueueService):\\n    \\\"\\\"\\\"Redis-backed job queue service for multi-worker deployments.\\n\\n    Replaces the in-memory :class:`JobQueueService` with one that uses Redis\\n    Streams as a shared event bus, so that build events published by the worker\\n    that started the job can be consumed by any other worker that receives the\\n    subsequent HTTP poll / streaming request.\\n\\n    Architecture\\n    ------------\\n    Producer (build worker)::\\n\\n        EventManager \u2192 local asyncio.Queue \u2192 bridge coroutine \u2192 Redis Stream\\n\\n    Consumer (poll worker)::\\n\\n        Redis Stream \u2192 RedisQueueWrapper fill task \u2192 local buffer \u2192 HTTP response\\n\\n    Configuration\\n    -------------\\n    Set ``LANGFLOW_JOB_QUEUE_TYPE=redis`` and, optionally:\\n\\n    * ``LANGFLOW_REDIS_QUEUE_DB`` (default ``1``, separate from cache DB ``0``)\\n    * ``LANGFLOW_REDIS_QUEUE_URL`` (full URL, overrides host/port/db)\\n    * ``LANGFLOW_REDIS_QUEUE_HOST`` / ``LANGFLOW_REDIS_QUEUE_PORT``\\n\\n    Cross-worker cancel\\n    -------------------\\n    When ``cancel_channel_enabled=True`` (the default), the service runs a\\n    single Redis PSUBSCRIBE dispatcher per worker over the pattern\\n    ``langflow:cancel:*``. Any worker can publish a cancel signal via\\n    :meth:`signal_cancel`; the worker that owns the job (i.e. has an entry in\\n    ``self._queues``) cancels the local task, flushes a sentinel through the\\n    bridge so cross-worker consumers see end-of-stream promptly, and triggers\\n    fast cleanup of the Redis stream + owner keys.\\n\\n    Note: callers of :meth:`signal_cancel` are responsible for any\\n    authorization checks. The HTTP cancel endpoint already verifies job\\n    ownership before calling through; programmatic callers must do the same.\\n\\n    Cross-worker passive disconnect is also wired through: when a client closes\\n    its streaming connection on a worker that doesn't own the job, the streaming\\n    response's disconnect handler calls :meth:`signal_cancel` so the owning\\n    worker stops emitting events promptly instead of running to natural\\n    completion. See ``langflow.api.build.create_flow_response``.\\n    \\\"\\\"\\\"\\n\\n    STREAM_PREFIX = _STREAM_PREFIX\\n    OWNER_PREFIX = _OWNER_PREFIX\\n    CANCEL_CHANNEL_PREFIX = _CANCEL_CHANNEL_PREFIX\\n    ACTIVITY_PREFIX = _ACTIVITY_PREFIX\\n    PUBLIC_JOB_PREFIX = _PUBLIC_JOB_PREFIX\\n\\n    _backend_label: str = \\\"redis\\\"\\n\\n    def __init__(\\n        self,\\n        host: str = \\\"localhost\\\",\\n        port: int = 6379,\\n        db: int = 1,\\n        url: str | None = None,\\n        ttl: int = 3600,\\n        startup_grace_s: float = 30.0,\\n        cancel_marker_ttl: int = 60,\\n        polling_stale_threshold_s: float = 90.0,\\n        polling_watchdog_interval_s: float = 15.0,\\n        *,\\n        cancel_channel_enabled: bool = True,\\n    ) -> None:\\n        super().__init__()\\n        self._redis_host = host\\n        self._redis_port = port\\n        self._redis_db = db\\n        self._redis_url = url\\n        self._ttl = ttl\\n        self._startup_grace_s = startup_grace_s\\n        self._cancel_channel_enabled = cancel_channel_enabled\\n        self._cancel_marker_ttl = cancel_marker_ttl\\n        self._polling_stale_threshold_s = polling_stale_threshold_s\\n        self._polling_watchdog_interval_s = polling_watchdog_interval_s\\n        self._client: Any = None\\n        self._connection_check_task: asyncio.Task | None = None\\n        self._bridge_tasks: dict[str, asyncio.Task] = {}\\n        self._consumer_wrappers: dict[str, RedisQueueWrapper] = {}\\n        self._owner_refresh_tasks: dict[str, asyncio.Task] = {}\\n        # Single PSUBSCRIBE task per worker \u2014 handles every job's cancel channel.\\n        # Replaces the previous per-job subscriber so connection-pool usage is O(1)\\n        # in active job count.\\n        self._cancel_dispatcher_task: asyncio.Task | None = None\\n        # Periodic loop that publishes cancel for owned jobs whose activity\\n        # heartbeat has gone stale (client abandoned a polling build). Started\\n        # only when polling_stale_threshold_s > 0.\\n        self._polling_watchdog_task: asyncio.Task | None = None\\n        # Strong references for short-lived fire-and-forget tasks (marker check,\\n        # post-cancel cleanup). Each task removes itself on completion. Without\\n        # this, asyncio is free to GC the task while it's still scheduled.\\n        self._background_tasks: set[asyncio.Task] = set()\\n        # Counters used for observability \u2014 bumped on each cancel event.\\n        self._cancel_stats: dict[str, int] = {\\n            \\\"published\\\": 0,\\n            \\\"marker_hit\\\": 0,\\n            \\\"dispatched_owned\\\": 0,\\n            \\\"dispatched_foreign\\\": 0,\\n            \\\"publish_errors\\\": 0,\\n            \\\"dispatcher_reconnects\\\": 0,\\n            \\\"dispatcher_internal_errors\\\": 0,\\n            \\\"polling_watchdog_kills\\\": 0,\\n            \\\"activity_touch_errors\\\": 0,\\n            \\\"activity_get_errors\\\": 0,\\n            \\\"activity_parse_errors\\\": 0,\\n        }\\n        # Monotonic timestamp of when each owned job entered start_job. Used\\n        # by the polling watchdog to grant a brand-new job a grace window\\n        # before reclaiming it if the activity key hasn't been written yet.\\n        self._job_start_times: dict[str, float] = {}\\n\\n    @property\\n    def cross_worker_cancel_enabled(self) -> bool:\\n        \\\"\\\"\\\"Reflects ``cancel_channel_enabled`` for the Redis backend.\\n\\n        When False, ``signal_cancel`` short-circuits to a 0 return without\\n        setting the marker, so cross-worker delivery is genuinely unavailable.\\n        \\\"\\\"\\\"\\n        return self._cancel_channel_enabled\\n\\n    def _bump_cancel_stat(self, key: str, value: int = 1) -> None:\\n        \\\"\\\"\\\"Increment a cancel_stat counter and emit the matching OTel counter event.\\n\\n        Single point of mutation for ``self._cancel_stats`` so ``/monitor/job_queue``\\n        and Prometheus stay in lockstep. The OTel emit is best-effort and never\\n        raises (see :meth:`_emit_otel_counter` on the base class).\\n        \\\"\\\"\\\"\\n        self._cancel_stats[key] += value\\n        self._emit_otel_counter(\\\"langflow_job_queue_cancel_events_total\\\", {\\\"event_type\\\": key}, float(value))\\n\\n    def _stream_key(self, job_id: str) -> str:\\n        return f\\\"{self.STREAM_PREFIX}{job_id}\\\"\\n\\n    def _owner_key(self, job_id: str) -> str:\\n        return f\\\"{self.OWNER_PREFIX}{job_id}\\\"\\n\\n    def _public_job_key(self, job_id: str) -> str:\\n        return f\\\"{self.PUBLIC_JOB_PREFIX}{job_id}\\\"\\n\\n    def _cancel_channel(self, job_id: str) -> str:\\n        return f\\\"{self.CANCEL_CHANNEL_PREFIX}{job_id}\\\"\\n\\n    def _spawn_background(self, coro) -> asyncio.Task:\\n        \\\"\\\"\\\"Schedule a fire-and-forget task with a strong reference until completion.\\n\\n        Without holding a strong reference, asyncio is free to garbage-collect a\\n        scheduled task before it runs. Each task removes itself on completion.\\n        \\\"\\\"\\\"\\n        task = asyncio.create_task(coro)\\n        self._background_tasks.add(task)\\n        task.add_done_callback(self._background_tasks.discard)\\n        return task\\n\\n    def _make_client(self):\\n        \\\"\\\"\\\"Build a Redis client from the configured settings.\\\"\\\"\\\"\\n        from redis.asyncio import StrictRedis\\n\\n        if self._redis_url:\\n            return StrictRedis.from_url(self._redis_url)\\n        return StrictRedis(host=self._redis_host, port=self._redis_port, db=self._redis_db)\\n\\n    def start(self) -> None:\\n        \\\"\\\"\\\"Create the Redis client, start the periodic cleanup, and run one cancel dispatcher.\\\"\\\"\\\"\\n        self._client = self._make_client()\\n        super().start()\\n        # Schedule a connectivity check so startup logs a clear error if Redis is unreachable.\\n        self._connection_check_task = asyncio.create_task(self._check_connection())\\n        # One PSUBSCRIBE per worker handles every job's cancel channel \u2014 bounded\\n        # connection-pool usage regardless of how many jobs are active.\\n        if self._cancel_channel_enabled:\\n            self._cancel_dispatcher_task = asyncio.create_task(self._run_cancel_dispatcher())\\n        # Polling watchdog: reclaim owned jobs whose activity heartbeat has gone\\n        # stale (client abandoned a polling build). Runs independently of the\\n        # pub/sub cancel channel \u2014 it uses only local state and _handle_cancel\\n        # directly, so disabling cancel_channel_enabled must not silence it.\\n        # Disabled entirely when threshold <= 0.\\n        if self._polling_stale_threshold_s > 0:\\n            self._polling_watchdog_task = asyncio.create_task(self._run_polling_watchdog())\\n        logger.debug(\\\"RedisJobQueueService started.\\\")\\n\\n    # Startup connectivity probe tunables (overridable in tests). A short retry\\n    # window tolerates Redis that comes up a beat after Langflow, e.g. a\\n    # docker-compose service without a healthcheck-gated dependency.\\n    _STARTUP_PROBE_ATTEMPTS = 5\\n    _STARTUP_PROBE_BACKOFF_S = 1.0\\n\\n    @property\\n    def connection_target(self) -> str:\\n        \\\"\\\"\\\"Human-readable description of the configured Redis endpoint for error messages.\\n\\n        Credentials embedded in the URL are redacted \u2014 this string ends up in\\n        server logs and in HTTP 503 details returned to API clients.\\n        \\\"\\\"\\\"\\n        if self._redis_url:\\n            return _redact_url_credentials(self._redis_url)\\n        return f\\\"{self._redis_host}:{self._redis_port} db={self._redis_db}\\\"\\n\\n    def _backend_unavailable_message(self) -> str:\\n        \\\"\\\"\\\"Actionable message for JobQueueBackendUnavailableError.\\\"\\\"\\\"\\n        return (\\n            f\\\"Job queue backend (Redis) is unavailable at {self.connection_target}. \\\"\\n            \\\"Start Redis, fix the LANGFLOW_REDIS_QUEUE_* settings, or set \\\"\\n            \\\"LANGFLOW_JOB_QUEUE_TYPE=asyncio.\\\"\\n        )\\n\\n    async def is_connected(self, *, attempts: int | None = None, backoff_s: float | None = None) -> bool:\\n        \\\"\\\"\\\"Ping Redis with bounded retry; return True if reachable, False otherwise.\\n\\n        Used at startup to fail fast when ``LANGFLOW_JOB_QUEUE_TYPE=redis`` but the\\n        Redis server is not reachable, instead of booting \\\"fine\\\" and then emitting\\n        confusing connection errors on the first flow execution.\\n\\n        The startup probe runs from ``initialize_services()``, before the per-worker\\n        ``start()`` creates ``self._client``, so a temporary client is used (and\\n        closed) when the service has not started yet. It is not retained: ``start()``\\n        runs on the worker's event loop, which may differ from the probe's.\\n        \\\"\\\"\\\"\\n        attempts = self._STARTUP_PROBE_ATTEMPTS if attempts is None else attempts\\n        backoff_s = self._STARTUP_PROBE_BACKOFF_S if backoff_s is None else backoff_s\\n        temp_client = None\\n        client = self._client\\n        if client is None:\\n            client = temp_client = self._make_client()\\n        try:\\n            for attempt in range(1, attempts + 1):\\n                try:\\n                    await client.ping()\\n                except Exception as exc:  # noqa: BLE001\\n                    if attempt < attempts:\\n                        await logger.adebug(\\n                            f\\\"RedisJobQueueService: Redis not reachable at {self.connection_target} \\\"\\n                            f\\\"(attempt {attempt}/{attempts}): {exc}. Retrying in {backoff_s}s.\\\"\\n                        )\\n                        await asyncio.sleep(backoff_s)\\n                        continue\\n                    return False\\n                else:\\n                    return True\\n            return False\\n        finally:\\n            if temp_client is not None:\\n                with contextlib.suppress(Exception):\\n                    await temp_client.aclose()\\n\\n    async def _check_connection(self) -> None:\\n        \\\"\\\"\\\"Ping Redis and log a prominent error if the connection is unavailable.\\\"\\\"\\\"\\n        try:\\n            await self._client.ping()\\n            await logger.adebug(\\\"RedisJobQueueService: Redis connection OK.\\\")\\n        except Exception as exc:  # noqa: BLE001\\n            await logger.aerror(\\n                f\\\"RedisJobQueueService: cannot reach Redis at {self.connection_target} \u2014 {exc}. \\\"\\n                \\\"Build events will NOT be delivered. \\\"\\n                \\\"Set LANGFLOW_JOB_QUEUE_TYPE=asyncio or start Redis before running Langflow.\\\"\\n            )\\n\\n    async def stop(self) -> None:\\n        \\\"\\\"\\\"Stop the service, cancel all background tasks, and close the Redis client.\\\"\\\"\\\"\\n        if self._connection_check_task and not self._connection_check_task.done():\\n            self._connection_check_task.cancel()\\n            with contextlib.suppress(asyncio.CancelledError):\\n                await self._connection_check_task\\n        self._connection_check_task = None\\n\\n        if self._cancel_dispatcher_task and not self._cancel_dispatcher_task.done():\\n            self._cancel_dispatcher_task.cancel()\\n            with contextlib.suppress(asyncio.CancelledError):\\n                await self._cancel_dispatcher_task\\n        self._cancel_dispatcher_task = None\\n\\n        if self._polling_watchdog_task and not self._polling_watchdog_task.done():\\n            self._polling_watchdog_task.cancel()\\n            with contextlib.suppress(asyncio.CancelledError):\\n                await self._polling_watchdog_task\\n        self._polling_watchdog_task = None\\n\\n        # Wait briefly for any fire-and-forget background tasks (marker checks,\\n        # post-cancel cleanups) so they don't leak across stop boundaries.\\n        for refresh_task in list(self._owner_refresh_tasks.values()):\\n            if not refresh_task.done():\\n                refresh_task.cancel()\\n                with contextlib.suppress(asyncio.CancelledError):\\n                    await refresh_task\\n        self._owner_refresh_tasks.clear()\\n\\n        for bg in list(self._background_tasks):\\n            if not bg.done():\\n                bg.cancel()\\n                with contextlib.suppress(asyncio.CancelledError, Exception):\\n                    await bg\\n        self._background_tasks.clear()\\n\\n        for bridge in list(self._bridge_tasks.values()):\\n            if not bridge.done():\\n                bridge.cancel()\\n                with contextlib.suppress(asyncio.CancelledError):\\n                    await bridge\\n        self._bridge_tasks.clear()\\n        for wrapper in list(self._consumer_wrappers.values()):\\n            await wrapper.cancel()\\n        self._consumer_wrappers.clear()\\n        await super().stop()\\n        if self._client:\\n            await self._client.aclose()\\n            self._client = None\\n        await logger.adebug(\\\"RedisJobQueueService stopped.\\\")\\n\\n    def create_queue(self, job_id: str) -> tuple[asyncio.Queue, EventManager]:\\n        \\\"\\\"\\\"Create a local queue + EventManager and start the producer bridge to Redis.\\\"\\\"\\\"\\n        local_queue, event_manager = super().create_queue(job_id)\\n        bridge = asyncio.create_task(self._bridge_to_redis(job_id, local_queue))\\n        self._bridge_tasks[job_id] = bridge\\n        return local_queue, event_manager\\n\\n    # Refresh the stream TTL on the first event, then every _TTL_REFRESH_EVENTS\\n    # events *or* every _TTL_REFRESH_SECS seconds, whichever comes first.\\n    # Calling expire() on every XADD doubles Redis round-trips and caps\\n    # single-job throughput; periodic refresh preserves semantics at ~1/100 the cost.\\n    _TTL_REFRESH_EVENTS = 100\\n    _TTL_REFRESH_SECS = 30.0\\n\\n    async def _bridge_to_redis(self, job_id: str, local_queue: asyncio.Queue) -> None:\\n        \\\"\\\"\\\"Drain the local queue and publish each event to the Redis Stream.\\n\\n        Items are read from the local asyncio.Queue (written by EventManager) and\\n        forwarded to a Redis Stream via XADD so that any worker can consume them.\\n        If Redis is temporarily unavailable the item is re-queued and the bridge\\n        backs off before retrying, preventing event loss.\\n        \\\"\\\"\\\"\\n        stream_key = self._stream_key(job_id)\\n        _max_retry_delay = 4.0\\n        _retry_delay = 0.1\\n        in_flight_item = None\\n        published = False\\n        event_count = 0\\n        last_ttl_refresh = time.monotonic()\\n        try:\\n            while True:\\n                item = await local_queue.get()\\n                in_flight_item = item\\n                published = False\\n                event_id, data, ts = item\\n                is_sentinel = data is None\\n                fields = (\\n                    {\\\"event_id\\\": \\\"__sentinel__\\\", \\\"data\\\": _STREAM_SENTINEL_DATA, \\\"ts\\\": str(ts)}\\n                    if is_sentinel\\n                    else {\\\"event_id\\\": event_id or \\\"\\\", \\\"data\\\": data, \\\"ts\\\": str(ts)}\\n                )\\n                # Refresh TTL on first event, every N events, every M seconds, or on sentinel.\\n                now = time.monotonic()\\n                needs_ttl_refresh = (\\n                    event_count == 0\\n                    or event_count % self._TTL_REFRESH_EVENTS == 0\\n                    or (now - last_ttl_refresh) >= self._TTL_REFRESH_SECS\\n                    or is_sentinel\\n                )\\n                while True:\\n                    try:\\n                        if not published:\\n                            await self._client.xadd(stream_key, fields, maxlen=10_000, approximate=True)\\n                            published = True\\n                        if needs_ttl_refresh:\\n                            await self._client.expire(stream_key, self._ttl)\\n                            # Why: register_public_job sets the public_job marker with\\n                            # ex=self._ttl once at job start. Long-running builds that\\n                            # outlive that TTL would have the marker expire while the\\n                            # stream itself is kept alive, causing is_public_job_async\\n                            # to 404 a still-active public job on other workers. Refresh\\n                            # it on the same cadence as the stream TTL. is_public_job is\\n                            # the in-memory (sync) check \u2014 true on the worker that owns\\n                            # this bridge, which is the same worker that registered it.\\n                            if self.is_public_job(job_id):\\n                                await self._client.expire(self._public_job_key(job_id), self._ttl)\\n                            last_ttl_refresh = time.monotonic()\\n                        in_flight_item = None\\n                        _retry_delay = 0.1\\n                        break\\n                    except asyncio.CancelledError:\\n                        raise\\n                    except Exception as exc:  # noqa: BLE001\\n                        await logger.awarning(\\n                            f\\\"Bridge XADD failed for job_id {job_id} (retrying in {_retry_delay}s): {exc}\\\"\\n                        )\\n                        await asyncio.sleep(_retry_delay)\\n                        _retry_delay = min(_retry_delay * 2, _max_retry_delay)\\n                event_count += 1\\n                if is_sentinel:\\n                    return\\n        except asyncio.CancelledError:\\n            if in_flight_item is not None and not published:\\n                local_queue.put_nowait(in_flight_item)\\n            return\\n\\n    def _get_consumer_wrapper(self, job_id: str) -> RedisQueueWrapper:\\n        \\\"\\\"\\\"Return the cached Redis stream consumer for a job, creating it if needed.\\\"\\\"\\\"\\n        wrapper = self._consumer_wrappers.get(job_id)\\n        if wrapper is None:\\n            wrapper = RedisQueueWrapper(\\n                job_id,\\n                self._client,\\n                self._ttl,\\n                startup_grace_s=self._startup_grace_s,\\n            )\\n            self._consumer_wrappers[job_id] = wrapper\\n        return wrapper\\n\\n    # Persistent marker that :meth:`signal_cancel` sets in addition to publishing.\\n    # Closes the race where a cancel signal is sent before the worker's dispatcher\\n    # finishes PSUBSCRIBE (or before this worker has even started the job). On\\n    # ``start_job`` the worker checks the marker; if present, fires cancel immediately.\\n    _CANCEL_MARKER_PREFIX = \\\"langflow:cancel-marker:\\\"\\n\\n    def _cancel_marker_key(self, job_id: str) -> str:\\n        return f\\\"{self._CANCEL_MARKER_PREFIX}{job_id}\\\"\\n\\n    def start_job(self, job_id: str, task_coro) -> None:  # type: ignore[override]\\n        \\\"\\\"\\\"Start the build task, then check for any pre-arrived cancel marker.\\\"\\\"\\\"\\n        # Record start time BEFORE super().start_job() so the watchdog never\\n        # sees the job in self._queues without a corresponding start timestamp.\\n        self._job_start_times[job_id] = time.monotonic()\\n        super().start_job(job_id, task_coro)\\n        if job_id in self._job_owners:\\n            self._ensure_owner_refresh_task(job_id)\\n        if not self._cancel_channel_enabled or self._client is None:\\n            return\\n        # Initialize the activity heartbeat so the watchdog gives clients the\\n        # configured threshold to make first contact before reclaiming the job.\\n        self._spawn_background(self.touch_activity(job_id))\\n        # Cancel may have been signaled before we registered this job_id. Check\\n        # the persistent marker in a background task to avoid making start_job async.\\n        self._spawn_background(self._check_pending_cancel_marker(job_id))\\n\\n    def _activity_key(self, job_id: str) -> str:\\n        return f\\\"{self.ACTIVITY_PREFIX}{job_id}\\\"\\n\\n    async def touch_activity(self, job_id: str) -> None:\\n        \\\"\\\"\\\"Refresh the activity heartbeat for *job_id*.\\n\\n        Called by polling and streaming responses to signal \\\"client still here\\\".\\n        The polling watchdog scans these keys to detect abandoned builds.\\n\\n        TTL is set to 4x the stale threshold (min 60s) so the activity key\\n        outlives a single dropped touch without the watchdog misclassifying\\n        the job as abandoned \u2014 Redis keeps the value around long enough for\\n        the next successful refresh to land. Errors here are non-fatal but\\n        observable via :attr:`_cancel_stats` (``activity_touch_errors``);\\n        sustained heartbeat failure combined with the start-time grace window\\n        in :meth:`_run_polling_watchdog` keeps an in-flight build alive even\\n        through a brief Redis outage.\\n        \\\"\\\"\\\"\\n        if self._client is None or self._polling_stale_threshold_s <= 0:\\n            return\\n        ttl = max(int(self._polling_stale_threshold_s * 4), 60)\\n        try:\\n            await self._client.set(self._activity_key(job_id), str(time.time()), ex=ttl)\\n        except asyncio.CancelledError:\\n            raise\\n        except Exception as exc:  # noqa: BLE001\\n            self._bump_cancel_stat(\\\"activity_touch_errors\\\")\\n            await logger.adebug(f\\\"touch_activity SET failed for {job_id}: {exc}\\\")\\n\\n    def _owner_refresh_interval_s(self) -> float:\\n        \\\"\\\"\\\"Return the owner-key refresh cadence for active Redis jobs.\\\"\\\"\\\"\\n        return max(min(self._ttl / 2, 30.0), 0.1)\\n\\n    async def _set_owner_key(self, job_id: str, user_id: UUID) -> None:\\n        if self._client:\\n            await self._client.set(self._owner_key(job_id), str(user_id), ex=self._ttl)\\n\\n    def _ensure_owner_refresh_task(self, job_id: str) -> None:\\n        task = self._owner_refresh_tasks.get(job_id)\\n        if task is None or task.done():\\n            self._owner_refresh_tasks[job_id] = asyncio.create_task(self._refresh_owner_key_until_done(job_id))\\n\\n    async def _refresh_owner_key_until_done(self, job_id: str) -> None:\\n        \\\"\\\"\\\"Keep the Redis owner key alive while this worker still owns the job.\\\"\\\"\\\"\\n        current_task = asyncio.current_task()\\n        try:\\n            while not self._closed and job_id in self._queues:\\n                user_id = self._job_owners.get(job_id)\\n                if user_id is not None and self._client is not None:\\n                    try:\\n                        await self._set_owner_key(job_id, user_id)\\n                    except asyncio.CancelledError:\\n                        raise\\n                    except Exception as exc:  # noqa: BLE001\\n                        await logger.adebug(f\\\"owner key refresh failed for {job_id}: {exc}\\\")\\n                await asyncio.sleep(self._owner_refresh_interval_s())\\n        finally:\\n            if self._owner_refresh_tasks.get(job_id) is current_task:\\n                self._owner_refresh_tasks.pop(job_id, None)\\n\\n    async def _check_pending_cancel_marker(self, job_id: str) -> None:\\n        \\\"\\\"\\\"Race-safety check: if a cancel marker exists, fire it immediately.\\\"\\\"\\\"\\n        marker_key = self._cancel_marker_key(job_id)\\n        try:\\n            if await self._client.exists(marker_key):\\n                await self._client.delete(marker_key)\\n                self._bump_cancel_stat(\\\"marker_hit\\\")\\n                await self._handle_cancel(job_id, source=\\\"marker\\\")\\n        except Exception as exc:  # noqa: BLE001\\n            await logger.awarning(f\\\"Pending cancel marker check failed for {job_id}: {exc}\\\")\\n\\n    async def _run_polling_watchdog(self) -> None:\\n        \\\"\\\"\\\"Periodically reclaim owned jobs whose activity heartbeat has gone stale.\\n\\n        Each tick scans :attr:`_queues` (jobs this worker owns), filters to\\n        jobs that have a registered owner (i.e. user-facing flow builds that\\n        expect client polling/streaming), and pulls their activity timestamp\\n        from Redis. Missing-or-older-than :attr:`_polling_stale_threshold_s`\\n        means the client gave up.\\n\\n        **Why the owner filter:** The :class:`TaskService` also uses\\n        :meth:`start_job` for server-internal tasks that have no polling client\\n        and never call :meth:`touch_activity`. Without the filter, every such\\n        task would trip the start-time fallback at the threshold and get\\n        cancelled mid-flight if it ran longer than the threshold \u2014 even though\\n        no client was ever waiting on it. Registered ownership is the\\n        existing signal for \\\"user-facing build with an expected client\\\", so\\n        scope the watchdog to that set.\\n\\n        Brand-new jobs are protected by a start-time grace window: if the\\n        activity key is missing (e.g. the background ``touch_activity`` from\\n        ``start_job`` hasn't completed yet, or Redis was briefly unreachable),\\n        the watchdog skips the kill until ``time - job_start >= threshold``.\\n        Without this, a slow first SET could nuke an active build the moment\\n        its first watchdog tick fires.\\n\\n        Cancellation goes through :meth:`_handle_cancel` directly rather than\\n        ``signal_cancel`` for owned jobs \u2014 there is no need to round-trip\\n        through pubsub when this worker already holds the cancel target, and\\n        bypassing the wire path keeps the ``cancel_stats[\\\"published\\\"]``\\n        counter honest as a count of *external* cancels only.\\n        \\\"\\\"\\\"\\n        interval = max(self._polling_watchdog_interval_s, 0.05)\\n        threshold = self._polling_stale_threshold_s\\n        while True:\\n            try:\\n                await asyncio.sleep(interval)\\n            except asyncio.CancelledError:\\n                return\\n            if self._closed or self._client is None:\\n                continue\\n            now = time.time()\\n            now_mono = time.monotonic()\\n            # Iterate a snapshot so concurrent inserts don't disturb the scan.\\n            for job_id in list(self._queues.keys()):\\n                # Only watch jobs with a registered owner \u2014 TaskService and\\n                # other server-internal callers use start_job without\\n                # registering ownership, and they never refresh activity\\n                # heartbeats. See the docstring for rationale.\\n                if job_id not in self._job_owners:\\n                    continue\\n                try:\\n                    raw = await self._client.get(self._activity_key(job_id))\\n                except Exception as exc:  # noqa: BLE001\\n                    self._bump_cancel_stat(\\\"activity_get_errors\\\")\\n                    await logger.adebug(f\\\"polling watchdog: GET failed for {job_id}: {exc}\\\")\\n                    continue\\n                # Default to \\\"infinitely stale\\\" so a missed elif below cannot\\n                # leave `last` unbound; the if-branches narrow this down.\\n                last = 0.0\\n                if raw is None:\\n                    # Activity key not in Redis. Could be a brand-new job whose\\n                    # background touch hasn't landed yet, or a touch_activity\\n                    # failure (counter bumped elsewhere). Respect the start-time\\n                    # grace window before reclaiming.\\n                    start_ts = self._job_start_times.get(job_id)\\n                    if start_ts is None or (now_mono - start_ts) < threshold:\\n                        continue\\n                else:\\n                    try:\\n                        last = float(raw.decode() if isinstance(raw, bytes) else raw)\\n                    except (ValueError, TypeError) as exc:\\n                        self._bump_cancel_stat(\\\"activity_parse_errors\\\")\\n                        await logger.awarning(\\n                            f\\\"polling watchdog: ignoring malformed activity value for {job_id}: {exc}\\\"\\n                        )\\n                        continue\\n                age = now - last if last > 0 else float(\\\"inf\\\")\\n                if age <= threshold:\\n                    continue\\n                # Stale \u2192 cancel this job. Local cancel on owned jobs skips the\\n                # pubsub round-trip and stays correct even during a dispatcher\\n                # reconnect window.\\n                self._bump_cancel_stat(\\\"polling_watchdog_kills\\\")\\n                await logger.ainfo(f\\\"polling watchdog: reclaiming abandoned job {job_id} (age={age:.1f}s)\\\")\\n                await self._handle_cancel(job_id, source=\\\"watchdog\\\")\\n                with contextlib.suppress(Exception):\\n                    await self._client.delete(self._activity_key(job_id))\\n\\n    # Reconnect tunables \u2014 class-level so tests can override without patching the loop.\\n    _DISPATCHER_RECONNECT_INITIAL_BACKOFF_S = 0.5\\n    _DISPATCHER_RECONNECT_MAX_BACKOFF_S = 30.0\\n\\n    async def _run_cancel_dispatcher(self) -> None:\\n        \\\"\\\"\\\"PSUBSCRIBE loop with auto-reconnect.\\n\\n        The dispatcher is the single point of cross-worker cancel delivery for\\n        this worker. If the pubsub connection dies (Redis restart, network\\n        blip, broker timeout), we MUST reconnect \u2014 otherwise the worker becomes\\n        silently blind to cancels until restart.\\n\\n        Strategy:\\n        * Each iteration of the outer loop opens a fresh pubsub.\\n        * On successful PSUBSCRIBE the backoff resets.\\n        * Any non-cancel exception is logged at warning, backoff doubles up to\\n          ``_DISPATCHER_RECONNECT_MAX_BACKOFF_S``, and we retry.\\n        * redis-py may also reconnect the active pubsub connection internally;\\n          the connection callback below records those transparent reconnects.\\n        * ``asyncio.CancelledError`` (service stop) breaks out cleanly.\\n        \\\"\\\"\\\"\\n        pattern = f\\\"{self.CANCEL_CHANNEL_PREFIX}*\\\"\\n        backoff = self._DISPATCHER_RECONNECT_INITIAL_BACKOFF_S\\n        while True:\\n            pubsub = self._client.pubsub()\\n            try:\\n                await pubsub.psubscribe(pattern)\\n                self._register_cancel_dispatcher_reconnect_callback(pubsub)\\n                backoff = self._DISPATCHER_RECONNECT_INITIAL_BACKOFF_S\\n                await logger.adebug(f\\\"RedisJobQueueService: cancel dispatcher subscribed to {pattern}\\\")\\n                async for message in pubsub.listen():\\n                    if message.get(\\\"type\\\") != \\\"pmessage\\\":\\n                        continue\\n                    channel = message.get(\\\"channel\\\")\\n                    if channel is None:\\n                        continue\\n                    channel_str = channel.decode() if isinstance(channel, bytes) else channel\\n                    if not channel_str.startswith(self.CANCEL_CHANNEL_PREFIX):\\n                        continue\\n                    job_id = channel_str[len(self.CANCEL_CHANNEL_PREFIX) :]\\n                    await self._handle_cancel(job_id, source=\\\"pubsub\\\")\\n                # listen() returned cleanly \u2014 treat as a soft disconnect and reconnect.\\n                self._bump_cancel_stat(\\\"dispatcher_reconnects\\\")\\n                await logger.awarning(f\\\"Cancel dispatcher pubsub.listen() ended; reconnecting in {backoff:.1f}s\\\")\\n            except asyncio.CancelledError:\\n                with contextlib.suppress(Exception):\\n                    await pubsub.punsubscribe(pattern)\\n                await self._close_pubsub(pubsub)\\n                return\\n            except (ConnectionError, TimeoutError, OSError) as exc:\\n                # Expected transient failure: Redis dropped the pubsub, network\\n                # blip, broker restart. Reconnect quietly via the backoff loop.\\n                self._bump_cancel_stat(\\\"dispatcher_reconnects\\\")\\n                await logger.awarning(f\\\"Cancel dispatcher disconnect (retrying in {backoff:.1f}s): {exc!r}\\\")\\n            except Exception as exc:  # noqa: BLE001\\n                # Unexpected exception \u2014 likely a bug in dispatch logic, NOT a\\n                # Redis problem. Surface at error level with traceback so it\\n                # reaches Sentry / log aggregation, then still reconnect so a\\n                # one-off bug doesn't kill cross-worker cancel permanently.\\n                self._bump_cancel_stat(\\\"dispatcher_reconnects\\\")\\n                self._bump_cancel_stat(\\\"dispatcher_internal_errors\\\")\\n                await logger.aerror(\\n                    f\\\"Cancel dispatcher internal error (retrying in {backoff:.1f}s): {exc!r}\\\",\\n                    exc_info=True,\\n                )\\n            # Clean up the dead pubsub before sleeping + retrying.\\n            with contextlib.suppress(Exception):\\n                await pubsub.punsubscribe(pattern)\\n            await self._close_pubsub(pubsub)\\n            try:\\n                await asyncio.sleep(backoff)\\n            except asyncio.CancelledError:\\n                return\\n            backoff = min(backoff * 2, self._DISPATCHER_RECONNECT_MAX_BACKOFF_S)\\n\\n    async def _on_cancel_dispatcher_connection_reconnect(self, _connection: Any) -> None:\\n        \\\"\\\"\\\"Record redis-py reconnects that happen inside an active PubSub.\\\"\\\"\\\"\\n        self._bump_cancel_stat(\\\"dispatcher_reconnects\\\")\\n        with contextlib.suppress(Exception):\\n            await logger.awarning(\\\"Cancel dispatcher pubsub connection reconnected transparently\\\")\\n\\n    def _register_cancel_dispatcher_reconnect_callback(self, pubsub: Any) -> None:\\n        connection = getattr(pubsub, \\\"connection\\\", None)\\n        register = getattr(connection, \\\"register_connect_callback\\\", None)\\n        if register is not None:\\n            with contextlib.suppress(Exception):\\n                register(self._on_cancel_dispatcher_connection_reconnect)\\n\\n    async def _close_pubsub(self, pubsub: Any) -> None:\\n        \\\"\\\"\\\"Close a pubsub object regardless of redis-py version.\\n\\n        Newer redis-py (>=5) exposes ``aclose``; older releases used ``close``.\\n        \\\"\\\"\\\"\\n        connection = getattr(pubsub, \\\"connection\\\", None)\\n        deregister = getattr(connection, \\\"deregister_connect_callback\\\", None)\\n        if deregister is not None:\\n            with contextlib.suppress(Exception):\\n                deregister(self._on_cancel_dispatcher_connection_reconnect)\\n        close = getattr(pubsub, \\\"aclose\\\", None) or getattr(pubsub, \\\"close\\\", None)\\n        if close is None:\\n            return\\n        with contextlib.suppress(Exception):\\n            result = close()\\n            if asyncio.iscoroutine(result):\\n                await result\\n\\n    async def _apply_cancel(self, job_id: str, *, source: str, wait_for_cleanup: bool) -> None:\\n        \\\"\\\"\\\"Apply a cancel signal for *job_id* if this worker owns the job.\\n\\n        Cancels the local task, flushes a sentinel through the bridge so cross-worker\\n        consumers see end-of-stream promptly, and triggers fast cleanup of the\\n        Redis stream + owner keys. No-op if this worker doesn't own the job\\n        (the owning worker's dispatcher will receive the same publish for\\n        pub/sub cancels).\\n        \\\"\\\"\\\"\\n        entry = self._queues.get(job_id)\\n        if entry is None:\\n            self._bump_cancel_stat(\\\"dispatched_foreign\\\")\\n            await logger.adebug(f\\\"Cancel for {job_id} ignored on this worker (not owner); source={source}\\\")\\n            return\\n        self._bump_cancel_stat(\\\"dispatched_owned\\\")\\n        await logger.ainfo(f\\\"Cancel applied to {job_id} (source={source})\\\")\\n        main_queue, _, task, _ = entry\\n        if task is not None and not task.done():\\n            task.cancel()\\n        # Flush a sentinel so the bridge publishes the Redis end-of-stream marker\\n        # before cleanup deletes the stream key.\\n        with contextlib.suppress(Exception):\\n            main_queue.put_nowait((None, None, time.time()))\\n        # Trigger fast cleanup; runs as a fire-and-forget task that swallows the\\n        # expected CancelledError re-raised by super().cleanup_job.\\n        cleanup_task = self._spawn_background(self._post_cancel_cleanup(job_id))\\n        if wait_for_cleanup:\\n            # Keep cleanup alive even if the HTTP request is cancelled while the\\n            # endpoint is waiting for confirmation.\\n            await asyncio.shield(cleanup_task)\\n\\n    async def _handle_cancel(self, job_id: str, *, source: str) -> None:\\n        \\\"\\\"\\\"Apply a received pub/sub or marker cancel signal for *job_id*.\\\"\\\"\\\"\\n        await self._apply_cancel(job_id, source=source, wait_for_cleanup=False)\\n\\n    # Max time _post_cancel_cleanup waits on cleanup_job before giving up.\\n    # Bounds the lifetime of the background task even under Redis pathology\\n    # (e.g. a hung DELETE). Periodic cleanup will still reap stale state later.\\n    _POST_CANCEL_CLEANUP_TIMEOUT_S = 10.0\\n\\n    async def _post_cancel_cleanup(self, job_id: str) -> None:\\n        \\\"\\\"\\\"Fire-and-forget cleanup wrapper that runs after the bridge has flushed.\\n\\n        Waits for the bridge task to drain the sentinel we just put on the local\\n        queue and publish the Redis end-of-stream marker before cancelling it via\\n        :meth:`cleanup_job`. Without this wait, a fast cleanup races the bridge\\n        and may cancel it before XADD completes, leaving cross-worker consumers\\n        without the sentinel record in the stream.\\n\\n        The outer :data:`_POST_CANCEL_CLEANUP_TIMEOUT_S` bounds total runtime so\\n        a stuck cleanup_job (e.g. Redis stalls during stream DELETE) does not\\n        leak this background task forever; periodic cleanup will reap whatever\\n        state remains on its next pass.\\n        \\\"\\\"\\\"\\n        bridge = self._bridge_tasks.get(job_id)\\n        if bridge is not None and not bridge.done():\\n            # ``shield`` keeps the bridge alive even if our task is cancelled\\n            # during the wait; the inner timeout caps the worst case if XADD\\n            # is stuck (cross-worker consumers can still recover via the\\n            # missing-stream-key sentinel path). Narrow the except to the\\n            # timeout case only so real bridge failures bubble up.\\n            try:\\n                await asyncio.wait_for(asyncio.shield(bridge), timeout=2.0)\\n            except asyncio.TimeoutError:\\n                await logger.awarning(\\n                    f\\\"Post-cancel cleanup: bridge sentinel flush timed out for {job_id}; \\\"\\n                    \\\"cross-worker consumers may see late end-of-stream.\\\"\\n                )\\n            except asyncio.CancelledError:\\n                raise\\n            except Exception as exc:  # noqa: BLE001\\n                await logger.awarning(f\\\"Post-cancel cleanup: bridge wait failed for {job_id}: {exc!r}\\\")\\n        try:\\n            await asyncio.wait_for(\\n                self.cleanup_job(job_id),\\n                timeout=self._POST_CANCEL_CLEANUP_TIMEOUT_S,\\n            )\\n        except asyncio.CancelledError:\\n            # Expected: super().cleanup_job re-raises after a user-initiated cancel.\\n            pass\\n        except asyncio.TimeoutError:\\n            await logger.awarning(\\n                f\\\"Post-cancel cleanup timed out for {job_id} after \\\"\\n                f\\\"{self._POST_CANCEL_CLEANUP_TIMEOUT_S:.1f}s; periodic cleanup will retry.\\\"\\n            )\\n        except Exception as exc:  # noqa: BLE001\\n            await logger.awarning(f\\\"Post-cancel cleanup error for {job_id}: {exc}\\\")\\n\\n    async def cancel_job(self, job_id: str) -> None:\\n        \\\"\\\"\\\"Cancel an owned Redis job after publishing an end-of-stream sentinel.\\n\\n        ``cleanup_job`` alone cancels the bridge before the cancelled build task\\n        can publish a terminal stream record. Route explicit same-worker cancels\\n        through the same sentinel-flush path used by cross-worker pub/sub cancels\\n        so any Redis-backed consumer terminates promptly.\\n        \\\"\\\"\\\"\\n        await self._apply_cancel(job_id, source=\\\"local\\\", wait_for_cleanup=True)\\n\\n    async def signal_cancel(self, job_id: str) -> int:\\n        \\\"\\\"\\\"Publish a cancel signal for *job_id* across all worker dispatchers.\\n\\n        Authorization note: this method does not perform any authorization check.\\n        Callers must verify the caller has rights to cancel the job \u2014 the HTTP\\n        cancel endpoint does this via ``_verify_job_ownership`` before calling\\n        through.\\n\\n        Returns the number of dispatchers reached by the PUBLISH. A return of 0\\n        is not necessarily a failure \u2014 the persistent marker key is also set, so\\n        a worker that picks up the job *after* this publish will still process\\n        the cancel during its start_job marker check.\\n\\n        Raises:\\n            redis exceptions if the Redis connection is unavailable. Callers\\n            that want best-effort behaviour should wrap in their own try/except.\\n        \\\"\\\"\\\"\\n        if not self._cancel_channel_enabled or self._client is None:\\n            return 0\\n        try:\\n            # Set the marker first so any worker that races the publish still sees it.\\n            await self._client.set(self._cancel_marker_key(job_id), \\\"1\\\", ex=self._cancel_marker_ttl)\\n            receivers = int(await self._client.publish(self._cancel_channel(job_id), \\\"1\\\"))\\n        except Exception:\\n            self._bump_cancel_stat(\\\"publish_errors\\\")\\n            raise\\n        self._bump_cancel_stat(\\\"published\\\")\\n        await logger.ainfo(f\\\"signal_cancel: job_id={job_id} receivers={receivers}\\\")\\n        return receivers\\n\\n    def metrics_snapshot(self) -> dict[str, Any]:  # type: ignore[override]\\n        \\\"\\\"\\\"Extend the base snapshot with Redis-backed bridge / cancel observability.\\n\\n        Fields:\\n        * ``bridge_count`` \u2014 active bridge tasks (one per locally-owned job).\\n        * ``consumer_wrapper_count`` \u2014 open cross-worker consumer wrappers.\\n        * ``background_task_count`` \u2014 fire-and-forget marker checks + cleanups.\\n        * ``cancel_dispatcher_running`` \u2014 True if the PSUBSCRIBE loop is alive.\\n        * ``cancel_stats`` \u2014 a copy of the cancel observability counters.\\n          ``dispatcher_reconnects`` counts explicit dispatcher-loop retries and\\n          redis-py transparent pubsub reconnect callbacks.\\n        \\\"\\\"\\\"\\n        base = super().metrics_snapshot()\\n        base[\\\"backend\\\"] = \\\"redis\\\"\\n        base[\\\"bridge_count\\\"] = len(self._bridge_tasks)\\n        base[\\\"consumer_wrapper_count\\\"] = len(self._consumer_wrappers)\\n        base[\\\"background_task_count\\\"] = len(self._background_tasks)\\n        base[\\\"cancel_dispatcher_running\\\"] = (\\n            self._cancel_dispatcher_task is not None and not self._cancel_dispatcher_task.done()\\n        )\\n        base[\\\"cancel_stats\\\"] = dict(self._cancel_stats)\\n        return base\\n\\n    def get_queue_data(self, job_id: str) -> tuple[asyncio.Queue, EventManager, asyncio.Task | None, float | None]:  # type: ignore[override]\\n        \\\"\\\"\\\"Return queue data for a job, always backed by a Redis Stream consumer.\\n\\n        The queue returned is always a :class:`RedisQueueWrapper` that reads from the\\n        Redis Stream, regardless of whether the job was started on this worker. This\\n        avoids the race condition that would occur if the bridge coroutine and the HTTP\\n        consumer both read from the same local ``asyncio.Queue``.\\n\\n        * **Same-worker path**: the bridge is the sole reader of the local queue; the\\n          HTTP consumer reads from Redis via the wrapper. The real ``asyncio.Task`` and\\n          ``EventManager`` are returned from the local registry so that disconnect\\n          handling and ownership checks work normally.\\n        * **Cross-worker path**: no local entry exists; a null ``EventManager`` and\\n          ``None`` task are returned. Cancellation from this worker travels via\\n          :meth:`signal_cancel` rather than a local ``task.cancel()`` \u2014 the\\n          dispatcher on the owning worker fires the cancel, and the streaming\\n          response's :func:`langflow.api.build.create_flow_response.on_disconnect`\\n          wires this up automatically for passive client disconnects.\\n        \\\"\\\"\\\"\\n        if self._closed:\\n            msg = f\\\"Queue service is closed for job_id: {job_id}\\\"\\n            raise RuntimeError(msg)\\n\\n        if job_id in self._queues:\\n            # Same-worker: keep task + event_manager from local registry; give a Redis\\n            # stream wrapper to the consumer so the bridge is the only local-queue reader.\\n            _, event_manager, task, cleanup_time = self._queues[job_id]\\n            return (  # type: ignore[return-value]\\n                self._get_consumer_wrapper(job_id),\\n                event_manager,\\n                task,\\n                cleanup_time,\\n            )\\n\\n        # Cross-worker path: create a Redis-backed consumer for the stream.\\n        # EventManager(None) is a null manager \u2014 send_event is a no-op (queue is None-guarded).\\n        return (  # type: ignore[return-value]\\n            self._get_consumer_wrapper(job_id),\\n            EventManager(None),\\n            None,\\n            None,\\n        )\\n\\n    async def _cleanup_old_queues(self) -> None:\\n        \\\"\\\"\\\"Run base queue cleanup then sweep done cross-worker consumer wrappers.\\n\\n        Cross-worker jobs are never inserted into ``self._queues``, so the base\\n        sweep never sees them. Their ``RedisQueueWrapper._fill_task`` exits on\\n        its own (sentinel or ``exists()=False``), but the dict entry in\\n        ``_consumer_wrappers`` stays forever unless we explicitly prune it here.\\n        \\\"\\\"\\\"\\n        await super()._cleanup_old_queues()\\n\\n        # Only prune wrappers that are NOT owned by this worker (i.e. absent from\\n        # self._queues). Same-worker wrappers are removed by cleanup_job(); touching\\n        # them here would race with the grace-period logic in the base class.\\n        done_cross_worker = [\\n            job_id\\n            for job_id, wrapper in self._consumer_wrappers.items()\\n            if job_id not in self._queues and wrapper.fill_done()\\n        ]\\n        for job_id in done_cross_worker:\\n            wrapper = self._consumer_wrappers.pop(job_id, None)\\n            if wrapper is not None:\\n                await logger.adebug(f\\\"Swept done cross-worker consumer wrapper for job_id {job_id}\\\")\\n\\n    async def cleanup_job(self, job_id: str) -> None:\\n        \\\"\\\"\\\"Cancel local task and bridge, then delete the Redis Stream and owner keys.\\\"\\\"\\\"\\n        # Capture ownership before super() pops the entry from self._queues so that\\n        # the Redis-key deletion below is scoped to the owning worker only. A\\n        # cross-worker poll populates _consumer_wrappers but not _queues; deleting\\n        # the stream/owner keys from that worker would corrupt an in-flight build on\\n        # the true owner.\\n        is_owner = job_id in self._queues\\n        # Drop the watchdog start-time entry alongside ownership.\\n        self._job_start_times.pop(job_id, None)\\n\\n        owner_refresh_task = self._owner_refresh_tasks.pop(job_id, None)\\n        if owner_refresh_task is not None and not owner_refresh_task.done():\\n            owner_refresh_task.cancel()\\n            with contextlib.suppress(asyncio.CancelledError):\\n                await owner_refresh_task\\n\\n        wrapper = self._consumer_wrappers.pop(job_id, None)\\n        if wrapper is not None:\\n            if is_owner:\\n                await wrapper.finish_with_sentinel()\\n            else:\\n                await wrapper.cancel()\\n\\n        bridge = self._bridge_tasks.pop(job_id, None)\\n        if bridge and not bridge.done():\\n            bridge.cancel()\\n            with contextlib.suppress(asyncio.CancelledError):\\n                await bridge\\n\\n        try:\\n            await super().cleanup_job(job_id)\\n        finally:\\n            if is_owner and self._client:\\n                # Best-effort delete of all Redis state owned by this job.\\n                # Combined into one DEL so a single round-trip handles them.\\n                # Truly best-effort: a Redis failure here must not escape and\\n                # break stop() / explicit cancel, which is most likely to happen\\n                # exactly when Redis is unhealthy.\\n                try:\\n                    await self._client.delete(\\n                        self._stream_key(job_id),\\n                        self._owner_key(job_id),\\n                        self._activity_key(job_id),\\n                        self._public_job_key(job_id),\\n                    )\\n                except asyncio.CancelledError:\\n                    raise\\n                except Exception as exc:  # noqa: BLE001\\n                    await logger.awarning(f\\\"Redis key cleanup failed for job_id {job_id}: {exc!r}\\\")\\n                else:\\n                    await logger.adebug(f\\\"Redis keys deleted for job_id {job_id}\\\")\\n\\n    async def register_job_owner(self, job_id: str, user_id: UUID) -> None:\\n        \\\"\\\"\\\"Store the job owner in Redis for cross-worker ownership checks.\\n\\n        Raises:\\n            JobQueueBackendUnavailableError: if Redis is unreachable. Callers\\n                (route handlers) translate this into a clean HTTP 503 instead of\\n                letting a raw redis ``ConnectionError`` escape as a 500.\\n        \\\"\\\"\\\"\\n        # Write to Redis first: registering locally before a failed Redis write\\n        # would let same-worker ownership checks pass while every other worker\\n        # sees the job as unowned.\\n        try:\\n            await self._set_owner_key(job_id, user_id)\\n        except Exception as exc:\\n            if _is_backend_connection_error(exc):\\n                raise JobQueueBackendUnavailableError(self._backend_unavailable_message()) from exc\\n            raise\\n        self._job_owners[job_id] = user_id\\n        if job_id in self._queues:\\n            self._ensure_owner_refresh_task(job_id)\\n\\n    async def get_job_owner(self, job_id: str) -> UUID | None:\\n        \\\"\\\"\\\"Retrieve the job owner, checking Redis when not found locally.\\n\\n        The Redis key TTL is refreshed on every successful cross-worker lookup so\\n        that long-running builds (agent loops, large RAG ingests, etc.) do not lose\\n        their ownership anchor mid-flight. The in-memory path is not TTL-bound.\\n        \\\"\\\"\\\"\\n        local = self._job_owners.get(job_id)\\n        if local is not None:\\n            return local\\n        if self._client:\\n            owner_key = self._owner_key(job_id)\\n            try:\\n                value = await self._client.get(owner_key)\\n                if value:\\n                    from uuid import UUID as _UUID\\n\\n                    # Slide the TTL forward so builds longer than the initial TTL\\n                    # continue to pass ownership checks as long as they are polled.\\n                    await self._client.expire(owner_key, self._ttl)\\n                    return _UUID(value.decode())\\n            except Exception as exc:\\n                # A Redis outage mid-session must surface as a clean 503 at the\\n                # ownership-check endpoints, not a raw ConnectionError 500.\\n                if _is_backend_connection_error(exc):\\n                    raise JobQueueBackendUnavailableError(self._backend_unavailable_message()) from exc\\n                raise\\n        return None\\n\\n    async def register_public_job(self, job_id: str) -> None:\\n        \\\"\\\"\\\"Mark a job as public in both local memory and Redis for cross-worker access.\\n\\n        Why synchronous (not fire-and-forget): a request for the public events/cancel\\n        endpoint can land on a different worker than the one that registered the job.\\n        If the Redis write were backgrounded, that worker could run is_public_job_async\\n        before the marker exists and incorrectly 404 a legitimate public job. Awaiting\\n        the write here guarantees the marker is visible to every worker by the time\\n        build_public_tmp's response (containing job_id) reaches the client.\\n\\n        Raises:\\n            JobQueueBackendUnavailableError: if a Redis client is configured but the\\n                marker write fails. Surfacing (instead of swallowing) prevents\\n                build_public_tmp from returning a job_id that only this worker\\n                recognizes \u2014 on a multi-worker deployment that would let the public\\n                events/cancel endpoints 404 on every other worker. The caller cleans\\n                up the started job and returns a 503. With no Redis client configured\\n                (single-worker, in-memory) there is no shared marker to persist, so\\n                the base no-op success path is unchanged.\\n        \\\"\\\"\\\"\\n        await super().register_public_job(job_id)\\n        if self._client:\\n            await self._set_public_job_key(job_id)\\n\\n    async def _set_public_job_key(self, job_id: str) -> None:\\n        try:\\n            await self._client.set(self._public_job_key(job_id), b\\\"1\\\", ex=self._ttl)\\n        except Exception as exc:\\n            if _is_backend_connection_error(exc):\\n                raise JobQueueBackendUnavailableError(self._backend_unavailable_message()) from exc\\n            raise\\n\\n    async def is_public_job_async(self, job_id: str) -> bool:\\n        \\\"\\\"\\\"Return True if the job was started through the public build endpoint.\\n\\n        Checks local memory first (fast path), then falls back to Redis so that\\n        a request hitting a different worker than the one that started the build\\n        still works correctly.\\n        \\\"\\\"\\\"\\n        if super().is_public_job(job_id):\\n            return True\\n        if self._client:\\n            try:\\n                return bool(await self._client.exists(self._public_job_key(job_id)))\\n            except Exception as exc:  # noqa: BLE001\\n                await logger.awarning(f\\\"Redis public_job check failed for {job_id}: {exc!r}\\\")\\n        return False\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/jobs/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6a5c35878691c6b74fffada6b41a621ac2edd38379abe387daa3408fe9221ef6\",\"content\":\"\\\"\\\"\\\"Job service package.\\\"\\\"\\\"\\n\\nfrom langflow.services.jobs.exceptions import DuplicateJobError\\nfrom langflow.services.jobs.service import JobService\\n\\n__all__ = [\\\"DuplicateJobError\\\", \\\"JobService\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/jobs/exceptions.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"45498e07738d71f092a04c77a4f50635c8c87c09f79a10dce3cdc316cc931103\",\"content\":\"\\\"\\\"\\\"Domain exceptions for the jobs service.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\n# Durable event type a producer emits to pause a run for human input.\\nHUMAN_INPUT_REQUIRED_EVENT = \\\"human_input_required\\\"\\n\\n\\nclass JobError(RuntimeError):\\n    \\\"\\\"\\\"Base exception for job-domain errors.\\\"\\\"\\\"\\n\\n\\nclass DuplicateJobError(JobError):\\n    \\\"\\\"\\\"Raised by create_job() when a non-retryable job with the same dedupe_key already exists.\\n\\n    (QUEUED, IN_PROGRESS, or COMPLETED).\\n    FAILED and CANCELLED are retryable and do not trigger this error.\\n    Extends RuntimeError so existing except RuntimeError callers keep working.\\n    \\\"\\\"\\\"\\n\\n\\nclass PauseRequested(JobError):  # noqa: N818\\n    \\\"\\\"\\\"Raised in the runner's drive loop when a producer pauses the run for human input.\\n\\n    Carries the opaque request payload the producer (agent tool-approval or a Human\\n    Input node) filled in. The runner suspends the job (SUSPENDED, no terminal\\n    finalization) instead of completing or failing it; ``execute_with_status``\\n    re-raises it without writing a terminal status.\\n    \\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        payload: dict | None = None,\\n        request_id: str | None = None,\\n        output_events: list[dict] | None = None,\\n    ) -> None:\\n        super().__init__(\\\"Run paused for human input\\\")\\n        self.payload = payload or {}\\n        self.request_id = request_id\\n        # Terminal outputs the run captured BEFORE the pause (e.g. a fully-run\\n        # sibling branch ending in an output component). The runner stashes these\\n        # on suspend so the resumed pass \u2014 which starts a fresh capture list and\\n        # skips re-emitting already-built vertices \u2014 does not drop them.\\n        self.output_events = output_events or []\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/jobs/factory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2c7813a4c568d5f1e9ca956e6db1cf825959b601676fdccdf0a7d826f375a127\",\"content\":\"\\\"\\\"\\\"Factory for creating JobService instances.\\\"\\\"\\\"\\n\\nfrom langflow.services.factory import ServiceFactory\\nfrom langflow.services.jobs.service import JobService\\n\\n\\nclass JobServiceFactory(ServiceFactory):\\n    \\\"\\\"\\\"Factory for creating JobService instances.\\\"\\\"\\\"\\n\\n    def __init__(self):\\n        super().__init__(JobService)\\n        self._instance = None\\n\\n    def create(self):\\n        \\\"\\\"\\\"Create a JobService instance.\\n\\n        Returns:\\n            JobService instance\\n        \\\"\\\"\\\"\\n        if self._instance is None:\\n            self._instance = JobService()\\n        return self._instance\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/services/jobs/service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3feb7e71bb50a1d35cdd636a3d19448a765423a46cd7e3bd41d8deebd79baf19\",\"content\":\"\\\"\\\"\\\"Job service for managing workflow job status and tracking.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport contextlib\\nfrom typing import TYPE_CHECKING\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Sequence\\nfrom datetime import datetime, timezone\\nfrom uuid import UUID, uuid4\\n\\nfrom lfx.graph.exceptions import GraphPausedException\\nfrom lfx.observability import inject_trace_carrier\\nfrom sqlalchemy.exc import IntegrityError, OperationalError\\nfrom sqlmodel import col, func, select\\n\\nfrom langflow.services.base import Service\\nfrom langflow.services.database.models.jobs.crud import (\\n    get_latest_jobs_by_asset_ids,\\n    update_job_status,\\n)\\nfrom langflow.services.database.models.jobs.model import (\\n    ExecutionSignal,\\n    Job,\\n    JobCheckpoint,\\n    JobEvent,\\n    JobStatus,\\n    JobType,\\n    SignalType,\\n)\\nfrom langflow.services.deps import session_scope\\nfrom langflow.services.jobs.exceptions import HUMAN_INPUT_REQUIRED_EVENT, DuplicateJobError, PauseRequested\\n\\n# Bounded retries for append_event's optimistic seq assignment \u2014 contention is at most a\\n# couple of concurrent appenders per job (worker + orphan sweep, or scaled-out processes).\\n_APPEND_EVENT_MAX_RETRIES = 50\\n\\n\\ndef _unwrap_pause_payload(payload: dict | None) -> dict | None:\\n    \\\"\\\"\\\"Return the raw pause request, unwrapping the wire adapter's envelope.\\n\\n    The pause event is persisted as the wire frame the runner saw: the langflow\\n    adapter nests the raw request under ``data``, AG-UI under a ``CustomEvent``'s\\n    ``value``. Consumers (resume single-use, timeout reroute, allowed-decision\\n    gate) read ``request_id``/``timeout_seconds``/``allowed_decisions`` at the top\\n    level, so peel one envelope layer when the payload is wrapped.\\n    \\\"\\\"\\\"\\n    if not isinstance(payload, dict) or \\\"request_id\\\" in payload:\\n        return payload\\n    for key in (\\\"value\\\", \\\"data\\\"):\\n        inner = payload.get(key)\\n        if isinstance(inner, dict) and \\\"request_id\\\" in inner:\\n            return inner\\n    return payload\\n\\n\\nclass JobService(Service):\\n    \\\"\\\"\\\"Service for managing workflow jobs.\\\"\\\"\\\"\\n\\n    name = \\\"jobs_service\\\"\\n\\n    def __init__(self):\\n        \\\"\\\"\\\"Initialize the job service.\\\"\\\"\\\"\\n        self.set_ready()\\n\\n    async def get_jobs_by_flow_id(\\n        self, flow_id: UUID | str, user_id: UUID, page: int = 1, page_size: int = 10\\n    ) -> list[Job]:\\n        \\\"\\\"\\\"Get jobs for a specific flow with pagination, filtered by user.\\n\\n        Args:\\n            flow_id: The flow ID to filter jobs by\\n            user_id: The user ID to enforce ownership\\n            page: Page number (1-indexed)\\n            page_size: Number of jobs per page\\n\\n        Returns:\\n            List of Job objects for the specified flow\\n        \\\"\\\"\\\"\\n        if isinstance(flow_id, str):\\n            flow_id = UUID(flow_id)\\n\\n        async with session_scope() as session:\\n            stmt = (\\n                select(Job)\\n                .where(Job.flow_id == flow_id)\\n                .where((Job.user_id == user_id) | (Job.user_id.is_(None)))\\n                .order_by(col(Job.created_timestamp).desc())\\n                .offset((page - 1) * page_size)\\n                .limit(page_size)\\n            )\\n            result = await session.exec(stmt)\\n            return list(result.all())\\n\\n    async def get_job_by_job_id(self, job_id: UUID | str, user_id: UUID | None = None) -> Job | None:\\n        \\\"\\\"\\\"Get job for a specific job ID.\\n\\n        Args:\\n            job_id: The job ID to filter jobs by\\n            user_id: When provided, restricts the result to jobs owned by this user\\n                or legacy jobs with no owner (user_id IS NULL).\\n\\n        Returns:\\n            Job object for the specified job ID, or None if not found or not accessible\\n        \\\"\\\"\\\"\\n        if isinstance(job_id, str):\\n            job_id = UUID(job_id)\\n\\n        async with session_scope() as session:\\n            stmt = select(Job).where(Job.job_id == job_id)\\n            if user_id:\\n                stmt = stmt.where((Job.user_id == user_id) | (Job.user_id.is_(None)))\\n            result = await session.exec(stmt)\\n            return result.first()\\n\\n    async def create_job(\\n        self,\\n        job_id: UUID,\\n        flow_id: UUID,\\n        job_type: JobType = JobType.WORKFLOW,\\n        asset_id: UUID | None = None,\\n        asset_type: str | None = None,\\n        user_id: UUID | None = None,\\n        dedupe_key: str | None = None,\\n        end_user_id: str | None = None,\\n        initial_metadata: dict | None = None,\\n    ) -> Job:\\n        \\\"\\\"\\\"Create a new job record with QUEUED status.\\n\\n        Args:\\n            job_id: The job ID\\n            flow_id: The flow ID\\n            user_id: The user ID\\n            job_type: The job type\\n            asset_id: The asset ID\\n            asset_type: The asset type\\n            user_id: The user ID who owns this job\\n            dedupe_key: Optional idempotency key to prevent duplicate jobs for the same batch\\n            end_user_id: Serving-plane end-user id (the gateway header) this run belongs to,\\n                or None for editor / anonymous / feature-off runs. Recorded in\\n                ``job_metadata['end_user_id']`` (no schema change) \u2014 ``user_id`` stays the\\n                executing service account so re-enqueue/resume can still fetch the SID-owned\\n                flow, while status/stop/resume isolate on this end-user key. See F8.\\n            initial_metadata: Metadata that must be committed atomically with the QUEUED\\n                row. The background workflow facade uses this for its replay request and\\n                encrypted override envelope so a worker can never claim a partially\\n                initialized job.\\n\\n        Returns:\\n            Created Job object\\n        \\\"\\\"\\\"\\n        if isinstance(job_id, str):\\n            job_id = UUID(job_id)\\n\\n        if isinstance(flow_id, str):\\n            flow_id = UUID(flow_id)\\n\\n        async with session_scope() as session:\\n            if dedupe_key is not None:\\n                # Why: scope uniqueness to the owner \u2014 a client-controlled idempotency_key flows into\\n                # dedupe_key, so a global count would let user A collide with / DoS user B's key (and leak\\n                # its existence). Ownerless rows (single-tenant AUTO_LOGIN, user_id None) share one space.\\n                stmt = (\\n                    select(func.count())\\n                    .select_from(Job)\\n                    .where(Job.dedupe_key == dedupe_key)\\n                    # SUSPENDED included so retrying the same key while a run is paused at a HITL node\\n                    # cannot bypass dedupe and launch a second concurrent execution that races the resume.\\n                    .where(\\n                        col(Job.status).in_(\\n                            [JobStatus.QUEUED, JobStatus.IN_PROGRESS, JobStatus.SUSPENDED, JobStatus.COMPLETED]\\n                        )\\n                    )\\n                )\\n                stmt = (\\n                    stmt.where(Job.user_id == user_id)\\n                    if user_id is not None\\n                    else stmt.where(col(Job.user_id).is_(None))\\n                )\\n                result = await session.exec(stmt)\\n                if result.one() > 0:\\n                    msg = f\\\"A non-retryable job with dedupe_key={dedupe_key!r} already exists\\\"\\n                    raise DuplicateJobError(msg)\\n\\n            metadata = dict(initial_metadata or {})\\n            if end_user_id:\\n                metadata[\\\"end_user_id\\\"] = end_user_id\\n            job = Job(\\n                job_id=job_id,\\n                flow_id=flow_id,\\n                status=JobStatus.QUEUED,\\n                type=job_type,\\n                asset_id=asset_id,\\n                asset_type=asset_type,\\n                user_id=user_id,\\n                dedupe_key=dedupe_key,\\n                # Job-owned context is stamped atomically with the insert. A later shallow\\n                # update_job_metadata preserves what is already on the row.\\n                #\\n                # The end user, so serving rows carry who the run was for.\\n                #\\n                # The trace carrier, because the queued run happens after this request returns,\\n                # in a worker that may be a different process, so contextvars cannot carry the\\n                # trace there. Written once, here, and never rewritten: job_metadata is saved\\n                # back whole, and a second writer on the pause path would race this one.\\n                #\\n                # Still None when neither applies, so non-serving untraced rows stay\\n                # byte-identical to what they were.\\n                job_metadata=inject_trace_carrier(metadata) or None,\\n            )\\n            session.add(job)\\n            await session.flush()\\n            return job\\n\\n    async def update_job_status(\\n        self, job_id: UUID, status: JobStatus, *, finished_timestamp: bool = False\\n    ) -> Job | None:\\n        \\\"\\\"\\\"Update job status and optionally set finished timestamp.\\n\\n        Args:\\n            job_id: The job ID to update\\n            status: New status value\\n            finished_timestamp: If True, set finished_timestamp to current time\\n\\n        Returns:\\n            Updated Job object or None if not found\\n        \\\"\\\"\\\"\\n        async with session_scope() as session:\\n            finished_at = datetime.now(timezone.utc) if finished_timestamp else None\\n            return await update_job_status(session, job_id, status, finished_timestamp=finished_at)\\n\\n    async def update_job_metadata(\\n        self,\\n        job_id: UUID,\\n        patch: dict,\\n        *,\\n        replace: bool = False,\\n    ) -> Job | None:\\n        \\\"\\\"\\\"Merge ``patch`` into ``job.job_metadata`` (or replace it).\\n\\n        Domain-owned per-job context lives here \u2014 KB ingestion writes\\n        counters and per-item outcomes, workflow runs can record their\\n        own keys, etc. The wrapped coroutine inside\\n        ``execute_with_status`` calls this as it makes progress so the\\n        UI can read partial state without waiting for the job to\\n        finish.\\n\\n        Args:\\n            job_id: The job ID to update.\\n            patch: Top-level keys to merge into the existing dict. Keys\\n                in ``patch`` overwrite same-named keys on the existing\\n                row; nested dicts are NOT deep-merged \u2014 callers that\\n                want deep-merge semantics should read, merge, and pass\\n                the full result.\\n            replace: When ``True``, replace ``job_metadata`` outright\\n                instead of merging. Use when the caller is the sole\\n                writer and wants a known-shape blob (e.g. KB ingestion\\n                finalize).\\n\\n        Returns:\\n            The updated Job, or ``None`` if the row does not exist.\\n        \\\"\\\"\\\"\\n        async with session_scope() as session:\\n            job = await session.get(Job, job_id)\\n            if job is None:\\n                return None\\n            if replace or job.job_metadata is None:\\n                job.job_metadata = dict(patch)\\n            else:\\n                # Shallow merge \u2014 callers wanting deep-merge own the\\n                # composition. This keeps the helper predictable.\\n                job.job_metadata = {**job.job_metadata, **patch}\\n            session.add(job)\\n            await session.flush()\\n            return job\\n\\n    async def suspend_job(self, job_id: UUID, metadata: dict) -> Job | None:\\n        \\\"\\\"\\\"Atomically merge pause metadata and transition a job to ``SUSPENDED``.\\n\\n        Resume-critical metadata must become visible in the same transaction as\\n        the status transition. Otherwise a status reader can observe\\n        ``SUSPENDED`` before ``pending_request_id`` or ``pre_pause_outputs`` is\\n        committed and return an incomplete pause response.\\n\\n        Returns the updated Job, or ``None`` if the row does not exist.\\n        \\\"\\\"\\\"\\n        async with session_scope() as session:\\n            job = await session.get(Job, job_id)\\n            if job is None:\\n                return None\\n            job.job_metadata = {**(job.job_metadata or {}), **metadata}\\n            job.status = JobStatus.SUSPENDED\\n            session.add(job)\\n            await session.flush()\\n            return job\\n\\n    async def set_result(self, job_id: UUID, result: dict | None) -> Job | None:\\n        \\\"\\\"\\\"Persist the durable terminal result blob for a job.\\n\\n        ``None`` clears a previously-written result (used when a late stop\\n        reconciles a racing completion to CANCELLED and the completed-run result\\n        must not linger on the terminal row).\\n\\n        Returns the updated Job, or None if the row does not exist.\\n        \\\"\\\"\\\"\\n        async with session_scope() as session:\\n            job = await session.get(Job, job_id)\\n            if job is None:\\n                return None\\n            job.result = result\\n            session.add(job)\\n            await session.flush()\\n            return job\\n\\n    async def set_error(self, job_id: UUID, error: dict) -> Job | None:\\n        \\\"\\\"\\\"Persist the durable terminal error blob for a job.\\n\\n        Returns the updated Job, or None if the row does not exist.\\n        \\\"\\\"\\\"\\n        async with session_scope() as session:\\n            job = await session.get(Job, job_id)\\n            if job is None:\\n                return None\\n            job.error = error\\n            session.add(job)\\n            await session.flush()\\n            return job\\n\\n    async def save_checkpoint(self, job_id: UUID, kind: str, blob: str) -> None:\\n        \\\"\\\"\\\"Upsert the durable checkpoint blob for ``(job_id, kind)``.\\n\\n        ``blob`` is already-serialized text persisted verbatim \u2014 the helper never\\n        parses it, so the graph producer (JSON) and the agent saver (base64 of\\n        msgpack, LE-1447) share one API. UNIQUE(job_id, kind) keeps a single live\\n        checkpoint per kind: a second save replaces the first.\\n        \\\"\\\"\\\"\\n        # Why: a single-statement dialect upsert is atomic, so two concurrent savers (two vertices at\\n        # one pause boundary) never collide on UNIQUE(job_id, kind) \u2014 no read-then-insert race to log.\\n        now = datetime.now(timezone.utc)\\n        async with session_scope() as session:\\n            if session.get_bind().dialect.name == \\\"postgresql\\\":\\n                from sqlalchemy.dialects.postgresql import insert as _dialect_insert\\n            else:\\n                from sqlalchemy.dialects.sqlite import insert as _dialect_insert\\n            stmt = (\\n                _dialect_insert(JobCheckpoint)\\n                .values(id=uuid4(), job_id=job_id, kind=kind, blob=blob, created_at=now, updated_at=now)\\n                .on_conflict_do_update(index_elements=[\\\"job_id\\\", \\\"kind\\\"], set_={\\\"blob\\\": blob, \\\"updated_at\\\": now})\\n            )\\n            await session.exec(stmt)\\n\\n    async def load_checkpoint(self, job_id: UUID, kind: str) -> str | None:\\n        \\\"\\\"\\\"Return the stored checkpoint blob for ``(job_id, kind)``, or None if absent.\\\"\\\"\\\"\\n        async with session_scope() as session:\\n            stmt = select(JobCheckpoint).where(JobCheckpoint.job_id == job_id).where(JobCheckpoint.kind == kind)\\n            row = (await session.exec(stmt)).first()\\n            return row.blob if row is not None else None\\n\\n    async def delete_checkpoint(self, job_id: UUID, kind: str) -> None:\\n        \\\"\\\"\\\"Delete the checkpoint for ``(job_id, kind)``; no-op when none exists.\\\"\\\"\\\"\\n        async with session_scope() as session:\\n            stmt = select(JobCheckpoint).where(JobCheckpoint.job_id == job_id).where(JobCheckpoint.kind == kind)\\n            row = (await session.exec(stmt)).first()\\n            if row is not None:\\n                await session.delete(row)\\n                await session.flush()\\n\\n    async def get_pending_human_request(self, job_id: UUID) -> dict | None:\\n        async with session_scope() as session:\\n            stmt = (\\n                select(JobEvent)\\n                .where(JobEvent.job_id == job_id)\\n                .where(JobEvent.event_type == HUMAN_INPUT_REQUIRED_EVENT)\\n                .order_by(col(JobEvent.seq).desc())\\n            )\\n            row = (await session.exec(stmt)).first()\\n            return _unwrap_pause_payload(row.payload) if row is not None else None\\n\\n    async def all_checkpoints(self, kind: str) -> list[tuple[UUID, str]]:\\n        \\\"\\\"\\\"Return ``(job_id, blob)`` for every stored checkpoint of ``kind``.\\n\\n        Lets a checkpoint store resolve the cross-row ABC lookups (by checkpoint\\n        id, run id, session id) it can't express through the job-keyed helper. The\\n        set is bounded: one row per actively-suspended job, dropped on completion.\\n        \\\"\\\"\\\"\\n        async with session_scope() as session:\\n            stmt = select(JobCheckpoint).where(JobCheckpoint.kind == kind)\\n            rows = (await session.exec(stmt)).all()\\n            return [(row.job_id, row.blob) for row in rows]\\n\\n    async def append_event(self, job_id: UUID, event_type: str, payload: dict) -> int:\\n        \\\"\\\"\\\"Append a durable event for a job and return its per-job seq.\\n\\n        seq is assigned as max(existing seq for job) + 1. UNIQUE(job_id, seq)\\n        guards against concurrent double-assignment: a colliding writer hits\\n        IntegrityError, and we retry with a freshly re-read max so every event\\n        lands gap-free even when a worker and the orphan sweep (or, in the\\n        scaled backend, multiple processes) append to the same job at once.\\n        \\\"\\\"\\\"\\n        last_exc: Exception | None = None\\n        for attempt in range(_APPEND_EVENT_MAX_RETRIES):\\n            try:\\n                async with session_scope() as session:\\n                    stmt = select(func.max(JobEvent.seq)).where(JobEvent.job_id == job_id)\\n                    result = await session.exec(stmt)\\n                    current_max = result.one()\\n                    next_seq = (current_max or 0) + 1\\n                    event = JobEvent(job_id=job_id, seq=next_seq, event_type=event_type, payload=payload)\\n                    session.add(event)\\n                    await session.flush()\\n                    return next_seq\\n            except IntegrityError as exc:\\n                # Lost the (job_id, seq) race \u2014 re-read max and try again.\\n                last_exc = exc\\n            except OperationalError as exc:\\n                # SQLite \\\"database is locked\\\"/busy under concurrent writers is transient.\\n                if \\\"lock\\\" not in str(exc).lower() and \\\"busy\\\" not in str(exc).lower():\\n                    raise\\n                last_exc = exc\\n            # Yield + brief backoff so the contending writer can commit before we retry.\\n            await asyncio.sleep(min(0.05, 0.002 * (attempt + 1)))\\n        # Exhausted retries under sustained contention \u2014 surface the last collision.\\n        msg = f\\\"append_event exhausted {_APPEND_EVENT_MAX_RETRIES} retries for job {job_id} (seq contention)\\\"\\n        raise RuntimeError(msg) from last_exc\\n\\n    async def read_events(self, job_id: UUID, after_seq: int = 0) -> list[JobEvent]:\\n        \\\"\\\"\\\"Return durable events for a job with seq > after_seq, ordered by seq.\\n\\n        ``after_seq`` is the SSE Last-Event-ID cursor; pass 0 to read from the\\n        start.\\n        \\\"\\\"\\\"\\n        async with session_scope() as session:\\n            stmt = (\\n                select(JobEvent)\\n                .where(JobEvent.job_id == job_id)\\n                .where(JobEvent.seq > after_seq)\\n                .order_by(col(JobEvent.seq).asc())\\n            )\\n            result = await session.exec(stmt)\\n            return list(result.all())\\n\\n    async def write_signal(self, job_id: UUID, signal_type: SignalType, data: dict | None = None) -> ExecutionSignal:\\n        \\\"\\\"\\\"Write a control signal for a job (e.g. STOP).\\n\\n        The runner consumes it at the next vertex boundary and stamps\\n        ``consumed_at``.\\n        \\\"\\\"\\\"\\n        async with session_scope() as session:\\n            signal = ExecutionSignal(job_id=job_id, signal_type=signal_type, data=data)\\n            session.add(signal)\\n            await session.flush()\\n            await session.refresh(signal)\\n            return signal\\n\\n    async def unconsumed_signals(self, job_id: UUID) -> list[ExecutionSignal]:\\n        \\\"\\\"\\\"Return signals for a job that have not yet been consumed, oldest first.\\\"\\\"\\\"\\n        async with session_scope() as session:\\n            stmt = (\\n                select(ExecutionSignal)\\n                .where(ExecutionSignal.job_id == job_id)\\n                .where(col(ExecutionSignal.consumed_at).is_(None))\\n                .order_by(col(ExecutionSignal.created_at).asc())\\n            )\\n            result = await session.exec(stmt)\\n            return list(result.all())\\n\\n    async def consume_signals(self, job_id: UUID, signal_type: SignalType) -> int:\\n        \\\"\\\"\\\"Stamp ``consumed_at`` on a job's unconsumed signals of ``signal_type``.\\n\\n        The runner calls this once it has acted on a STOP so the signal does not\\n        linger: ``unconsumed_signals`` filters on ``consumed_at IS NULL``, so an\\n        unstamped STOP would (a) grow the table forever and (b) make a later\\n        re-enqueued run of the same job self-cancel off the stale signal. Returns\\n        the number of rows stamped.\\n        \\\"\\\"\\\"\\n        now = datetime.now(timezone.utc)\\n        async with session_scope() as session:\\n            stmt = (\\n                select(ExecutionSignal)\\n                .where(ExecutionSignal.job_id == job_id)\\n                .where(ExecutionSignal.signal_type == signal_type)\\n                .where(col(ExecutionSignal.consumed_at).is_(None))\\n            )\\n            result = await session.exec(stmt)\\n            rows = list(result.all())\\n            for row in rows:\\n                row.consumed_at = now\\n                session.add(row)\\n            await session.flush()\\n            return len(rows)\\n\\n    async def heartbeat(self, job_id: UUID, owner: str) -> None:\\n        \\\"\\\"\\\"Stamp the running owner + a fresh heartbeat on the job row.\\n\\n        This is the liveness signal a reconciler reads to tell a live in-flight\\n        run from a genuinely orphaned one: only the running owner refreshes it,\\n        and a reconciler only fails/requeues a job whose heartbeat is STALE\\n        (``is_lease_stale``). Stored in ``job_metadata`` (no new column, matching\\n        the attempt-accounting decision in the design) via a shallow merge so the\\n        persisted request / retry flags are preserved.\\n        \\\"\\\"\\\"\\n        now = datetime.now(timezone.utc).isoformat()\\n        await self.update_job_metadata(job_id, {\\\"owner\\\": owner, \\\"heartbeat_at\\\": now})\\n\\n    @staticmethod\\n    def is_lease_stale(job: Job, *, lease_ttl_s: float) -> bool:\\n        \\\"\\\"\\\"True when a job's heartbeat is older than ``lease_ttl_s`` (or absent).\\n\\n        An absent heartbeat means the owner never recorded liveness (it died in\\n        the QUEUED->IN_PROGRESS window, or this is a legacy row), so it is\\n        treated as stale and reconcilable. A fresh heartbeat (within the TTL)\\n        means a live owner is running the job and a reconciler must NOT touch it.\\n        \\\"\\\"\\\"\\n        meta = job.job_metadata or {}\\n        raw = meta.get(\\\"heartbeat_at\\\")\\n        if not raw:\\n            return True\\n        try:\\n            hb = datetime.fromisoformat(raw)\\n        except (TypeError, ValueError):\\n            return True\\n        if hb.tzinfo is None:\\n            hb = hb.replace(tzinfo=timezone.utc)\\n        age = (datetime.now(timezone.utc) - hb).total_seconds()\\n        return age > lease_ttl_s\\n\\n    async def increment_attempt_if(self, job_id: UUID, *, expected: int, new: int) -> bool:\\n        \\\"\\\"\\\"Atomically bump ``job_metadata.attempt`` from ``expected`` to ``new``.\\n\\n        Returns True only for the single caller whose read-modify-write observed\\n        ``attempt == expected`` and committed. Concurrent reconcilers reading the\\n        same ``expected`` race on the row, but UNIQUE row identity + a re-read\\n        under the write lock means only one transaction's conditional UPDATE\\n        matches: every other sees ``rowcount == 0`` and returns False. This\\n        closes the lost-update window where two reconcilers both bumped 1->2 and\\n        each requeued, pushing a job past ``max_attempts``.\\n\\n        Portable across SQLite and Postgres: the conditional UPDATE matches the\\n        JSON-extracted attempt cast to integer, the same single-row-conditional\\n        primitive ``claim_queued_job`` relies on.\\n        \\\"\\\"\\\"\\n        from sqlalchemy import Integer\\n        from sqlalchemy import cast as sa_cast\\n        from sqlmodel import update\\n\\n        attempt_expr = sa_cast(col(Job.job_metadata)[\\\"attempt\\\"].as_string(), Integer)\\n        async with session_scope() as session:\\n            # Read the current metadata so we can write back a full merged blob\\n            # (JSON columns are replaced wholesale, not patched in place).\\n            job = await session.get(Job, job_id)\\n            if job is None:\\n                return False\\n            merged = {**(job.job_metadata or {}), \\\"attempt\\\": new}\\n            stmt = update(Job).where(Job.job_id == job_id, attempt_expr == expected).values(job_metadata=merged)\\n            result = await session.exec(stmt)  # type: ignore[call-overload]\\n            await session.flush()\\n            return result.rowcount == 1\\n\\n    async def retry_requeue_claim(self, job_id: UUID, *, expected_attempt: int) -> bool:\\n        \\\"\\\"\\\"Atomically bump ``attempt`` AND flip IN_PROGRESS->QUEUED for a retry requeue.\\n\\n        A SINGLE conditional UPDATE guarded by BOTH ``attempt == expected_attempt``\\n        AND ``status == IN_PROGRESS``. The winner sets ``attempt = expected+1`` and\\n        ``status = QUEUED`` in one statement; every racing reconciler then sees\\n        either a changed attempt or a non-IN_PROGRESS status and gets\\n        ``rowcount == 0``. This closes the window that a separate increment +\\n        ``update_job_status(QUEUED)`` left open, where a second reconciler could\\n        read the already-bumped attempt on a still-IN_PROGRESS row and bump it\\n        again past ``max_attempts``. Portable across SQLite and Postgres.\\n        \\\"\\\"\\\"\\n        from sqlalchemy import Integer\\n        from sqlalchemy import cast as sa_cast\\n        from sqlmodel import update\\n\\n        attempt_expr = sa_cast(col(Job.job_metadata)[\\\"attempt\\\"].as_string(), Integer)\\n        async with session_scope() as session:\\n            job = await session.get(Job, job_id)\\n            if job is None:\\n                return False\\n            merged = {**(job.job_metadata or {}), \\\"attempt\\\": expected_attempt + 1}\\n            stmt = (\\n                update(Job)\\n                .where(\\n                    Job.job_id == job_id,\\n                    attempt_expr == expected_attempt,\\n                    Job.status == JobStatus.IN_PROGRESS,\\n                )\\n                .values(job_metadata=merged, status=JobStatus.QUEUED)\\n            )\\n            result = await session.exec(stmt)  # type: ignore[call-overload]\\n            await session.flush()\\n            return result.rowcount == 1\\n\\n    async def claim_queued_lease(\\n        self,\\n        job_id: UUID,\\n        *,\\n        owner: str,\\n        lease_ttl_s: float,\\n        heartbeat_at: str | None = None,\\n    ) -> bool:\\n        \\\"\\\"\\\"Lease-claim a QUEUED row WITHOUT flipping its status. Returns True if won.\\n\\n        Single-flight ownership for the default re-enqueue path that, unlike\\n        ``claim_queued_job``, does NOT move the row to IN_PROGRESS. Keeping the\\n        row QUEUED means a re-enqueue that crashes before the runner emits its\\n        first transition leaves the job re-runnable (the sweep never fails QUEUED\\n        rows, and the next boot re-claims it once this lease goes stale) instead\\n        of becoming a stranded IN_PROGRESS that gets failed worker_lost. The\\n        runner's ``execute_with_status`` performs the real QUEUED->IN_PROGRESS\\n        flip when it actually starts.\\n\\n        The claim succeeds only when the row is QUEUED and its current lease is\\n        absent or stale, and the conditional UPDATE matches the EXACT prior\\n        ``heartbeat_at`` we read, so two workers racing the same stale row see\\n        only one ``rowcount == 1``. A caller-supplied ``heartbeat_at`` becomes\\n        the claim token for a later guarded release or terminalization. Portable\\n        across SQLite and Postgres.\\n        \\\"\\\"\\\"\\n        from sqlmodel import update\\n\\n        hb_expr = col(Job.job_metadata)[\\\"heartbeat_at\\\"].as_string()\\n        claim_heartbeat = heartbeat_at or datetime.now(timezone.utc).isoformat()\\n        async with session_scope() as session:\\n            job = await session.get(Job, job_id)\\n            if job is None or job.status != JobStatus.QUEUED:\\n                return False\\n            meta = job.job_metadata or {}\\n            prior_hb = meta.get(\\\"heartbeat_at\\\")\\n            # A fresh lease means another worker already owns this claim window.\\n            if not self.is_lease_stale(job, lease_ttl_s=lease_ttl_s):\\n                return False\\n            merged = {**meta, \\\"owner\\\": owner, \\\"heartbeat_at\\\": claim_heartbeat}\\n            # Guard on the exact prior heartbeat so a concurrent claimer that\\n            # already stamped its own loses the conditional UPDATE.\\n            guard = hb_expr.is_(None) if prior_hb is None else hb_expr == prior_hb\\n            stmt = (\\n                update(Job)\\n                .where(Job.job_id == job_id, Job.status == JobStatus.QUEUED, guard)\\n                .values(job_metadata=merged)\\n            )\\n            result = await session.exec(stmt)  # type: ignore[call-overload]\\n            await session.flush()\\n            return result.rowcount == 1\\n\\n    async def release_queued_lease(self, job_id: UUID, *, owner: str, heartbeat_at: str) -> bool:\\n        \\\"\\\"\\\"Release this owner's QUEUED lease without clearing a newer claim.\\n\\n        The status, owner, and exact heartbeat guards make the whole-metadata\\n        replacement safe across SQLite and Postgres: a worker that has replaced\\n        or refreshed this lease cannot have its claim erased by a stale recovery.\\n        \\\"\\\"\\\"\\n        from sqlmodel import update\\n\\n        owner_expr = col(Job.job_metadata)[\\\"owner\\\"].as_string()\\n        hb_expr = col(Job.job_metadata)[\\\"heartbeat_at\\\"].as_string()\\n        async with session_scope() as session:\\n            job = await session.get(Job, job_id)\\n            if job is None or job.status != JobStatus.QUEUED:\\n                return False\\n            metadata = dict(job.job_metadata or {})\\n            if metadata.get(\\\"owner\\\") != owner or metadata.get(\\\"heartbeat_at\\\") != heartbeat_at:\\n                return False\\n            metadata.pop(\\\"owner\\\", None)\\n            metadata.pop(\\\"heartbeat_at\\\", None)\\n            stmt = (\\n                update(Job)\\n                .where(\\n                    Job.job_id == job_id,\\n                    Job.status == JobStatus.QUEUED,\\n                    owner_expr == owner,\\n                    hb_expr == heartbeat_at,\\n                )\\n                .values(job_metadata=metadata or None)\\n            )\\n            result = await session.exec(stmt)  # type: ignore[call-overload]\\n            await session.flush()\\n            return result.rowcount == 1\\n\\n    async def fail_queued_job(\\n        self,\\n        job_id: UUID,\\n        *,\\n        owner: str,\\n        heartbeat_at: str,\\n        error: dict,\\n        event_type: str,\\n    ) -> bool:\\n        \\\"\\\"\\\"Atomically terminalize this owner's QUEUED claim with its durable event.\\n\\n        The entire status-CAS + event transaction is retried after a per-job\\n        sequence collision or transient SQLite writer lock. Rolling back before\\n        each retry leaves the job QUEUED under the exact original lease, so a\\n        retry either commits both records or safely loses to a newer claim.\\n        \\\"\\\"\\\"\\n        from sqlmodel import update\\n\\n        owner_expr = col(Job.job_metadata)[\\\"owner\\\"].as_string()\\n        hb_expr = col(Job.job_metadata)[\\\"heartbeat_at\\\"].as_string()\\n        last_exc: Exception | None = None\\n        for attempt in range(_APPEND_EVENT_MAX_RETRIES):\\n            try:\\n                async with session_scope() as session:\\n                    job = await session.get(Job, job_id)\\n                    if job is None or job.status != JobStatus.QUEUED:\\n                        return False\\n                    metadata = job.job_metadata or {}\\n                    if metadata.get(\\\"owner\\\") != owner or metadata.get(\\\"heartbeat_at\\\") != heartbeat_at:\\n                        return False\\n                    stmt = (\\n                        update(Job)\\n                        .where(\\n                            Job.job_id == job_id,\\n                            Job.status == JobStatus.QUEUED,\\n                            owner_expr == owner,\\n                            hb_expr == heartbeat_at,\\n                        )\\n                        .values(\\n                            status=JobStatus.FAILED,\\n                            error=dict(error),\\n                            finished_timestamp=datetime.now(timezone.utc),\\n                        )\\n                    )\\n                    result = await session.exec(stmt)  # type: ignore[call-overload]\\n                    if result.rowcount != 1:\\n                        return False\\n                    current_max = (\\n                        await session.exec(select(func.max(JobEvent.seq)).where(JobEvent.job_id == job_id))\\n                    ).one()\\n                    session.add(\\n                        JobEvent(\\n                            job_id=job_id,\\n                            seq=(current_max or 0) + 1,\\n                            event_type=event_type,\\n                            payload=dict(error),\\n                        )\\n                    )\\n                    await session.flush()\\n                    return True\\n            except IntegrityError as exc:\\n                last_exc = exc\\n            except OperationalError as exc:\\n                if \\\"lock\\\" not in str(exc).lower() and \\\"busy\\\" not in str(exc).lower():\\n                    raise\\n                last_exc = exc\\n            await asyncio.sleep(min(0.05, 0.002 * (attempt + 1)))\\n\\n        msg = f\\\"fail_queued_job exhausted {_APPEND_EVENT_MAX_RETRIES} retries for job {job_id} (event seq contention)\\\"\\n        raise RuntimeError(msg) from last_exc\\n\\n    async def claim_suspended_for_resume(self, job_id: UUID, *, owner: str | None = None) -> bool:\\n        \\\"\\\"\\\"Atomically flip SUSPENDED->IN_PROGRESS for resume; True iff this caller won.\\n\\n        The single conditional ``UPDATE ... WHERE status = SUSPENDED`` is the single-use\\n        primitive: only one concurrent resume gets ``rowcount == 1``. Going straight to\\n        IN_PROGRESS (with a fresh heartbeat) means a racing startup sweep sees a non-QUEUED,\\n        live row and cannot double-enqueue it.\\n        \\\"\\\"\\\"\\n        from sqlmodel import update\\n\\n        now = datetime.now(timezone.utc).isoformat()\\n        async with session_scope() as session:\\n            job = await session.get(Job, job_id)\\n            if job is None:\\n                return False\\n            merged = {**(job.job_metadata or {})}\\n            if owner is not None:\\n                merged.update({\\\"owner\\\": owner, \\\"heartbeat_at\\\": now})\\n            stmt = (\\n                update(Job)\\n                .where(Job.job_id == job_id, Job.status == JobStatus.SUSPENDED)\\n                .values(status=JobStatus.IN_PROGRESS, job_metadata=merged)\\n            )\\n            result = await session.exec(stmt)  # type: ignore[call-overload]\\n            await session.flush()\\n            return result.rowcount == 1\\n\\n    async def claim_suspended_for_cancel(self, job_id: UUID) -> bool:\\n        \\\"\\\"\\\"Atomically flip SUSPENDED->CANCELLED; True iff this caller won.\\n\\n        Mirror of ``claim_suspended_for_resume`` for the supersede/stop side of the\\n        race: a resume that already flipped the row to IN_PROGRESS keeps its run \u2014\\n        an unconditional CANCELLED write here would clobber it and destroy its\\n        checkpoint mid-flight.\\n        \\\"\\\"\\\"\\n        from sqlmodel import update\\n\\n        async with session_scope() as session:\\n            stmt = (\\n                update(Job)\\n                .where(Job.job_id == job_id, Job.status == JobStatus.SUSPENDED)\\n                .values(status=JobStatus.CANCELLED, finished_timestamp=datetime.now(timezone.utc))\\n            )\\n            result = await session.exec(stmt)  # type: ignore[call-overload]\\n            await session.flush()\\n            return result.rowcount == 1\\n\\n    async def queued_workflow_job_ids(self) -> list[UUID]:\\n        \\\"\\\"\\\"Return the ids of every QUEUED workflow job (for strand recovery).\\\"\\\"\\\"\\n        async with session_scope() as session:\\n            stmt = select(Job.job_id).where(\\n                Job.status == JobStatus.QUEUED,\\n                Job.type == JobType.WORKFLOW,\\n            )\\n            result = await session.exec(stmt)\\n            return list(result.all())\\n\\n    async def claim_queued_job(self, job_id: UUID) -> bool:\\n        \\\"\\\"\\\"Atomically claim a QUEUED job for execution. Returns True if we won.\\n\\n        Single-flight guard for the startup sweep: a conditional\\n        ``UPDATE job SET status=IN_PROGRESS WHERE job_id=? AND status='QUEUED'``\\n        means only ONE racer's update affects a row (``rowcount == 1``); every\\n        other concurrent sweeper sees ``rowcount == 0`` and must not enqueue.\\n        Works identically on SQLite and Postgres (a single-row conditional UPDATE\\n        is atomic on both), so two uvicorn workers booting against one DB cannot\\n        both re-run the same non-idempotent QUEUED job.\\n        \\\"\\\"\\\"\\n        from sqlmodel import update\\n\\n        async with session_scope() as session:\\n            stmt = (\\n                update(Job)\\n                .where(Job.job_id == job_id, Job.status == JobStatus.QUEUED)\\n                .values(status=JobStatus.IN_PROGRESS)\\n            )\\n            result = await session.exec(stmt)  # type: ignore[call-overload]\\n            await session.flush()\\n            return result.rowcount == 1\\n\\n    async def sweep_orphans(self, *, lease_ttl_s: float = 30.0) -> list[UUID]:\\n        \\\"\\\"\\\"Reconcile GENUINELY orphaned IN_PROGRESS jobs (stale/absent heartbeat).\\n\\n        Liveness-aware: only an IN_PROGRESS row whose heartbeat is older than\\n        ``lease_ttl_s`` (or never recorded) is treated as orphaned. A row with a\\n        FRESH heartbeat means a live owner is mid-run, so the sweep must NOT\\n        touch it \u2014 this is what stops a booting worker B from flipping worker A's\\n        actively-running job FAILED(worker_lost) under ``gunicorn -w N``.\\n\\n        For a real orphan, mark it FAILED with a worker_lost error, stamp\\n        finished_timestamp, and append a terminal ``run_failed`` event so a\\n        reattacher always sees a clean end. QUEUED jobs are intentionally\\n        untouched (at-least-once: they get re-picked by a fresh worker).\\n\\n        Returns the ids of the jobs transitioned to FAILED.\\n        \\\"\\\"\\\"\\n        from sqlmodel import update\\n\\n        error_payload = {\\\"type\\\": \\\"worker_lost\\\"}\\n        reconciled: list[UUID] = []\\n        async with session_scope() as session:\\n            stmt = select(Job).where(Job.status == JobStatus.IN_PROGRESS)\\n            result = await session.exec(stmt)\\n            in_progress = list(result.all())\\n            now = datetime.now(timezone.utc)\\n            hb_expr = col(Job.job_metadata)[\\\"heartbeat_at\\\"].as_string()\\n            for job in in_progress:\\n                if not self.is_lease_stale(job, lease_ttl_s=lease_ttl_s):\\n                    # Live owner still heartbeating \u2014 leave the run alone.\\n                    continue\\n                prior_heartbeat = (job.job_metadata or {}).get(\\\"heartbeat_at\\\")\\n                heartbeat_unchanged = hb_expr.is_(None) if prior_heartbeat is None else hb_expr == prior_heartbeat\\n                claim = (\\n                    update(Job)\\n                    .where(\\n                        Job.job_id == job.job_id,\\n                        Job.status == JobStatus.IN_PROGRESS,\\n                        heartbeat_unchanged,\\n                    )\\n                    .values(\\n                        status=JobStatus.FAILED,\\n                        error=dict(error_payload),\\n                        finished_timestamp=now,\\n                    )\\n                )\\n                claim_result = await session.exec(claim)  # type: ignore[call-overload]\\n                if claim_result.rowcount == 1:\\n                    reconciled.append(job.job_id)\\n            await session.flush()\\n        # Why: append the terminal milestone via append_event (own session) so its seq-collision retry\\n        # applies \u2014 a collision with a concurrent appender can no longer roll back the whole sweep.\\n        for job_id in reconciled:\\n            await self.append_event(job_id, \\\"run_failed\\\", dict(error_payload))\\n        return reconciled\\n\\n    async def sweep_input_deadlines(self) -> list[UUID]:\\n        \\\"\\\"\\\"FAIL SUSPENDED runs whose human-input deadline has passed (LE-1452).\\n\\n        A separate pass from ``sweep_orphans`` (which only touches IN_PROGRESS): selects\\n        SUSPENDED rows carrying an ``input_deadline_at`` in ``job_metadata`` that is now\\n        in the past and writes a terminal FAILED status with an ``input_timed_out`` error\\n        plus a durable terminal event, so a reattaching client sees a clean end. Rows\\n        without a stamped deadline (the setting was off at suspend) are left untouched.\\n\\n        Returns the ids transitioned to FAILED.\\n        \\\"\\\"\\\"\\n        from sqlmodel import update\\n\\n        error_payload = {\\\"type\\\": \\\"input_timed_out\\\"}\\n        reconciled: list[UUID] = []\\n        async with session_scope() as session:\\n            result = await session.exec(select(Job).where(Job.status == JobStatus.SUSPENDED))\\n            now = datetime.now(timezone.utc)\\n            deadline_expr = col(Job.job_metadata)[\\\"input_deadline_at\\\"].as_string()\\n            for job in result.all():\\n                deadline = (job.job_metadata or {}).get(\\\"input_deadline_at\\\")\\n                if not deadline or self._parse_deadline(deadline) is None or self._parse_deadline(deadline) > now:\\n                    continue\\n                # A resume, a newer pause, or another sweeper can win after the\\n                # SEL";
